class ОшибкаОтчёта(RuntimeError):
    """Ошибка публикационно проверяемого контракта отчёта."""


class _ВызовыВидимыхАтрибутовДарвина:
    """FD-вызовы Darwin; этот объект не открывает и не закрывает файлы."""

    _предел_списка = 64 * 1024
    _предел_имени = 127
    _предел_числа = 128
    _предел_значения = 1024 * 1024
    _предел_всех_значений = 4 * 1024 * 1024

    def __init__(сам):
        if sys.platform != 'darwin':
            raise ОшибкаОтчёта('нет допущенного backend видимых атрибутов')
        import ctypes

        сам._типы = ctypes
        try:
            библиотека = ctypes.CDLL(None, use_errno=True)
            сам._список = библиотека.flistxattr
            сам._чтение = библиотека.fgetxattr
            сам._запись = библиотека.fsetxattr
        except (AttributeError, OSError) as ошибка:
            raise ОшибкаОтчёта('нет требуемых FD-вызовов видимых атрибутов') from ошибка
        сам._библиотека = библиотека
        сам._список.argtypes = [ctypes.c_int, ctypes.c_void_p, ctypes.c_size_t, ctypes.c_int]
        сам._список.restype = ctypes.c_ssize_t
        сам._чтение.argtypes = [
            ctypes.c_int, ctypes.c_char_p, ctypes.c_void_p, ctypes.c_size_t,
            ctypes.c_uint32, ctypes.c_int,
        ]
        сам._чтение.restype = ctypes.c_ssize_t
        сам._запись.argtypes = [
            ctypes.c_int, ctypes.c_char_p, ctypes.c_void_p, ctypes.c_size_t,
            ctypes.c_uint32, ctypes.c_int,
        ]
        сам._запись.restype = ctypes.c_int

    def _ошибка_вызова(сам):
        номер = сам._типы.get_errno()
        return OSError(номер, 'не удалось обработать видимые атрибуты FD')

    def имена(сам, дескриптор):
        типы = сам._типы
        размер = сам._список(дескриптор, None, 0, 0)
        if размер < 0:
            raise сам._ошибка_вызова()
        if размер > сам._предел_списка:
            raise ОшибкаОтчёта('превышен предел списка видимых атрибутов')
        буфер = типы.create_string_buffer(max(размер, 1))
        прочитано = сам._список(
            дескриптор, типы.cast(буфер, типы.c_void_p), max(размер, 1), 0)
        if прочитано < 0:
            raise сам._ошибка_вызова()
        if прочитано != размер:
            raise ОшибкаОтчёта('список видимых атрибутов изменился при чтении')
        if размер == 0:
            return ()
        байты = буфер.raw[:размер]
        if not байты.endswith(b'\0'):
            raise ОшибкаОтчёта('неполный список видимых атрибутов')
        имена = байты[:-1].split(b'\0')
        if (len(имена) > сам._предел_числа or len(set(имена)) != len(имена)
            or any(not имя or len(имя) > сам._предел_имени for имя in имена)):
            raise ОшибкаОтчёта('неверные имена видимых атрибутов')
        if any(имя in (b'com.apple.ResourceFork', b'com.apple.decmpfs') for имя in имена):
            raise ОшибкаОтчёта('неподдерживаемые ресурсная вилка или сжатие')
        try:
            for имя in имена:
                имя.decode('utf-8')
        except UnicodeError as ошибка:
            raise ОшибкаОтчёта('неверная кодировка имени видимого атрибута') from ошибка
        return tuple(sorted(имена))

    def значение(сам, дескриптор, имя, остаток):
        типы = сам._типы
        размер = сам._чтение(дескриптор, имя, None, 0, 0, 0)
        if размер < 0:
            raise сам._ошибка_вызова()
        if размер > сам._предел_значения or размер > остаток:
            raise ОшибкаОтчёта('превышен предел видимых атрибутов')
        буфер = типы.create_string_buffer(max(размер, 1))
        прочитано = сам._чтение(
            дескриптор, имя, типы.cast(буфер, типы.c_void_p), max(размер, 1), 0, 0)
        if прочитано < 0:
            raise сам._ошибка_вызова()
        if прочитано != размер:
            raise ОшибкаОтчёта('видимый атрибут изменился при чтении')
        return буфер.raw[:размер]

    def снять(сам, дескриптор):
        имена = сам.имена(дескриптор)
        остаток = сам._предел_всех_значений
        результат = []
        for имя in имена:
            значение = сам.значение(дескриптор, имя, остаток)
            остаток -= len(значение)
            результат.append((имя, значение))
        if сам.имена(дескриптор) != имена:
            raise ОшибкаОтчёта('список видимых атрибутов изменился')
        return tuple(результат)

    def создать(сам, дескриптор, имя, значение):
        типы = сам._типы
        буфер = типы.create_string_buffer(значение)
        # XATTR_CREATE: не заменять неожиданно появившийся атрибут.
        итог = сам._запись(
            дескриптор, имя, типы.cast(буфер, типы.c_void_p), len(значение), 0, 0x0002)
        if итог < 0:
            raise сам._ошибка_вызова()
        if итог != 0:
            raise ОшибкаОтчёта('неизвестен результат записи видимого атрибута')


class _ОпытныйПереносВидимыхАтрибутов:
    """Однократный FD-перенос доступных xattr; не владеет FD и не делает rename.

    Вызывающий обеспечивает закрытый ACL/namespace и удерживает оба FD и этот
    объект до известного исхода; другие процессы того же UID не исключаются FD.
    Вход одного закреплённого потока не должен вызываться повторно из handler.
    ACL, скрытые атрибуты, содержимое, fsync и публикация не подтверждаются.
    """

    def __init__(сам, система, источник, назначение):
        if (type(система) is not _ВызовыВидимыхАтрибутовДарвина
            or type(источник) is not int or type(назначение) is not int
            or источник < 0 or назначение < 0 or источник == назначение):
            raise ОшибкаОтчёта('неверные опоры видимых атрибутов')
        сам._система = система
        сам._источник = источник
        сам._назначение = назначение
        сам._процесс = os.getpid()
        сам._поток = threading.current_thread()
        сам.состояние = 'готов'
        сам.ошибка = None
        сам.попытка = None
        сам.подтверждено = 0

    def выполнить(сам):
        if (os.getpid() != сам._процесс or threading.current_thread() is not сам._поток
            or сам.состояние != 'готов'):
            raise ОшибкаОтчёта('повтор или чужой владелец переноса видимых атрибутов')
        def исходная_метка(с):
            return (с.st_dev, с.st_ino, с.st_mode, с.st_uid, с.st_gid, с.st_nlink,
                    с.st_size, с.st_mtime_ns, с.st_ctime_ns, с.st_flags)
        def метка_назначения(с):
            return (с.st_dev, с.st_ino, с.st_mode, с.st_uid, с.st_gid, с.st_nlink,
                    с.st_size, с.st_mtime_ns, с.st_flags)
        try:
            сам.состояние = 'сверка'
            for дескриптор, доступы in (
                (сам._источник, (os.O_RDONLY, os.O_RDWR)),
                (сам._назначение, (os.O_RDWR,)),
            ):
                доступ = fcntl.fcntl(дескриптор, fcntl.F_GETFL) & os.O_ACCMODE
                if (доступ not in доступы
                    or not fcntl.fcntl(дескриптор, fcntl.F_GETFD) & fcntl.FD_CLOEXEC):
                    raise ОшибкаОтчёта('неверный доступ к FD видимых атрибутов')
            исходный = os.fstat(сам._источник)
            временный = os.fstat(сам._назначение)
            if (not stat.S_ISREG(исходный.st_mode) or not stat.S_ISREG(временный.st_mode)
                or исходный.st_nlink != 1 or временный.st_nlink != 1
                or (исходный.st_dev, исходный.st_ino) == (временный.st_dev, временный.st_ino)
                or (исходный.st_dev, исходный.st_uid, исходный.st_gid)
                   != (временный.st_dev, временный.st_uid, временный.st_gid)
                or stat.S_IMODE(исходный.st_mode) & 0o7000
                or stat.S_IMODE(временный.st_mode) != 0o600
                or исходный.st_flags != 0 or временный.st_flags != 0):
                raise ОшибкаОтчёта('неверные исходный или временный inode видимых атрибутов')
            метка_источника = исходная_метка(исходный)
            метка_временного = метка_назначения(временный)
            исходные = сам._система.снять(сам._источник)
            if сам._система.снять(сам._назначение):
                raise ОшибкаОтчёта('временный inode уже имеет видимые атрибуты')
            if (исходная_метка(os.fstat(сам._источник)) != метка_источника
                or метка_назначения(os.fstat(сам._назначение)) != метка_временного):
                raise ОшибкаОтчёта('inode изменился до переноса видимых атрибутов')
            for имя, значение in исходные:
                сам.попытка = (имя, 'начата')
                сам._система.создать(сам._назначение, имя, значение)
                сам.попытка = (имя, 'подтверждена')
                сам.подтверждено += 1
            if (сам._система.снять(сам._назначение) != исходные
                or сам._система.снять(сам._источник) != исходные
                or исходная_метка(os.fstat(сам._источник)) != метка_источника
                or метка_назначения(os.fstat(сам._назначение)) != метка_временного):
                raise ОшибкаОтчёта('перенос видимых атрибутов не подтверждён')
            сам.состояние = 'подтверждено'
            return сам.подтверждено
        except BaseException as ошибка:
            сам.ошибка = ошибка
            сам.состояние = 'неизвестно' if сам.попытка is not None else 'отказ до записи'
            raise


class _ВызовыСписковДоступаДарвина:
    """Ограниченный Darwin ABI; не открывает и не закрывает файловые FD.

    Признак FILESEC_ACL после успешного fstatx трактуется только в заранее
    проверенном вызывающим профиле файловой системы. Скрытые ACL и полнота
    представления внешних данных этим интерфейсом не доказываются.
    """

    _предел_байтов = 64 * 1024
    _предел_объектов = 16

    def __init__(сам):
        if sys.platform != 'darwin' or os.uname().machine != 'arm64':
            raise ОшибкаОтчёта('нет допущенного ABI списков доступа')
        import ctypes

        if (ctypes.sizeof(ctypes.c_void_p) != 8 or ctypes.sizeof(ctypes.c_long) != 8
            or sys.byteorder != 'little'):
            raise ОшибкаОтчёта('неверная разрядность ABI списков доступа')

        class Время(ctypes.Structure):
            _fields_ = [('секунды', ctypes.c_int64), ('наносекунды', ctypes.c_int64)]

        class Сведения(ctypes.Structure):
            _fields_ = [
                ('устройство', ctypes.c_int32), ('режим', ctypes.c_uint16),
                ('ссылки', ctypes.c_uint16), ('инод', ctypes.c_uint64),
                ('владелец', ctypes.c_uint32), ('группа', ctypes.c_uint32),
                ('тип_устройства', ctypes.c_int32), ('доступ', Время),
                ('изменение', Время), ('состояние', Время), ('создание', Время),
                ('размер', ctypes.c_int64), ('блоки', ctypes.c_int64),
                ('размер_блока', ctypes.c_int32), ('флаги', ctypes.c_uint32),
                ('поколение', ctypes.c_uint32), ('резерв', ctypes.c_int32),
                ('резервные_слова', ctypes.c_int64 * 2),
            ]

        смещения = tuple(getattr(Сведения, имя).offset for имя in (
            'устройство', 'режим', 'ссылки', 'инод', 'владелец', 'группа',
            'тип_устройства', 'доступ', 'изменение', 'состояние', 'создание',
            'размер', 'блоки', 'размер_блока', 'флаги', 'поколение', 'резерв',
            'резервные_слова'))
        if (ctypes.sizeof(Время) != 16 or ctypes.sizeof(Сведения) != 144
            or ctypes.alignment(Сведения) != 8
            or смещения != (0, 4, 6, 8, 16, 20, 24, 32, 48, 64, 80,
                           96, 104, 112, 116, 120, 124, 128)):
            raise ОшибкаОтчёта('неверная структура stat для списков доступа')

        сам._типы = ctypes
        сам._сведения = Сведения
        сам._ресурсы = []
        сам._занято = False
        try:
            библиотека = ctypes.CDLL(None, use_errno=True)
            сам._начать_безопасность = библиотека.filesec_init
            сам._кончить_безопасность = библиотека.filesec_free
            сам._стат = библиотека.fstatx_np
            сам._наличие = библиотека.filesec_query_property
            сам._взять_список = библиотека.acl_get_fd_np
            сам._размер_списка = библиотека.acl_size
            сам._копия_списка = библиотека.acl_copy_ext
            сам._установить_список = библиотека.acl_set_fd_np
            сам._кончить_список = библиотека.acl_free
        except (AttributeError, OSError) as ошибка:
            raise ОшибкаОтчёта('нет требуемых Darwin вызовов списков доступа') from ошибка
        сам._библиотека = библиотека
        сам._начать_безопасность.argtypes = []
        сам._начать_безопасность.restype = ctypes.c_void_p
        сам._кончить_безопасность.argtypes = [ctypes.c_void_p]
        сам._кончить_безопасность.restype = None
        сам._стат.argtypes = [ctypes.c_int, ctypes.POINTER(Сведения), ctypes.c_void_p]
        сам._стат.restype = ctypes.c_int
        сам._наличие.argtypes = [ctypes.c_void_p, ctypes.c_int, ctypes.POINTER(ctypes.c_int)]
        сам._наличие.restype = ctypes.c_int
        сам._взять_список.argtypes = [ctypes.c_int, ctypes.c_int]
        сам._взять_список.restype = ctypes.c_void_p
        сам._размер_списка.argtypes = [ctypes.c_void_p]
        сам._размер_списка.restype = ctypes.c_ssize_t
        сам._копия_списка.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.c_ssize_t]
        сам._копия_списка.restype = ctypes.c_ssize_t
        сам._установить_список.argtypes = [ctypes.c_int, ctypes.c_void_p, ctypes.c_int]
        сам._установить_список.restype = ctypes.c_int
        сам._кончить_список.argtypes = [ctypes.c_void_p]
        сам._кончить_список.restype = ctypes.c_int

    def _ошибка_вызова(сам):
        return OSError(сам._типы.get_errno() or errno.EIO, 'ошибка работы со списком доступа FD')

    def _получить_объект(сам, вид, операция, *аргументы):
        if len(сам._ресурсы) >= сам._предел_объектов:
            raise ОшибкаОтчёта('превышен предел объектов списков доступа')
        запись = {'вид': вид, 'указатель': None, 'фаза': 'получение начато', 'ошибка': None}
        сам._ресурсы.append(запись)
        указатель = операция(*аргументы)
        if not указатель or указатель == 1:
            запись['фаза'] = 'отказ'
            raise сам._ошибка_вызова()
        запись['указатель'] = указатель
        запись['фаза'] = 'получен'
        return запись

    def _снять(сам, дескриптор):
        типы = сам._типы
        объект = сам._получить_объект('безопасность', сам._начать_безопасность)
        сведения = сам._сведения()
        if сам._стат(дескриптор, типы.byref(сведения), объект['указатель']) != 0:
            raise сам._ошибка_вызова()
        действительный = типы.c_int(-1)
        if сам._наличие(объект['указатель'], 5, типы.byref(действительный)) != 0:
            raise сам._ошибка_вызова()
        if действительный.value < 0:
            raise ОшибкаОтчёта('не подтверждён признак списка доступа')
        проверка = os.fstat(дескриптор)
        время = lambda значение: значение.секунды * 1_000_000_000 + значение.наносекунды
        if (сведения.устройство, сведения.режим, сведения.ссылки, сведения.инод,
            сведения.владелец, сведения.группа, сведения.тип_устройства,
            сведения.размер, сведения.блоки, сведения.размер_блока, сведения.флаги,
            время(сведения.изменение), время(сведения.состояние)) != (
            проверка.st_dev, проверка.st_mode, проверка.st_nlink, проверка.st_ino,
            проверка.st_uid, проверка.st_gid, проверка.st_rdev, проверка.st_size,
            проверка.st_blocks, проверка.st_blksize, проверка.st_flags,
            проверка.st_mtime_ns, проверка.st_ctime_ns):
            raise ОшибкаОтчёта('fstatx не совпал с удержанным FD')
        if not действительный.value:
            return None, None
        запись = сам._получить_объект('список', сам._взять_список, дескриптор, 0x100)
        размер = сам._размер_списка(запись['указатель'])
        if размер < 0:
            raise сам._ошибка_вызова()
        if размер == 0 or размер > сам._предел_байтов:
            raise ОшибкаОтчёта('неверный размер внешнего списка доступа')
        буфер = типы.create_string_buffer(размер)
        записано = сам._копия_списка(буфер, запись['указатель'], размер)
        if записано < 0:
            raise сам._ошибка_вызова()
        if записано != размер:
            raise ОшибкаОтчёта('неполное внешнее представление списка доступа')
        return буфер.raw[:размер], запись

    def _установить(сам, дескриптор, запись):
        if (type(запись) is not dict or not any(объект is запись for объект in сам._ресурсы)
            or запись['вид'] != 'список' or запись['фаза'] != 'получен'):
            raise ОшибкаОтчёта('неверный владелец списка доступа')
        if сам._установить_список(дескриптор, запись['указатель'], 0x100) != 0:
            raise сам._ошибка_вызова()

    def _освободить_подтверждённые(сам):
        for запись in reversed(сам._ресурсы):
            if запись['фаза'] != 'получен':
                raise ОшибкаОтчёта('объект списка доступа не подтверждён')
            запись['фаза'] = 'освобождение начато'
            try:
                if запись['вид'] == 'безопасность':
                    сам._кончить_безопасность(запись['указатель'])
                elif запись['вид'] == 'список':
                    if сам._кончить_список(запись['указатель']) != 0:
                        raise сам._ошибка_вызова()
                else:
                    raise ОшибкаОтчёта('неверный тип объекта списка доступа')
            except BaseException as ошибка:
                запись['ошибка'] = ошибка
                запись['фаза'] = 'неизвестно'
                raise
            запись['фаза'] = 'освобождён'


class _ОпытныйПереносСпискаДоступа:
    """Один перенос ACL между удержанными FD в доверенном namespace.

    Вызывающий доказывает профиль Darwin/FS, защищённый staging, отсутствие
    постороннего изменения и повторного входа из handler; удерживает этот
    объект, систему и оба FD. Скрытые данные и публикация не подтверждаются.
    При ошибке собственные объекты C остаются в системе и не освобождаются
    повторно; caller сохраняет её, даже когда запись ACL не начиналась.
    """

    def __init__(сам, система, источник, назначение):
        if (type(система) is not _ВызовыСписковДоступаДарвина or система._занято
            or type(источник) is not int or type(назначение) is not int
            or источник < 0 or назначение < 0 or источник == назначение):
            raise ОшибкаОтчёта('неверные опоры списка доступа')
        система._занято = True
        сам._система = система
        сам._источник = источник
        сам._назначение = назначение
        сам._процесс = os.getpid()
        сам._поток = threading.current_thread()
        сам.состояние = 'готов'
        сам.ошибка = None
        сам.попытка = None

    def выполнить(сам):
        if (os.getpid() != сам._процесс or threading.current_thread() is not сам._поток
            or сам.состояние != 'готов'):
            raise ОшибкаОтчёта('повтор или чужой владелец переноса списка доступа')
        def исходная_метка(с):
            return (с.st_dev, с.st_ino, с.st_mode, с.st_uid, с.st_gid, с.st_nlink,
                    с.st_size, с.st_mtime_ns, с.st_ctime_ns, с.st_flags)
        def метка_назначения(с):
            return (с.st_dev, с.st_ino, с.st_mode, с.st_uid, с.st_gid, с.st_nlink,
                    с.st_size, с.st_mtime_ns, с.st_flags)
        try:
            сам.состояние = 'сверка'
            for дескриптор, доступы in (
                (сам._источник, (os.O_RDONLY, os.O_RDWR)),
                (сам._назначение, (os.O_RDWR,)),
            ):
                доступ = fcntl.fcntl(дескриптор, fcntl.F_GETFL) & os.O_ACCMODE
                if (доступ not in доступы
                    or not fcntl.fcntl(дескриптор, fcntl.F_GETFD) & fcntl.FD_CLOEXEC):
                    raise ОшибкаОтчёта('неверный доступ к FD списка доступа')
            исходный = os.fstat(сам._источник)
            временный = os.fstat(сам._назначение)
            if (not stat.S_ISREG(исходный.st_mode) or not stat.S_ISREG(временный.st_mode)
                or исходный.st_nlink != 1 or временный.st_nlink != 1
                or (исходный.st_dev, исходный.st_ino) == (временный.st_dev, временный.st_ino)
                or (исходный.st_dev, исходный.st_uid, исходный.st_gid)
                   != (временный.st_dev, временный.st_uid, временный.st_gid)
                or stat.S_IMODE(исходный.st_mode) & 0o7000
                or stat.S_IMODE(временный.st_mode) != 0o600
                or исходный.st_flags != 0 or временный.st_flags != 0):
                raise ОшибкаОтчёта('неверные исходный или временный inode списка доступа')
            метка_источника = исходная_метка(исходный)
            метка_временного = метка_назначения(временный)
            исходный_список, объект_списка = сам._система._снять(сам._источник)
            временный_список, _ = сам._система._снять(сам._назначение)
            if временный_список is not None:
                raise ОшибкаОтчёта('временный inode уже имеет список доступа')
            повторный_список, _ = сам._система._снять(сам._источник)
            повторный_временный, _ = сам._система._снять(сам._назначение)
            if (повторный_список != исходный_список or повторный_временный is not None
                or исходная_метка(os.fstat(сам._источник)) != метка_источника
                or метка_назначения(os.fstat(сам._назначение)) != метка_временного):
                raise ОшибкаОтчёта('списки доступа или inode изменились до переноса')
            if исходный_список is not None:
                сам.попытка = ('установка', 'начата')
                сам._система._установить(сам._назначение, объект_списка)
                сам.попытка = ('установка', 'подтверждена')
            после_источника, _ = сам._система._снять(сам._источник)
            после_назначения, _ = сам._система._снять(сам._назначение)
            if (после_источника != исходный_список or после_назначения != исходный_список
                or исходная_метка(os.fstat(сам._источник)) != метка_источника
                or метка_назначения(os.fstat(сам._назначение)) != метка_временного):
                raise ОшибкаОтчёта('перенос списка доступа не подтверждён')
            сам._система._освободить_подтверждённые()
            сам.состояние = 'подтверждено'
            return исходный_список is not None
        except BaseException as ошибка:
            сам.состояние = 'неизвестно'
            сам.ошибка = ошибка
            неопределённое_освобождение = any(
                запись['фаза'] in ('получение начато', 'освобождение начато', 'неизвестно')
                for запись in сам._система._ресурсы)
            if сам.попытка is None and not неопределённое_освобождение:
                сам.состояние = 'отказ до записи'
            raise


class ПрерываниеОбёртки(BaseException):
    """Обрабатываемый сигнал, который нужно передать дочерней группе."""

    def __init__(сам, номер_сигнала: int) -> None:
        super().__init__(номер_сигнала)
        сам.номер_сигнала = номер_сигнала


def канонические_машинные_байты(значение: object) -> bytes:
    try:
        текст = json.dumps(
            значение,
            ensure_ascii=False,
            indent=2,
            sort_keys=True,
            allow_nan=False,
        )
    except ValueError as ошибка:
        raise ОшибкаОтчёта("не удалось сериализовать машинную запись") from ошибка
    return (текст + "\n").encode("utf-8")


def _разобрать_машинный_json(текст: str) -> object:
    """Не принимать повторы ключей и неконечные числа в машинной записи."""
    def объект_без_повторов(пары):
        объект = {}
        for ключ, значение in пары:
            if ключ in объект:
                raise ОшибкаОтчёта("повторяющийся ключ в машинной записи")
            объект[ключ] = значение
        return объект

    def запретить_константу(_значение):
        raise ОшибкаОтчёта("недопустимая числовая константа в машинной записи")

    def конечное_число(значение):
        число = float(значение)
        if not math.isfinite(число):
            raise ОшибкаОтчёта("неконечное число в машинной записи")
        return число

    return json.loads(текст, object_pairs_hook=объект_без_повторов,
                      parse_constant=запретить_константу, parse_float=конечное_число)


def хэш_содержимого(байты: bytes) -> str:
    return hashlib.sha256(байты).hexdigest()


def проверить_обычный_путь(путь: Path, назначение: str) -> None:
    if путь.is_symlink() or not путь.is_file():
        raise ОшибкаОтчёта(f"{назначение} должен быть обычным файлом: {путь}")


def проверить_компоненты_без_ссылок(корень: Path, путь: Path) -> None:
    текущий = корень
    for часть in путь.relative_to(корень).parts:
        текущий = текущий / часть
        if текущий.is_symlink():
            raise ОшибкаОтчёта(
                f"символическая ссылка в управляемом пути запрещена: {текущий}"
            )


def разрешить_сессию(
    корень_репозитория: str | Path,
    запрос: str | Path,
) -> tuple[Path, Path, Path, Path, str]:
    корень = Path(корень_репозитория).resolve()
    if not корень.is_dir():
        raise ОшибкаОтчёта(f"корень репозитория не является каталогом: {корень}")

    исходный_путь = Path(запрос)
    лексический_путь = Path(
        os.path.abspath(
            исходный_путь
            if исходный_путь.is_absolute()
            else корень / исходный_путь
        )
    )
    try:
        лексический_относительный = лексический_путь.relative_to(корень)
    except ValueError as ошибка:
        raise ОшибкаОтчёта("путь запроса вышел за корень репозитория") from ошибка
    if (
        len(лексический_относительный.parts) != 3
        or лексический_относительный.parts[0] != КАТАЛОГ_ЖУРНАЛА
        or лексический_относительный.name != ИМЯ_ЗАПРОСА
    ):
        raise ОшибкаОтчёта(
            "путь запроса должен иметь вид Журнал/<stem>/запрос.md"
        )
    проверить_компоненты_без_ссылок(корень, лексический_путь)

    путь_запроса = лексический_путь.resolve()
    try:
        относительный = путь_запроса.relative_to(корень)
    except ValueError as ошибка:
        raise ОшибкаОтчёта("путь запроса вышел за корень репозитория") from ошибка
    if относительный != лексический_относительный:
        raise ОшибкаОтчёта("путь запроса изменился при разрешении")
    if (
        len(относительный.parts) != 3
        or относительный.parts[0] != КАТАЛОГ_ЖУРНАЛА
        or относительный.name != ИМЯ_ЗАПРОСА
    ):
        raise ОшибкаОтчёта(
            "путь запроса должен иметь вид Журнал/<stem>/запрос.md"
        )
    проверить_компоненты_без_ссылок(корень, путь_запроса)
    проверить_обычный_путь(путь_запроса, "запрос")

    путь_отчёта = путь_запроса.parent / ИМЯ_ОТЧЁТА
    проверить_компоненты_без_ссылок(корень, путь_отчёта)
    проверить_обычный_путь(путь_отчёта, "отчёт")
    каталог_запусков = путь_запроса.parent / ОТНОСИТЕЛЬНЫЙ_КАТАЛОГ_ЗАПУСКОВ
    проверить_компоненты_без_ссылок(корень, каталог_запусков)
    return (
        корень,
        путь_запроса,
        путь_отчёта,
        каталог_запусков,
        относительный.as_posix(),
    )


_ПРИЗНАК_ИСТЕЧЕНИЯ_ЗАМКА = object()


def _остаток_срока_блокировки(срок: float, название: str) -> float:
    try:
        сейчас = time.monotonic()
        if type(сейчас) not in (int, float) or not math.isfinite(сейчас):
            raise ValueError("недостоверные часы")
        остаток = срок - сейчас
        if not math.isfinite(остаток) or остаток <= 0:
            raise ValueError("недостоверный или истёкший срок")
        return остаток
    except (OSError, OverflowError, TypeError, ValueError) as ошибка:
        отказ = ОшибкаОтчёта(f"истёк срок или недостоверны часы {название}")
        отказ._признак_истечения_замка = _ПРИЗНАК_ИСТЕЧЕНИЯ_ЗАМКА
        raise отказ from ошибка



def _взять_файловый_замок(дескриптор: int, срок: float | None) -> None:
    if срок is None:
        fcntl.flock(дескриптор, fcntl.LOCK_EX)
        return
    while True:
        _остаток_срока_блокировки(срок, 'межпроцессной блокировки')
        try:
            fcntl.flock(дескриптор, fcntl.LOCK_EX | fcntl.LOCK_NB)
            return
        except BlockingIOError as причина:
            if причина.errno not in (errno.EAGAIN, errno.EWOULDBLOCK):
                raise
            остаток = _остаток_срока_блокировки(срок, 'межпроцессной блокировки')
            time.sleep(min(0.01, остаток))



@contextlib.contextmanager
def межпроцессная_блокировка(
    корень: Path, сессия: str, *, срок_монотонный: float | None = None,
) -> Iterator[Callable[[], None]]:
    """Удержать прежний файл замка и обнаружить его замену до допуска.

    Требуется доверенный каталог и запрет удаления файла другими участниками:
    проверки имени не защищают от замены после последней сверки или ABA.
    """
    if срок_монотонный is not None:
        if (type(срок_монотонный) is not float
            or not math.isfinite(срок_монотонный) or срок_монотонный <= 0):
            raise ОшибкаОтчёта("нужен конечный положительный срок блокировки")
        _остаток_срока_блокировки(срок_монотонный, 'межпроцессной блокировки')
    ключ = хэш_содержимого(f"{корень}\0{сессия}".encode("utf-8"))
    путь = Path(tempfile.gettempdir()) / f"fum-check-runs-{ключ}.lock"
    флаги = os.O_RDWR | os.O_NOFOLLOW | os.O_NONBLOCK | os.O_CLOEXEC
    дескрипторы: list[int] = []
    первичная: BaseException | None = None
    взят = False

    class УжеСуществует(Exception):
        pass

    def создать():
        try:
            return os.open(путь, флаги | os.O_CREAT | os.O_EXCL, 0o600)
        except FileExistsError as ошибка:
            raise УжеСуществует() from ошибка

    def проверить_метку(метка):
        if not (stat.S_ISREG(метка.st_mode) and метка.st_nlink == 1
                and stat.S_IMODE(метка.st_mode) == 0o600
                and метка.st_uid == os.getuid() == os.geteuid()):
            raise ОшибкаОтчёта("небезопасный файл межпроцессной блокировки")

    try:
        try:
            дескриптор = _приобрести_fd(дескрипторы, создать)
            исходный = None
        except УжеСуществует:
            исходный = путь.lstat()
            проверить_метку(исходный)
            дескриптор = _приобрести_fd(дескрипторы, os.open, путь, флаги)

        def сверить():
            открытый, текущий = os.fstat(дескриптор), путь.lstat()
            проверить_метку(открытый)
            проверить_метку(текущий)
            if not fcntl.fcntl(дескриптор, fcntl.F_GETFD) & fcntl.FD_CLOEXEC:
                raise ОшибкаОтчёта("дескриптор замка наследуется")
            if (открытый.st_dev, открытый.st_ino) != (текущий.st_dev, текущий.st_ino):
                raise ОшибкаОтчёта("подменён файл межпроцессной блокировки")
            if исходный is not None and (открытый.st_dev, открытый.st_ino) != (
                    исходный.st_dev, исходный.st_ino):
                raise ОшибкаОтчёта("заменён существующий файл межпроцессной блокировки")

        сверить()
        _взять_файловый_замок(дескриптор, срок_монотонный)
        взят = True
        сверить()
        if срок_монотонный is not None:
            _остаток_срока_блокировки(срок_монотонный, 'межпроцессной блокировки')
        yield сверить
        сверить()
    except BaseException as ошибка:
        первичная = ошибка
        raise
    finally:
        ошибка_разблокировки = None
        try:
            if взят:
                fcntl.flock(дескриптор, fcntl.LOCK_UN)
        except BaseException as ошибка:
            ошибка_разблокировки = ошибка
        итог = первичная
        if ошибка_разблокировки is not None:
            итог = (BaseExceptionGroup("ошибки блокировки и разблокировки",
                                       [первичная, ошибка_разблокировки])
                    if первичная is not None else ошибка_разблокировки)
        _закрыть_удержанные_fd(дескрипторы, итог, "межпроцессной блокировки",
                               _сохранять_ошибки=True)
        if ошибка_разблокировки is not None:
            raise итог from None

def синхронизировать_каталог(каталог: Path) -> None:
    дескриптор = os.open(каталог, os.O_RDONLY)
    ошибка_синхронизации = None
    try:
        os.fsync(дескриптор)
    except BaseException as ошибка:
        ошибка_синхронизации = ошибка
        raise
    finally:
        try:
            os.close(дескриптор)
        except BaseException as ошибка_закрытия:
            if ошибка_синхронизации is None or ошибка_синхронизации is ошибка_закрытия:
                raise
            if not isinstance(ошибка_синхронизации, Exception):
                raise ошибка_синхронизации from ошибка_закрытия
            raise ошибка_закрытия from ошибка_синхронизации


def атомарно_записать_байты(путь: Path, байты: bytes) -> None:
    путь.parent.mkdir(parents=True, exist_ok=True)
    if путь.parent.is_symlink():
        raise ОшибкаОтчёта(
            f"символическая ссылка вместо каталога записи запрещена: {путь.parent}"
        )
    временный = путь.parent / f".{путь.name}.{uuid.uuid4()}.tmp"
    режим = 0o644
    if путь.exists() and not путь.is_symlink():
        режим = путь.stat().st_mode & 0o777
    дескриптор: int | None = None
    try:
        дескриптор = os.open(
            временный,
            os.O_WRONLY | os.O_CREAT | os.O_EXCL,
            режим,
        )
        with os.fdopen(дескриптор, "wb") as поток:
            дескриптор = None
            поток.write(байты)
            поток.flush()
            os.fsync(поток.fileno())
        os.replace(временный, путь)
        синхронизировать_каталог(путь.parent)
    except OSError as ошибка:
        raise ОшибкаОтчёта(f"не удалось атомарно записать {путь}: {ошибка}") from ошибка
    finally:
        if дескриптор is not None:
            os.close(дескриптор)


def атомарно_записать_текст(путь: Path, текст: str) -> None:
    атомарно_записать_байты(путь, текст.encode("utf-8"))


def прочитать_машинную_запись(путь: Path, *, предел: int | None = None) -> tuple[object, bytes]:
    """Прочитать конечный компонент без перехода по ссылке или ожидания FIFO."""
    if предел is not None and (type(предел) is not int or not 0 <= предел <= 16 * 1024 * 1024):
        raise ОшибкаОтчёта('неверный предел машинной записи')
    дескрипторы: list[int] = []
    первичная: BaseException | None = None
    def метка(сведения):
        return (сведения.st_dev, сведения.st_ino, сведения.st_mode, сведения.st_uid,
                сведения.st_gid, сведения.st_nlink, сведения.st_size,
                сведения.st_mtime_ns, сведения.st_ctime_ns)
    def читать(fd: int, размер: int) -> bytes:
        части = bytearray()
        while len(части) < размер:
            try:
                часть = os.read(fd, min(1024 * 1024, размер - len(части)))
            except InterruptedError:
                continue
            if not часть:
                raise ОшибкаОтчёта("машинная запись изменилась во время чтения")
            части.extend(часть)
        while True:
            try:
                лишнее = os.read(fd, 1)
                break
            except InterruptedError:
                continue
        if лишнее:
            raise ОшибкаОтчёта("машинная запись изменилась во время чтения")
        return bytes(части)
    try:
        try:
            исходное = путь.lstat()
            if not stat.S_ISREG(исходное.st_mode):
                raise ОшибкаОтчёта(f"машинная запись должна быть обычным файлом: {путь}")
            fd = _приобрести_fd(дескрипторы, os.open, путь,
                                os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK | os.O_CLOEXEC)
            открытое = os.fstat(fd)
            if not stat.S_ISREG(открытое.st_mode) or метка(открытое) != метка(исходное):
                raise ОшибкаОтчёта("машинная запись заменена до чтения")
            if предел is not None and открытое.st_size > предел:
                raise ОшибкаОтчёта('превышен предел машинной записи')
            байты = читать(fd, открытое.st_size)
            if метка(os.fstat(fd)) != метка(открытое) or метка(путь.lstat()) != метка(открытое):
                raise ОшибкаОтчёта("машинная запись изменилась во время чтения")
            текст = байты.decode("utf-8")
            try:
                значение = _разобрать_машинный_json(текст)
            except (ValueError, RecursionError) as ошибка:
                raise ОшибкаОтчёта(f"не удалось прочитать JSON {путь}: {ошибка}") from ошибка
        except (OSError, UnicodeError) as ошибка:
            raise ОшибкаОтчёта(f"не удалось прочитать JSON {путь}: {ошибка}") from ошибка
        return значение, байты
    except BaseException as ошибка:
        первичная = ошибка
        raise
    finally:
        try:
            _закрыть_удержанные_fd(дескрипторы, первичная, 'машинной записи',
                                   _сохранять_ошибки=True)
        except ExceptionGroup as ошибки_закрытия:
            raise ОшибкаОтчёта('неизвестен исход закрытия машинной записи') from ошибки_закрытия


def проверить_строку(
    значение: object,
    поле: str,
    *,
    разрешить_пустую: bool = False,
) -> str:
    if not isinstance(значение, str):
        raise ОшибкаОтчёта(f"поле {поле} должно быть строкой")
    if not разрешить_пустую and not значение:
        raise ОшибкаОтчёта(f"поле {поле} не должно быть пустым")
    if any(
        unicodedata.category(знак) in {"Cc", "Zl", "Zp"}
        for знак in значение
    ):
        raise ОшибкаОтчёта(
            f"поле {поле} содержит управляющий или строковый разделитель"
        )
    return значение


def проверить_идентификатор(значение: object) -> str:
    if not isinstance(значение, str) or КАНОНИЧЕСКИЙ_ИДЕНТИФИКАТОР.fullmatch(значение) is None:
        raise ОшибкаОтчёта("идентификатор запуска должен быть каноническим UUID")
    try:
        канонический = str(uuid.UUID(значение))
    except ValueError as ошибка:
        raise ОшибкаОтчёта("идентификатор запуска должен быть каноническим UUID") from ошибка
    if канонический != значение:
        raise ОшибкаОтчёта("идентификатор запуска должен быть lowercase UUID")
    return значение


def проверить_наблюдения(значение: object) -> list[dict[str, object]]:
    if not isinstance(значение, list):
        raise ОшибкаОтчёта("наблюдения должны быть списком")
    результат: list[dict[str, object]] = []
    ключи: set[str] = set()
    for номер, наблюдение in enumerate(значение, start=1):
        if not isinstance(наблюдение, dict) or set(наблюдение) != ПОЛЯ_НАБЛЮДЕНИЯ:
            raise ОшибкаОтчёта(
                f"неверный набор полей наблюдения smoke-check: {номер}"
            )
        ключ = проверить_аналитический_ключ(
            наблюдение["ключ_проверки"],
            f"ключ_проверки наблюдения {номер}",
        )
        приведённый = ключ.casefold()
        if приведённый in ключи:
            raise ОшибкаОтчёта(
                f"повторный ключ проверки в наблюдениях smoke-check: {ключ}"
            )
        ключи.add(приведённый)
        проверить_строку(
            наблюдение["название"],
            f"название наблюдения {номер}",
        )
        if not isinstance(наблюдение["статус"], str) or наблюдение["статус"] not in СТАТУСЫ:
            raise ОшибкаОтчёта(
                f"неверный статус наблюдения smoke-check: {номер}"
            )
        длительность = наблюдение["длительность_наносекунды"]
        if (
            isinstance(длительность, bool)
            or not isinstance(длительность, int)
            or длительность < 0
        ):
            raise ОшибкаОтчёта(
                f"неверная длительность наблюдения smoke-check: {номер}"
            )
        результат.append(наблюдение)
    return результат


def проверить_аналитический_ключ(значение: object, поле: str) -> str:
    ключ = проверить_строку(значение, поле)
    путь = PurePosixPath(ключ)
    if (
        ключ != unicodedata.normalize("NFC", ключ)
        or "\\" in ключ
        or путь.is_absolute()
        or путь.as_posix() != ключ
        or any(часть in {"", ".", ".."} for часть in путь.parts)
    ):
        raise ОшибкаОтчёта(f"поле {поле} не является каноническим ключом")
    return ключ


def подготовить_ограниченную_среду_проверки(
    идентификатор: str, путь_наблюдений: Path | None, *,
    неполная_проекция: bool, изолировать_git: bool = False,
) -> dict[str, str]:
    """Чистый кандидат: не читает текущую среду и не разрешает запуск."""
    if type(неполная_проекция) is not bool:
        raise ОшибкаОтчёта("режим проекции должен быть логическим")
    if type(изолировать_git) is not bool:
        raise ОшибкаОтчёта("режим изоляции Git должен быть логическим")
    проверить_идентификатор(идентификатор)
    if путь_наблюдений is not None and (
        not isinstance(путь_наблюдений, Path)
        or not путь_наблюдений.is_absolute()
        or ".." in путь_наблюдений.parts
        or "\0" in str(путь_наблюдений)
    ):
        raise ОшибкаОтчёта("путь наблюдений должен быть абсолютным и не содержать .. или NUL")
    if неполная_проекция and путь_наблюдений is not None:
        raise ОшибкаОтчёта("неполная проекция не принимает путь наблюдений")
    окружение = {
        "PATH": os.defpath,
        "GIT_OPTIONAL_LOCKS": "0",
        "GIT_NO_LAZY_FETCH": "1",
        "GIT_NO_REPLACE_OBJECTS": "1",
        "LC_ALL": "C",
    }
    if изолировать_git:
        окружение.update({
            "GIT_CONFIG_NOSYSTEM": "1",
            "GIT_CONFIG_GLOBAL": "/dev/null",
            "GIT_ATTR_NOSYSTEM": "1",
        })
    if not неполная_проекция:
        окружение[ПЕРЕМЕННАЯ_ИДЕНТИФИКАТОРА_ЗАПУСКА] = идентификатор
        if путь_наблюдений is not None:
            окружение[ПЕРЕМЕННАЯ_ПУТИ_НАБЛЮДЕНИЙ] = str(путь_наблюдений)
    return окружение


def выполнить_чтение_репозитория(корень: Path, *аргументы: str) -> bytes:
    raise ОшибкаОтчёта("профиль исторического Git-снимка неизвестен")
    окружение = os.environ.copy()
    for имя in (
        "GIT_DIR",
        "GIT_WORK_TREE",
        "GIT_INDEX_FILE",
        "GIT_COMMON_DIR",
        "GIT_OBJECT_DIRECTORY",
        "GIT_ALTERNATE_OBJECT_DIRECTORIES",
        "GIT_REPLACE_REF_BASE",
    ):
        окружение.pop(имя, None)
    окружение.update(
        {
            "GIT_OPTIONAL_LOCKS": "0",
            "GIT_NO_REPLACE_OBJECTS": "1",
            "LC_ALL": "C",
        }
    )
    итог = subprocess.run(
        ["git", "-C", str(корень), *аргументы],
        check=False,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        env=окружение,
    )
    if итог.returncode != 0:
        пояснение = итог.stderr.decode("utf-8", errors="replace").strip()
        raise ОшибкаОтчёта(
            "не удалось прочитать Git-снимок"
            + (f": {пояснение}" if пояснение else "")
        )
    return итог.stdout


def добавить_часть_отпечатка(
    хэш: "hashlib._Hash",
    метка: str,
    байты: bytes,
) -> None:
    метка_байты = метка.encode("utf-8")
    хэш.update(len(метка_байты).to_bytes(8, "big"))
    хэш.update(метка_байты)
    хэш.update(len(байты).to_bytes(8, "big"))
    хэш.update(байты)


def путь_в_производном_пространстве(путь: str) -> bool:
    return путь == ПРОИЗВОДНОЕ_ПРОСТРАНСТВО or путь.startswith(
        f"{ПРОИЗВОДНОЕ_ПРОСТРАНСТВО}/"
    )


def проверить_чистоту_подмодулей(корень: Path) -> None:
    состояние = выполнить_чтение_репозитория(
        корень,
        "status",
        "--porcelain=v2",
        "-z",
        "--untracked-files=all",
        "--ignore-submodules=none",
        "--",
        ".",
        f":(top,exclude,literal){ПРОИЗВОДНОЕ_ПРОСТРАНСТВО}",
        f":(top,exclude,glob){ПРОИЗВОДНОЕ_ПРОСТРАНСТВО}/**",
    )
    for строка in состояние.split(b"\0"):
        if not строка.startswith((b"1 ", b"2 ", b"u ")):
            continue
        части = строка.split(b" ", 8)
        if (
            len(части) > 2
            and len(части[2]) == 4
            and части[2].startswith(b"S")
            and части[2][2:] != b".."
        ):
            raise ОшибкаОтчёта(
                "Git-снимок содержит изменённый подмодуль"
            )


def вычислить_отпечаток_снимка(
    корень_репозитория: str | Path,
    сессия: str | Path,
) -> str:
    корень = Path(корень_репозитория).resolve()
    сессия_путь = PurePosixPath(Path(сессия).as_posix())
    if сессия_путь.is_absolute() or any(
        часть in {"", ".", ".."} for часть in сессия_путь.parts
    ):
        raise ОшибкаОтчёта("путь сессии для отпечатка неканоничен")
    исключённый_отчёт = (сессия_путь / ИМЯ_ОТЧЁТА).as_posix()
    исключённые_запуски = (
        сессия_путь / ОТНОСИТЕЛЬНЫЙ_КАТАЛОГ_ЗАПУСКОВ.as_posix()
    ).as_posix()
    пути_для_разницы = [
        ".",
        f":(exclude){исключённый_отчёт}",
        f":(exclude){исключённые_запуски}",
        f":(exclude){исключённые_запуски}/**",
        f":(top,exclude,literal){ПРОИЗВОДНОЕ_ПРОСТРАНСТВО}",
        f":(top,exclude,glob){ПРОИЗВОДНОЕ_ПРОСТРАНСТВО}/**",
    ]
    проверить_чистоту_подмодулей(корень)
    вершина = выполнить_чтение_репозитория(
        корень, "rev-parse", "--verify", "HEAD"
    ).strip()
    индекс = выполнить_чтение_репозитория(
        корень,
        "diff",
        "--binary",
        "--no-ext-diff",
        "--no-textconv",
        "--ignore-submodules=none",
        "--cached",
        "HEAD",
        "--",
        *пути_для_разницы,
    )
    рабочее_дерево = выполнить_чтение_репозитория(
        корень,
        "diff",
        "--binary",
        "--no-ext-diff",
        "--no-textconv",
        "--ignore-submodules=none",
        "--",
        *пути_для_разницы,
    )
    неотслеживаемые = выполнить_чтение_репозитория(
        корень, "ls-files", "--others", "--exclude-standard", "-z", "--", "."
    )
    хэш = hashlib.sha256()
    добавить_часть_отпечатка(хэш, "вершина", вершина)
    добавить_часть_отпечатка(хэш, "индекс", индекс)
    добавить_часть_отпечатка(хэш, "рабочее_дерево", рабочее_дерево)
    for исходное_имя in sorted(неотслеживаемые.split(b"\0")):
        if not исходное_имя:
            continue
        try:
            имя = исходное_имя.decode("utf-8")
        except UnicodeError as ошибка:
            raise ОшибкаОтчёта(
                "Git-снимок содержит не-UTF-8 путь"
            ) from ошибка
        if имя == исключённый_отчёт or (
            имя == исключённые_запуски
            or имя.startswith(f"{исключённые_запуски}/")
        ):
            continue
        if путь_в_производном_пространстве(имя):
            continue
        каноническое_имя = проверить_аналитический_ключ(имя, "путь Git-снимка")
        путь = корень / Path(каноническое_имя)
        try:
            сведения = путь.lstat()
            if stat.S_ISREG(сведения.st_mode):
                тип = "файл"
                содержимое = путь.read_bytes()
            elif stat.S_ISLNK(сведения.st_mode):
                тип = "символическая_ссылка"
                содержимое = os.fsencode(os.readlink(путь))
            else:
                raise ОшибкаОтчёта(
                    f"неотслеживаемый путь имеет опасный тип: {имя}"
                )
        except OSError as ошибка:
            raise ОшибкаОтчёта(
                f"не удалось прочитать неотслеживаемый путь: {имя}"
            ) from ошибка
        добавить_часть_отпечатка(
            хэш,
            f"неотслеживаемый:{каноническое_имя}:{тип}:{stat.S_IMODE(сведения.st_mode):o}",
            содержимое,
        )
    return f"sha256:{хэш.hexdigest()}"


_неизвестные_закрытия_fd = []
_учёт_неизвестных_закрытий_fd_потерян = False


def _закрыть_удержанные_fd(дескрипторы: list[int], первичная: BaseException | None, назначение: str,
                           *, _сохранять_ошибки: bool = False) -> None:
    """Попытаться закрыть каждый FD один раз, сохраняя отказ и отмену.

    По умолчанию вторичные ошибки фиксируются числом и не более чем 16 именами
    типов. Явный режим сохраняет все объекты и требует памяти пропорционально
    числу ошибок; caller обязан ограничить число передаваемых дескрипторов.
    Прямая отмена при неизвестном close сохраняется отдельно от графа причин.
    Записи процесса диагностические и не разрешают повторный close.
    Асинхронные прерывания между операциями этой гарантией не охвачены.
    """
    первая_ошибка = None
    отложенное_прерывание = None
    неизвестная_группа = None
    иное_прерывание = None
    число_неизвестных = 0
    типы_ошибок = []
    ошибки_закрытия = []
    отмена_закрытия = None
    отмены = (KeyboardInterrupt, SystemExit, ПрерываниеОбёртки)
    def содержит_отмену(ошибка: BaseException) -> bool | None:
        очередь = [ошибка]
        просмотрено = 0
        while очередь:
            текущая = очередь.pop()
            просмотрено += 1
            if просмотрено > 8192:
                return None
            if isinstance(текущая, отмены):
                return True
            if isinstance(текущая, BaseExceptionGroup):
                вложенные = BaseExceptionGroup.exceptions.__get__(текущая)
                if len(очередь) + len(вложенные) > 8192:
                    return None
                очередь.extend(вложенные)
        return False
    while дескрипторы:
        fd = дескрипторы.pop()
        try:
            os.close(fd)
        except BaseException as ошибка:
            if _сохранять_ошибки:
                if отмена_закрытия is None and isinstance(ошибка, отмены):
                    отмена_закрытия = ошибка
                ошибки_закрытия.append(ошибка)
                continue
            число_неизвестных += 1
            if len(типы_ошибок) < 16:
                типы_ошибок.append(type(ошибка).__name__)
            состояние_отмены = содержит_отмену(ошибка)
            if состояние_отмены is True:
                if отложенное_прерывание is None:
                    отложенное_прерывание = ошибка
            elif состояние_отмены is None:
                if неизвестная_группа is None:
                    неизвестная_группа = ошибка
            elif isinstance(ошибка, Exception):
                if первая_ошибка is None:
                    первая_ошибка = ошибка
            elif иное_прерывание is None:
                иное_прерывание = ошибка
    if ошибки_закрытия:
        отмена = первичная if isinstance(первичная, отмены) else отмена_закрытия
        if отмена is not None:
            global _учёт_неизвестных_закрытий_fd_потерян
            try:
                _неизвестные_закрытия_fd.append({
                    'назначение': назначение, 'первичная': первичная,
                    'ошибки': tuple(ошибки_закрытия), 'отмена': отмена,
                })
            except BaseException:
                _учёт_неизвестных_закрытий_fd_потерян = True
                try:
                    BaseException.add_note(отмена, 'Неполный учёт неизвестного закрытия FD; повтор не разрешён.')
                except BaseException:
                    pass
            raise отмена
        причины = ([] if первичная is None else [первичная]) + ошибки_закрытия
        raise BaseExceptionGroup('неизвестен исход закрытия FD: ' + назначение, причины) from None
    if not число_неизвестных:
        return
    if отложенное_прерывание is None:
        отложенное_прерывание = неизвестная_группа
    elif неизвестная_группа is not None and первая_ошибка is None:
        первая_ошибка = неизвестная_группа
    заметка = (f"Неизвестен исход закрытия FD {назначение}: {число_неизвестных}; "
               f"типы: {', '.join(типы_ошибок)}")
    if первичная is not None:
        первичная.add_note(заметка)
    if отложенное_прерывание is not None:
        отложенное_прерывание.add_note(заметка)
        if первичная is None:
            if первая_ошибка is not None:
                raise отложенное_прерывание from первая_ошибка
            raise отложенное_прерывание
        if содержит_отмену(первичная) is not True:
            raise отложенное_прерывание from первичная
        первичная.add_note("При закрытии FD возникло дополнительное прерывание")
    if иное_прерывание is not None:
        if первичная is None:
            иное_прерывание.add_note(заметка)
            raise иное_прерывание from первая_ошибка
        первичная.add_note("При закрытии FD возникло иное прерывание")
    if первичная is None:
        raise ОшибкаОтчёта(заметка) from первая_ошибка


def _приобрести_fd(дескрипторы: list[int], операция, *аргументы, **ключи):
    """Зарегистрировать FD до возврата маски; не полная атомарность.

    Смешанную BaseExceptionGroup сохраняем целиком, не разбирая вложения.
    """
    if not hasattr(signal, 'pthread_sigmask'):
        raise ОшибкаОтчёта('недоступна маска управляемых сигналов')
    try:
        прежняя = signal.pthread_sigmask(signal.SIG_BLOCK, {signal.SIGINT, signal.SIGTERM})
    except BaseException as ошибка:
        ошибка.add_note('Неизвестно состояние маски после сбоя блокировки')
        raise
    исходная = None
    try:
        новый = операция(*аргументы, **ключи)
        try:
            дескрипторы.append(новый)
        except BaseException as ошибка:
            if новый not in дескрипторы:
                try:
                    os.close(новый)
                except BaseException as закрытие:
                    raise BaseExceptionGroup('ошибка регистрации и закрытия FD', [ошибка, закрытие]) from None
            raise
        return новый
    except BaseException as ошибка:
        исходная = ошибка
        raise
    finally:
        try:
            signal.pthread_sigmask(signal.SIG_SETMASK, прежняя)
        except BaseException as восстановление:
            восстановление.add_note('Неизвестно состояние маски после сбоя восстановления')
            if исходная is not None:
                if исходная is восстановление:
                    raise
                if not isinstance(исходная, Exception):
                    исходная.add_note('Неизвестно состояние маски после сбоя восстановления')
                    raise исходная from восстановление
                if not isinstance(восстановление, Exception):
                    raise восстановление from исходная
                raise BaseExceptionGroup('ошибка получения FD и возврата маски', [исходная, восстановление]) from None
            raise


def _проверить_nul_обрамление_списка(сырые: bytes) -> None:
    """Пустой список допустим; непустой состоит из непустых NUL-записей."""
    if (type(сырые) is not bytes or сырые and
        (not сырые.endswith(b'\0') or сырые.startswith(b'\0') or b'\0\0' in сырые)):
        raise ОшибкаОтчёта('неверное NUL-обрамление списка Git')


@contextlib.contextmanager
def _удержать_каталог_отпечатка(корневой_fd: int | None, части: tuple[str, ...]):
    """Открыть цепочку каталогов относительно удерживаемого дескриптора."""
    дескрипторы: list[int] = []
    цепочка = []
    родитель = корневой_fd
    ошибка = None
    try:
        for имя in части:
            fd = _приобрести_fd(
                дескрипторы, os.open, имя,
                os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC,
                dir_fd=родитель,
            )
            цепочка.append((родитель, имя, fd, os.fstat(fd)))
            родитель = fd

        def сверить() -> None:
            for старший, имя, fd, метка in цепочка:
                адрес = os.stat(имя, dir_fd=старший, follow_symlinks=False)
                if not os.path.samestat(метка, адрес) or not os.path.samestat(метка, os.fstat(fd)):
                    raise ОшибкаОтчёта("каталог содержательного отпечатка был подменён")

        сверить()
        yield родитель, сверить
        сверить()
    except BaseException as исходная:
        ошибка = исходная
        raise
    finally:
        _закрыть_удержанные_fd(
            дескрипторы, ошибка, "каталога содержательного отпечатка", _сохранять_ошибки=True,
        )


def _прочитать_вход_отпечатка(корневой_fd: int, имя: str) -> tuple[int, bytes] | None:
    части = PurePosixPath(имя).parts
    дескрипторы: list[int] = []
    ошибка = None
    найден = False

    def метка(сведения: os.stat_result) -> tuple[int, ...]:
        return (сведения.st_dev, сведения.st_ino, сведения.st_mode,
                сведения.st_size, сведения.st_mtime_ns, сведения.st_ctime_ns)

    try:
        with _удержать_каталог_отпечатка(корневой_fd, части[:-1]) as (родитель, _):
            до = os.stat(части[-1], dir_fd=родитель, follow_symlinks=False)
            найден = True
            if not stat.S_ISREG(до.st_mode):
                raise ОшибкаОтчёта("содержательный отпечаток требует обычные файлы без символических ссылок")
            fd = _приобрести_fd(
                дескрипторы, os.open, части[-1],
                os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK | os.O_CLOEXEC,
                dir_fd=родитель,
            )
            if метка(os.fstat(fd)) != метка(до):
                raise ОшибкаОтчёта(f"входной файл подменён до чтения: {имя}")
            with os.fdopen(fd, "rb", closefd=False) as файл:
                содержимое = файл.read(до.st_size + 1)
            if (len(содержимое) != до.st_size or метка(os.fstat(fd)) != метка(до)
                or метка(os.stat(части[-1], dir_fd=родитель, follow_symlinks=False)) != метка(до)):
                raise ОшибкаОтчёта(f"входной файл изменён при чтении: {имя}")
            return stat.S_IMODE(до.st_mode), содержимое
    except FileNotFoundError as исходная:
        if найден:
            ошибка = ОшибкаОтчёта(f"входной файл исчез при чтении: {имя}")
            raise ошибка from исходная
        return None
    except OSError as исходная:
        ошибка = ОшибкаОтчёта(f"не удалось безопасно прочитать входной файл: {имя}")
        raise ошибка from исходная
    except BaseException as исходная:
        ошибка = исходная
        raise
    finally:
        _закрыть_удержанные_fd(
            дескрипторы, ошибка, "входного файла содержательного отпечатка", _сохранять_ошибки=True,
        )


def _сигнатура_входа_отпечатка(вход: tuple[int, bytes] | None) -> tuple[int, bytes] | None:
    if вход is None:
        return None
    режим, содержимое = вход
    return режим, hashlib.sha256(содержимое).digest()


def _сверить_состояние_подмодуля_отпечатка(читать, вершина: bytes, индекс: bytes) -> None:
    if (читать("ls-files", "--stage", "-z") != индекс
        or читать("ls-files", "--others", "--exclude-standard", "-z", "--", ".")
        or читать("rev-parse", "--verify", "HEAD") != вершина):
        raise ОшибкаОтчёта("содержательный отпечаток содержит изменённый подмодуль")


def _добавить_подмодуль_в_отпечаток(хэш, корень: Path, корневой_fd: int, имя: str, читать,
                                    наблюдения: list[tuple[str, tuple[int, bytes] | None]],
                                    наблюдения_подмодулей: list[tuple[str, bytes, bytes]]) -> None:
    путь = корень / имя
    try:
        with _удержать_каталог_отпечатка(корневой_fd, PurePosixPath(имя).parts) as (fd, сверить_каталог):
            def читать_подмодуль(*аргументы: str) -> bytes:
                сверить_каталог()
                данные = читать(путь, *аргументы)
                сверить_каталог()
                return данные

            if читать_подмодуль("rev-parse", "--show-toplevel") != os.fsencode(путь) + b"\n":
                raise ОшибкаОтчёта("подмодуль не материализован в своём каталоге")
            вершина_с_переносом = читать_подмодуль("rev-parse", "--verify", "HEAD")
            if re.fullmatch(rb"(?:[0-9a-f]{40}|[0-9a-f]{64})\n", вершина_с_переносом) is None:
                raise ОшибкаОтчёта("неверная вершина подмодуля")
            вершина = вершина_с_переносом[:-1]
            алгоритм = {40: "sha1", 64: "sha256"}[len(вершина)]
            дерево = читать_подмодуль("ls-tree", "-r", "-z", вершина.decode("ascii"))
            _проверить_nul_обрамление_списка(дерево)
            файлы_подмодуля: dict[bytes, tuple[bytes, bytes]] = {}
            for запись_дерева in дерево.split(b"\0")[:-1]:
                описание_файла, разделитель, имя_файла = запись_дерева.partition(b"\t")
                поля = описание_файла.split(b" ")
                if not разделитель or not имя_файла or имя_файла in файлы_подмодуля or len(поля) != 3:
                    raise ОшибкаОтчёта("неверная запись дерева подмодуля")
                режим_файла, тип_объекта, объект = поля
                if (тип_объекта != b"blob" or режим_файла not in {b"100644", b"100755"}
                    or len(объект) != len(вершина) or re.fullmatch(rb"[0-9a-f]+", объект) is None):
                    raise ОшибкаОтчёта("подмодуль содержит неподдерживаемую ссылку или вложенный подмодуль")
                файлы_подмодуля[имя_файла] = режим_файла, объект
            ожидаемый_индекс = b"".join(
                режим + b" " + объект + b" 0\t" + имя_файла + b"\0"
                for имя_файла, (режим, объект) in sorted(файлы_подмодуля.items())
            )

            def сверить_подмодуль() -> None:
                _сверить_состояние_подмодуля_отпечатка(
                    читать_подмодуль, вершина_с_переносом, ожидаемый_индекс,
                )

            сверить_подмодуль()
            for имя_файла, (режим_файла, объект) in файлы_подмодуля.items():
                имя_внутри = проверить_аналитический_ключ(
                    имя_файла.decode("utf-8"), "вход подмодуля",
                )
                if any(часть.casefold() == ".git" for часть in имя_внутри.split("/")):
                    raise ОшибкаОтчёта("служебный путь недопустим во входе подмодуля")
                вход = _прочитать_вход_отпечатка(fd, имя_внутри)
                if вход is None:
                    raise ОшибкаОтчёта("не удалось прочитать вход подмодуля")
                режим, содержимое_файла = вход
                объект_файла = hashlib.new(алгоритм)
                объект_файла.update(b"blob " + str(len(содержимое_файла)).encode("ascii") + b"\0")
                объект_файла.update(содержимое_файла)
                if объект_файла.hexdigest().encode("ascii") != объект:
                    raise ОшибкаОтчёта("содержимое подмодуля отличается от его вершины")
                if bool(режим & stat.S_IXUSR) != (режим_файла == b"100755"):
                    raise ОшибкаОтчёта("исполняемый режим подмодуля отличается от его вершины")
                наблюдения.append((f"{имя}/{имя_внутри}", _сигнатура_входа_отпечатка(вход)))
                добавить_часть_отпечатка(
                    хэш, f"файл-подмодуля:{имя}/{имя_внутри}:{режим:o}", содержимое_файла,
                )
            сверить_подмодуль()
            наблюдения_подмодулей.append((имя, вершина_с_переносом, ожидаемый_индекс))
            добавить_часть_отпечатка(хэш, f"подмодуль:{имя}", вершина)
    except (OSError, UnicodeError) as ошибка:
        raise ОшибкаОтчёта(f"не удалось безопасно прочитать подмодуль: {имя}") from ошибка


def вычислить_отпечаток_содержимого(
    корень_репозитория: str | Path,
    сессия: str | Path,
) -> str:
    """Хэш дисковых входов; HEAD родителя и представление индекса не входят."""
    корень = Path(корень_репозитория).resolve()
    сессия_путь = проверить_аналитический_ключ(Path(сессия).as_posix(), "путь сессии")
    отчёт = f"{сессия_путь}/{ИМЯ_ОТЧЁТА}"
    запуски = f"{сессия_путь}/{ОТНОСИТЕЛЬНЫЙ_КАТАЛОГ_ЗАПУСКОВ.as_posix()}"
    try:
        with _удержать_каталог_отпечатка(None, корень.parts) as (корневой_fd, сверить_корень):
            проверить_чистоту_подмодулей(корень)
            читать = выполнить_чтение_репозитория
            индекс = читать(корень, "ls-files", "--stage", "-z")
            аргументы_новых = ("ls-files", "--others", "--exclude-standard", "-z")
            неотслеживаемые = читать(корень, *аргументы_новых)
            сверить_корень()
            _проверить_nul_обрамление_списка(индекс)
            _проверить_nul_обрамление_списка(неотслеживаемые)
            пути = set(неотслеживаемые.split(b"\0")[:-1])
            подмодули: set[bytes] = set()
            for запись in индекс.split(b"\0")[:-1]:
                описание, разделитель, имя = запись.partition(b"\t")
                if (not разделитель or not имя
                    or re.fullmatch(rb"[0-7]{6} (?:[0-9a-f]{40}|[0-9a-f]{64}) [0-3]", описание) is None):
                    raise ОшибкаОтчёта("неверная запись списка Git index")
                if not описание.endswith(b" 0"):
                    raise ОшибкаОтчёта("содержательный отпечаток запрещён при конфликте индекса")
                пути.add(имя)
                if описание.startswith(b"160000 "):
                    подмодули.add(имя)
            хэш = hashlib.sha256()
            наблюдения: list[tuple[str, tuple[int, bytes] | None]] = []
            наблюдения_подмодулей: list[tuple[str, bytes, bytes]] = []
            добавить_часть_отпечатка(хэш, "схема", "fum.каноническое-содержимое.1".encode("utf-8"))
            for сырое_имя in sorted(пути):
                имя = сырое_имя.decode("utf-8")
                if имя == отчёт or имя == запуски or имя.startswith(f"{запуски}/"):
                    continue
                if путь_в_производном_пространстве(имя):
                    continue
                имя = проверить_аналитический_ключ(имя, "путь содержательного отпечатка")
                if сырое_имя in подмодули:
                    _добавить_подмодуль_в_отпечаток(
                        хэш, корень, корневой_fd, имя, читать, наблюдения, наблюдения_подмодулей,
                    )
                    continue
                вход = _прочитать_вход_отпечатка(корневой_fd, имя)
                наблюдения.append((имя, _сигнатура_входа_отпечатка(вход)))
                if вход is None:
                    # Удаление остаётся тем же входом после staging и commit.
                    continue
                режим, содержимое = вход
                добавить_часть_отпечатка(хэш, f"файл:{имя}:{режим:o}", содержимое)
            for имя, сигнатура in наблюдения:
                if _сигнатура_входа_отпечатка(_прочитать_вход_отпечатка(корневой_fd, имя)) != сигнатура:
                    raise ОшибкаОтчёта(f"вход содержательного отпечатка изменился во время чтения: {имя}")
            for имя, вершина, индекс_подмодуля in наблюдения_подмодулей:
                путь = корень / имя
                with _удержать_каталог_отпечатка(корневой_fd, PurePosixPath(имя).parts) as (_, сверить):
                    def читать_повторно(*аргументы: str) -> bytes:
                        сверить()
                        результат = читать(путь, *аргументы)
                        сверить()
                        return результат
                    if читать_повторно("rev-parse", "--show-toplevel") != os.fsencode(путь) + b"\n":
                        raise ОшибкаОтчёта("подмодуль изменил рабочий каталог при повторной сверке")
                    _сверить_состояние_подмодуля_отпечатка(
                        читать_повторно, вершина, индекс_подмодуля,
                    )
            if (читать(корень, "ls-files", "--stage", "-z") != индекс
                or читать(корень, *аргументы_новых) != неотслеживаемые):
                raise ОшибкаОтчёта("состав содержательного отпечатка изменился во время чтения")
    except (OSError, UnicodeError) as ошибка:
        raise ОшибкаОтчёта("не удалось безопасно вычислить содержательный отпечаток") from ошибка
    return f"sha256:{хэш.hexdigest()}"


def проверить_полные_наборы(значение: object) -> list[str]:
    if not isinstance(значение, list):
        raise ОшибкаОтчёта("полные_наборы должны быть списком")
    результат: list[str] = []
    приведённые: set[str] = set()
    for номер, значение_ключа in enumerate(значение, start=1):
        ключ = проверить_аналитический_ключ(
            значение_ключа, f"полный набор { номер}"
        )
        приведённый = ключ.casefold()
        if приведённый in приведённые:
            raise ОшибкаОтчёта(f"повторный полный набор: {ключ}")
        приведённые.add(приведённый)
        результат.append(ключ)
    return результат


def проверить_профиль_проверки(
    значение: object,
    план: Sequence[dict[str, str]] | None,
    наблюдения: Sequence[dict[str, object]],
    состояние: str,
) -> dict[str, object]:
    if not isinstance(значение, dict) or set(значение) != ПОЛЯ_ПРОФИЛЯ_ПРОВЕРКИ:
        raise ОшибкаОтчёта("неверный набор полей профиля проверки")
    класс = значение["класс"]
    if not isinstance(класс, str) or класс not in КЛАССЫ_ПРОВЕРОК:
        raise ОшибкаОтчёта("неверный класс проверки")
    отпечаток = значение["отпечаток_снимка"]
    if not isinstance(отпечаток, str) or re.fullmatch(
        r"sha256:[0-9a-f]{64}", отпечаток
    ) is None:
        raise ОшибкаОтчёта("неверный отпечаток Git-снимка")
    полные_наборы = проверить_полные_наборы(
        значение["полные_наборы"]
    )
    основание = значение["основание"]
    идентификатор_отказа = значение["идентификатор_отказа"]
    свидетельство = значение["ожидаемое_свидетельство"]
    if основание is not None and not isinstance(основание, str):
        raise ОшибкаОтчёта("основание профиля должно быть строкой или null")
    if идентификатор_отказа is not None:
        проверить_идентификатор(идентификатор_отказа)
    if свидетельство is not None:
        проверить_строку(свидетельство, "ожидаемое_свидетельство")
    if класс == "адресная":
        if полные_наборы or any(
            значение[поле] is not None
            for поле in (
                "основание",
                "идентификатор_отказа",
                "ожидаемое_свидетельство",
            )
        ):
            raise ОшибкаОтчёта("адресная проверка не объявляет полные наборы или диагностику")
    elif класс == "диагностическая":
        if not полные_наборы or основание not in ОСНОВАНИЯ_ДИАГНОСТИКИ or not свидетельство:
            raise ОшибкаОтчёта("диагностическая проверка требует наборы, основание и ожидаемое свидетельство")
        if (
            основание == "локализация_наблюдаемого_отказа"
        ) != (идентификатор_отказа is not None):
            raise ОшибкаОтчёта("локализация требует точный UUID предшествующего неуспешного запуска")
    else:
        if any(
            значение[поле] is not None
            for поле in (
                "основание",
                "идентификатор_отказа",
            )
        ):
            raise ОшибкаОтчёта("полная проверка не объявляет диагностику")
        if свидетельство is not None and (
            состояние != "завершён"
            or re.fullmatch(r"fum\.контур-проверки-слияния\.1:sha256:[0-9a-f]{64}", свидетельство) is None
        ):
            raise ОшибкаОтчёта("полная проверка допускает только завершённое подтверждение контура")
        ожидаемые_ключи = (
            [элемент["ключ_проверки"] for элемент in план]
            if план is not None
            else []
        )
        if полные_наборы != ожидаемые_ключи:
            raise ОшибкаОтчёта("наборы полной проверки не выведены из фактического плана")
    if класс != "полная" and (план is not None or наблюдения):
        raise ОшибкаОтчёта("план и наблюдения допустимы только для полной проверки")
    if состояние == "выполняется" and (план is not None or наблюдения):
        raise ОшибкаОтчёта("активная профилированная запись содержит наблюдения")
    return значение


def проверить_план_наблюдений(
    значение: object,
) -> list[dict[str, str]] | None:
    if значение is None:
        return None
    if not isinstance(значение, list):
        raise ОшибкаОтчёта(
            "план наблюдений smoke-check должен быть списком или null"
        )
    результат: list[dict[str, str]] = []
    приведённые_ключи: set[str] = set()
    for номер, элемент in enumerate(значение, start=1):
        if not isinstance(элемент, dict) or set(элемент) != ПОЛЯ_ЭЛЕМЕНТА_ПЛАНА:
            raise ОшибкаОтчёта(
                f"неверный набор полей плана наблюдений smoke-check: {номер}"
            )
        ключ = проверить_аналитический_ключ(
            элемент["ключ_проверки"],
            f"ключ_проверки плана {номер}",
        )
        название = проверить_строку(
            элемент["название"],
            f"название плана {номер}",
        )
        приведённый = ключ.casefold()
        if приведённый in приведённые_ключи:
            raise ОшибкаОтчёта(
                f"регистронезависимая коллизия ключа в плане smoke-check: {ключ}"
            )
        приведённые_ключи.add(приведённый)
        результат.append({"ключ_проверки": ключ, "название": название})
    return результат


def проверить_префикс_наблюдений(
    план: Sequence[dict[str, str]] | None,
    наблюдения: Sequence[dict[str, object]],
) -> None:
    if план is None:
        if наблюдения:
            raise ОшибкаОтчёта(
                "наблюдения smoke-check записаны до формирования плана"
            )
        return
    if len(наблюдения) > len(план):
        raise ОшибкаОтчёта("наблюдения smoke-check длиннее плана")
    for номер, наблюдение in enumerate(наблюдения):
        if any(
            наблюдение[поле] != план[номер][поле]
            for поле in ("ключ_проверки", "название")
        ):
            raise ОшибкаОтчёта(
                "наблюдения smoke-check не образуют точный префикс плана"
            )


def проверить_текущую_проверку(
    значение: object,
    план: Sequence[dict[str, str]] | None,
    наблюдения: Sequence[dict[str, object]],
) -> dict[str, object] | None:
    if значение is None:
        return None
    if (
        not isinstance(значение, dict)
        or set(значение) != ПОЛЯ_ТЕКУЩЕЙ_ПРОВЕРКИ
        or план is None
        or len(наблюдения) >= len(план)
    ):
        raise ОшибкаОтчёта("неверная текущая проверка smoke-check")
    for поле in ("ключ_проверки", "название"):
        проверить_строку(значение[поле], f"{поле} текущей проверки")
        if значение[поле] != план[len(наблюдения)][поле]:
            raise ОшибкаОтчёта(
                "текущая проверка smoke-check не совпадает со следующим шагом плана"
            )
    начало = значение["начало_монотонные_наносекунды"]
    if isinstance(начало, bool) or not isinstance(начало, int) or начало < 0:
        raise ОшибкаОтчёта(
            "неверное монотонное начало текущей проверки smoke-check"
        )
    if any(наблюдение["статус"] != "успешно" for наблюдение in наблюдения):
        raise ОшибкаОтчёта(
            "текущая проверка smoke-check следует после fail-fast исхода"
        )
    return значение


def загрузить_контур_слияния():
    путь = (Path(__file__).resolve().parents[2] / "fum-kompleksnaya-proverka-repozitoriya/scripts/контур_слияния.py")
    модуль = types.ModuleType("контур_слияния")
    модуль.__file__ = str(путь)
    exec(compile(путь.read_bytes(), str(путь), "exec"), модуль.__dict__)
    return модуль


def индекс_канонического_исполнителя_проверок(
    корень: Path,
    команда: Sequence[str],
) -> int | None:
    канонический = (корень / ПУТЬ_ПОЛНОЙ_ПРОВЕРКИ).resolve()
    if not команда:
        return None

    def совпадает(аргумент: str) -> bool:
        путь = Path(аргумент)
        if not путь.is_absolute():
            путь = корень / путь
        try:
            return путь.resolve() == канонический
        except OSError:
            return False

    if совпадает(команда[0]):
        return 0
    имя_исполнителя = Path(команда[0]).name.lower()
    if re.fullmatch(r"python(?:[0-9]+(?:\.[0-9]+)*)?", имя_исполнителя) is None:
        return None
    индекс = 1
    while индекс < len(команда) and команда[индекс] in {
        "-B", "-E", "-I", "-O", "-OO", "-P", "-s", "-S", "-u"
    }:
        индекс += 1
    return индекс if индекс < len(команда) and совпадает(команда[индекс]) else None


def является_неполной_проверкой_проекции(корень: Path, команда: Sequence[str]) -> bool:
    индекс = индекс_канонического_исполнителя_проверок(корень, команда)
    if индекс is None:
        флаги_проекции = ("--проекция", "--основание-отложения-проекции")
        if any(аргумент.startswith("--") and аргумент != "--" and
               any(флаг.startswith(аргумент.split("=", 1)[0]) for флаг in флаги_проекции)
               for аргумент in команда):
            канонический = (корень / ПУТЬ_ПОЛНОЙ_ПРОВЕРКИ).resolve()
            for аргумент in команда:
                путь = Path(аргумент)
                if not путь.is_absolute():
                    путь = корень / путь
                try:
                    if путь.resolve() == канонический:
                        raise ОшибкаОтчёта("неподдержанный исполнитель режима проекции")
                except OSError:
                    continue
        return False
    аргументы = команда[индекс + 1:]
    режимы: list[str | None] = []
    есть_основание = False
    for номер, аргумент in enumerate(аргументы):
        if аргумент == "--":
            break
        флаг = аргумент.split("=", 1)[0]
        if флаг == "--проекция":
            режимы.append(аргумент.split("=", 1)[1] if "=" in аргумент else
                          аргументы[номер + 1] if номер + 1 < len(аргументы) else None)
        elif флаг.startswith("--") and флаг != "--" and "--проекция".startswith(флаг):
            return True
        elif флаг.startswith("--") and флаг != "--" and "--основание-отложения-проекции".startswith(флаг):
            есть_основание = True
    # Основание допустимо только с отложенным режимом: такой вызов всегда неполон.
    return есть_основание or len(режимы) > 1 or any(режим != "активна" for режим in режимы)


def _отказать_неподтверждённому_контуру(корень: Path, команда: Sequence[str]) -> None:
    """Проверить прямой smoke с параметрами закрытого контура без загрузки кода."""
    if not команда:
        return
    параметры_контура = ("--источник-проверок", "--ведущая-основа",
                         "--свидетельство-контура")

    def есть_параметр(аргументы: Sequence[str]) -> bool:
        for аргумент in аргументы:
            if аргумент == "--":
                break
            флаг = аргумент.split("=", 1)[0]
            if флаг.startswith("--") and флаг != "--" and any(
                имя.startswith(флаг) for имя in параметры_контура
            ):
                return True
        return False

    def неизвестно(причина: BaseException) -> None:
        raise ОшибкаОтчёта("неизвестна физическая идентичность прямой команды") from причина

    def метка_или_отсутствует(путь: Path):
        try:
            результат = os.stat(путь)
        except OSError as причина:
            if причина.errno in (errno.ENOENT, errno.ENOTDIR):
                return None
            неизвестно(причина)
        except ValueError as причина:
            неизвестно(причина)
        if результат.st_ino <= 0:
            неизвестно(ValueError("недостоверный номер inode"))
        return результат

    def совпадает(аргумент: str) -> bool:
        путь = Path(аргумент)
        if not путь.is_absolute():
            путь = корень / путь
        try:
            нормальный = путь.resolve()
            исходный = Path(__file__).resolve().parents[3]
        except (OSError, RuntimeError, ValueError, IndexError) as причина:
            неизвестно(причина)
        цели = (корень / ПУТЬ_ПОЛНОЙ_ПРОВЕРКИ,
                исходный / ПУТЬ_ПОЛНОЙ_ПРОВЕРКИ)
        ошибка_цели = None
        for цель in цели:
            try:
                if нормальный == цель.resolve():
                    return True
            except (OSError, RuntimeError, ValueError) as причина:
                if ошибка_цели is None:
                    ошибка_цели = причина
        метка = метка_или_отсутствует(путь)
        if метка is None:
            return False
        for цель in цели:
            try:
                ожидаемая = метка_или_отсутствует(цель)
            except ОшибкаОтчёта as причина:
                if ошибка_цели is None:
                    ошибка_цели = причина
                continue
            if (ожидаемая is not None
                and (метка.st_dev, метка.st_ino) == (ожидаемая.st_dev, ожидаемая.st_ino)):
                return True
        if ошибка_цели is not None:
            неизвестно(ошибка_цели)
        return False

    def проверить(аргумент: str) -> None:
        if совпадает(аргумент):
            raise ОшибкаОтчёта("контур слияния закрыт до подтверждения его источника")

    if есть_параметр(команда[1:]):
        проверить(команда[0])
    имя = Path(команда[0]).name.lower()
    if re.fullmatch(r"python(?:[0-9]+(?:\.[0-9]+)*)?", имя) is None:
        return
    индекс = 1
    while индекс < len(команда):
        параметр = команда[индекс]
        if параметр == "--":
            индекс += 1
            break
        if параметр == "--check-hash-based-pycs":
            if индекс + 1 >= len(команда):
                return
            индекс += 2
            continue
        if параметр.startswith("--check-hash-based-pycs="):
            индекс += 1
            continue
        if not параметр.startswith("-") or параметр == "-" or параметр.startswith("--"):
            break
        for позиция, флаг in enumerate(параметр[1:], start=1):
            if флаг in "BEIOPSsubdiqvx":
                continue
            if флаг in "XW":
                if позиция + 1 < len(параметр):
                    индекс += 1
                elif индекс + 1 < len(команда):
                    индекс += 2
                else:
                    return
                break
            # -c и -m не обозначают прямой вызов проверяемого скрипта.
            return
        else:
            индекс += 1
    if индекс < len(команда) and есть_параметр(команда[индекс + 1:]):
        проверить(команда[индекс])


def _обычная_полная_проверка(корень: Path, команда: Sequence[str]) -> bool:
    if является_неполной_проверкой_проекции(корень, команда):
        return False
    return "--list" not in команда and индекс_канонического_исполнителя_проверок(корень, команда) is not None


def является_запуском_полной_проверки(корень: Path, команда: Sequence[str]) -> bool:
    _отказать_неподтверждённому_контуру(корень, команда)
    return _обычная_полная_проверка(корень, команда)


def прочитать_конверт_наблюдений(
    путь: Path,
    идентификатор: str,
) -> tuple[
    list[dict[str, str]] | None,
    list[dict[str, object]],
    dict[str, object] | None,
]:
    if not путь.exists():
        raise ОшибкаОтчёта("обязательный конверт наблюдений smoke-check отсутствует")
    try:
        значение, байты = прочитать_машинную_запись(путь)
    except ОшибкаОтчёта as ошибка:
        raise ОшибкаОтчёта(
            "не удалось прочитать обязательный конверт наблюдений smoke-check"
        ) from ошибка
    if байты != канонические_машинные_байты(значение):
        raise ОшибкаОтчёта("конверт наблюдений smoke-check неканоничен")
    if not isinstance(значение, dict) or set(значение) != ПОЛЯ_КОНВЕРТА_НАБЛЮДЕНИЙ:
        raise ОшибкаОтчёта("неверный набор полей конверта наблюдений smoke-check")
    if значение["схема"] != СХЕМА_НАБЛЮДЕНИЙ_ПОЛНОЙ_ПРОВЕРКИ:
        raise ОшибкаОтчёта("неверная схема конверта наблюдений smoke-check")
    if значение["идентификатор_запуска"] != идентификатор:
        raise ОшибкаОтчёта(
            "конверт наблюдений smoke-check принадлежит другому запуску"
        )
    план = проверить_план_наблюдений(значение["план"])
    наблюдения = проверить_наблюдения(значение["наблюдения"])
    проверить_префикс_наблюдений(план, наблюдения)
    текущая_проверка = проверить_текущую_проверку(
        значение["текущая_проверка"],
        план,
        наблюдения,
    )
    return план, наблюдения, текущая_проверка


def начальный_конверт_наблюдений(
    идентификатор: str,
) -> dict[str, object]:
    return {
        "схема": СХЕМА_НАБЛЮДЕНИЙ_ПОЛНОЙ_ПРОВЕРКИ,
        "идентификатор_запуска": идентификатор,
        "план": None,
        "наблюдения": [],
        "текущая_проверка": None,
    }


def проверить_согласованность_наблюдений(
    план: Sequence[dict[str, str]] | None,
    наблюдения: Sequence[dict[str, object]],
    статус: str,
    длительность_наносекунды: int,
) -> None:
    проверить_префикс_наблюдений(план, наблюдения)
    неуспешные = [
        номер
        for номер, наблюдение in enumerate(наблюдения)
        if наблюдение["статус"] != "успешно"
    ]
    if len(неуспешные) > 1 or (
        неуспешные and неуспешные[0] != len(наблюдения) - 1
    ):
        raise ОшибкаОтчёта(
            "наблюдения smoke-check нарушают последовательный fail-fast"
        )
    if статус == "успешно" and (
        план is None
        or len(наблюдения) != len(план)
        or неуспешные
    ):
        raise ОшибкаОтчёта(
            "успешный smoke-check не подтвердил полный успешный тестовый план"
        )
    сумма = sum(
        int(наблюдение["длительность_наносекунды"])
        for наблюдение in наблюдения
    )
    if сумма > длительность_наносекунды:
        raise ОшибкаОтчёта(
            "сумма длительностей тестов превышает длительность smoke-check"
        )


def проверить_отпечаток_раундов(значение: object, поле: str) -> str:
    if not isinstance(значение, str) or re.fullmatch(r"sha256:[0-9a-f]{64}", значение) is None:
        raise ОшибкаОтчёта(f"неверный отпечаток: {поле}")
    return значение


def проверить_переход_схемы(значение: object) -> dict[str, object] | None:
    if значение is None:
        return None
    if not isinstance(значение, dict) or set(значение) != ПОЛЯ_ПЕРЕХОДА_СХЕМЫ:
        raise ОшибкаОтчёта("неверный набор полей перехода схемы")
    for поле in ("последний_порядок", "число_записей"):
        число = значение[поле]
        if isinstance(число, bool) or not isinstance(число, int) or число <= 0:
            raise ОшибкаОтчёта(f"неверная граница перехода: {поле}")
    проверить_отпечаток_раундов(значение["хэш_префикса"], "хэш_префикса")
    коммит = значение["исходный_коммит"]
    if not isinstance(коммит, str) or re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", коммит) is None:
        raise ОшибкаОтчёта("переход требует полный идентификатор исходного коммита")
    изменения = значение["изменения_контракта"]
    if not isinstance(изменения, list) or not изменения:
        raise ОшибкаОтчёта("переход требует изменения контракта")
    пути: list[str] = []
    for изменение in изменения:
        if not isinstance(изменение, dict) or set(изменение) != ПОЛЯ_ИЗМЕНЕНИЯ_КОНТРАКТА:
            raise ОшибкаОтчёта("неверные поля изменения контракта")
        пути.append(проверить_аналитический_ключ(изменение["путь"], "путь контракта"))
        до = проверить_отпечаток_раундов(изменение["до_sha256"], "до_sha256")
        после = проверить_отпечаток_раундов(изменение["после_sha256"], "после_sha256")
        if до == после:
            raise ОшибкаОтчёта("переход требует фактическое изменение контракта")
    if пути != sorted(пути) or len({путь.casefold() for путь in пути}) != len(пути):
        raise ОшибкаОтчёта("пути контракта должны быть уникальны и отсортированы")
    return значение


def проверить_запись(
    значение: object,
    имя_файла: str,
    сессия: str,
) -> dict[str, object]:
    if not isinstance(значение, dict):
        raise ОшибкаОтчёта(f"неверный набор полей записи: {имя_файла}")
    схема = значение.get("схема")
    if схема == СХЕМА_ЗАПУСКА:
        ожидаемые_поля = ПОЛЯ_ЗАПИСИ
    elif схема == СХЕМА_ЗАПУСКА_С_НАБЛЮДЕНИЯМИ:
        ожидаемые_поля = ПОЛЯ_ЗАПИСИ_С_НАБЛЮДЕНИЯМИ
    elif схема == СХЕМА_ПРОФИЛИРОВАННОГО_ЗАПУСКА:
        ожидаемые_поля = ПОЛЯ_ПРОФИЛИРОВАННОЙ_ЗАПИСИ
    elif схема == СХЕМА_ЗАПУСКА_С_РАУНДАМИ:
        ожидаемые_поля = ПОЛЯ_ЗАПИСИ_С_РАУНДАМИ
    else:
        raise ОшибкаОтчёта(f"неверная схема записи: {имя_файла}")
    if set(значение) != ожидаемые_поля:
        raise ОшибкаОтчёта(f"неверный набор полей записи: {имя_файла}")
    if схема == СХЕМА_ЗАПУСКА_С_РАУНДАМИ:
        проверить_отпечаток_раундов(значение["отпечаток_содержимого"], "отпечаток_содержимого")
        проверить_переход_схемы(значение["переход_схемы"])
    совпадение = ИМЯ_ФАЙЛА_ЗАПУСКА.fullmatch(имя_файла)
    if совпадение is None:
        raise ОшибкаОтчёта(f"неверное имя файла запуска: {имя_файла}")
    идентификатор = проверить_идентификатор(значение["идентификатор"])
    if идентификатор != совпадение.group("идентификатор"):
        raise ОшибкаОтчёта(f"UUID записи не совпадает с именем: {имя_файла}")
    if значение["сессия"] != сессия:
        raise ОшибкаОтчёта(f"запись принадлежит другой сессии: {имя_файла}")
    порядок = значение["порядок"]
    if isinstance(порядок, bool) or not isinstance(порядок, int) or порядок <= 0:
        raise ОшибкаОтчёта(f"неверный порядок записи: {имя_файла}")
    if порядок != int(совпадение.group("порядок")):
        raise ОшибкаОтчёта(f"порядок записи не совпадает с именем: {имя_файла}")
    проверить_строку(значение["исполнитель"], "исполнитель")
    проверить_строку(значение["вызов"], "вызов")
    состояние = значение["состояние"]
    if not isinstance(состояние, str) or состояние not in СОСТОЯНИЯ:
        raise ОшибкаОтчёта(f"неверное состояние записи: {имя_файла}")
    if схема in {
        СХЕМА_ЗАПУСКА_С_НАБЛЮДЕНИЯМИ,
        СХЕМА_ПРОФИЛИРОВАННОГО_ЗАПУСКА,
        СХЕМА_ЗАПУСКА_С_РАУНДАМИ,
    }:
        план = проверить_план_наблюдений(значение["план"])
        наблюдения = проверить_наблюдения(значение["наблюдения"])
        проверить_префикс_наблюдений(план, наблюдения)
        if состояние == "выполняется" and (
            план is not None or наблюдения
        ):
            raise ОшибкаОтчёта(
                f"активная запись содержит план или наблюдения: {имя_файла}"
            )
        if схема in {СХЕМА_ПРОФИЛИРОВАННОГО_ЗАПУСКА, СХЕМА_ЗАПУСКА_С_РАУНДАМИ}:
            проверить_профиль_проверки(
                значение["профиль_проверки"],
                план,
                наблюдения,
                состояние,
            )

    терминальные_поля = (
        значение["длительность_наносекунды"],
        значение["статус"],
        значение["код_завершения"],
        значение["пояснение"],
    )
    if состояние == "выполняется":
        if any(поле is not None for поле in терминальные_поля):
            raise ОшибкаОтчёта(
                f"активная запись содержит терминальные поля: {имя_файла}"
            )
        return значение

    длительность = значение["длительность_наносекунды"]
    if (
        isinstance(длительность, bool)
        or not isinstance(длительность, int)
        or длительность < 0
    ):
        raise ОшибкаОтчёта(f"неверная длительность записи: {имя_файла}")
    статус = значение["статус"]
    if not isinstance(статус, str) or статус not in СТАТУСЫ:
        raise ОшибкаОтчёта(f"неверный статус записи: {имя_файла}")
    код = значение["код_завершения"]
    if код is not None and (isinstance(код, bool) or not isinstance(код, int)):
        raise ОшибкаОтчёта(f"неверный код завершения: {имя_файла}")
    if (
        (статус == "успешно" and код != 0)
        or (статус == "неуспешно" and (код is None or код <= 0))
        or (статус == "прервано" and (код is None or код >= 0))
        or (статус == "не завершено" and (код is None or код <= 0))
    ):
        raise ОшибкаОтчёта(
            f"статус записи противоречит коду завершения: {имя_файла}"
        )
    пояснение = значение["пояснение"]
    if пояснение is not None:
        проверить_строку(
            пояснение,
            "пояснение",
            разрешить_пустую=True,
        )
    if схема == СХЕМА_ЗАПУСКА_С_НАБЛЮДЕНИЯМИ or (
        схема in {СХЕМА_ПРОФИЛИРОВАННОГО_ЗАПУСКА, СХЕМА_ЗАПУСКА_С_РАУНДАМИ}
        and значение["профиль_проверки"]["класс"] == "полная"
    ):
        проверить_согласованность_наблюдений(
            план,
            наблюдения,
            статус,
            длительность,
        )
    return значение


def прочитать_записи(
    каталог: Path,
    сессия: str,
    *,
    разрешить_раунды: bool = False,
) -> list[tuple[Path, dict[str, object], bytes]]:
    if not каталог.exists():
        raise ОшибкаОтчёта(f"каталог запусков отсутствует: {каталог}")
    if каталог.is_symlink() or not каталог.is_dir():
        raise ОшибкаОтчёта(f"каталог запусков должен быть обычным каталогом: {каталог}")
    записи: list[tuple[Path, dict[str, object], bytes]] = []
    for путь in sorted(каталог.iterdir(), key=lambda элемент: элемент.name):
        if путь.name in {ИМЯ_СНИМКА, ИМЯ_ЖУРНАЛА_ВОЗОБНОВЛЕНИЯ}:
            if путь.is_symlink() or not путь.is_file():
                raise ОшибкаОтчёта(
                    f"служебный файл должен быть обычным файлом: {путь.name}"
                )
            continue
        if ИМЯ_ФАЙЛА_ЗАПУСКА.fullmatch(путь.name) is None:
            raise ОшибкаОтчёта(f"неизвестный файл в каталоге запусков: {путь.name}")
        значение, байты = прочитать_машинную_запись(путь)
        запись = проверить_запись(значение, путь.name, сессия)
        if запись["схема"] == СХЕМА_ЗАПУСКА_С_РАУНДАМИ and not разрешить_раунды:
            raise ОшибкаОтчёта("команда ещё не поддерживает приёмочные раунды v4")
        записи.append((путь, запись, байты))
    if not записи:
        raise ОшибкаОтчёта("машинный журнал не содержит ни одного запуска")
    порядки = [int(запись["порядок"]) for _, запись, _ in записи]
    идентификаторы = [str(запись["идентификатор"]) for _, запись, _ in записи]
    if len(set(порядки)) != len(порядки):
        raise ОшибкаОтчёта("машинный журнал содержит повтор порядка")
    if len(set(идентификаторы)) != len(идентификаторы):
        raise ОшибкаОтчёта("машинный журнал содержит повтор UUID")
    return sorted(
        записи,
        key=lambda элемент: (
            int(элемент[1]["порядок"]),
            str(элемент[1]["идентификатор"]),
        ),
    )


def журнал_возобновления_существует(каталог: Path) -> bool:
    путь = каталог / ИМЯ_ЖУРНАЛА_ВОЗОБНОВЛЕНИЯ
    return путь.exists() or путь.is_symlink()


def запретить_действие_при_возобновлении(
    каталог: Path,
    действие: str,
) -> None:
    if журнал_возобновления_существует(каталог):
        raise ОшибкаОтчёта(
            f"{действие} запрещено до завершения журнала возобновления"
        )


def экранировать_табличный_текст(значение: str) -> str:
    return значение.replace("\\", "\\\\").replace("|", "\\|")


def округлить_до_миллисекунд(наносекунды: int) -> int:
    return (наносекунды + 500_000) // 1_000_000


def отформатировать_секунды(миллисекунды: int, *, активный: bool = False) -> str:
    if активный:
        return "0,000"
    целые, дробные = divmod(миллисекунды, 1000)
    if дробные == 0:
        return str(целые)
    return f"{целые},{дробные:03d}".rstrip("0")


def табличная_строка(ячейки: Sequence[str], ширины: Sequence[int]) -> str:
    return "| " + " | ".join(
        ячейка.ljust(ширины[номер])
        for номер, ячейка in enumerate(ячейки)
    ) + " |"


НОРМАТИВНЫЙ_КОНТУР_УСПЕШНОЙ_СЕССИИ = (
    "адресные_красные_и_зелёные_проверки",
    "изменённые_плановые_контракты",
    "свежесть",
    "связность_сессии",
    "финальная_комплексная_проверка",
    "закрытие_отчёта",
    "локальный_коммит_этапа_на_master",
)


def профиль_записи(запись: dict[str, object]) -> dict[str, object] | None:
    if запись.get("схема") != СХЕМА_ПРОФИЛИРОВАННОГО_ЗАПУСКА:
        return None
    профиль = запись.get("профиль_проверки")
    return профиль if isinstance(профиль, dict) else None


def _запретить_историю_с_неизвестным_git_профилем(записи):
    if есть_раунды(записи) or any(профиль_записи(запись) is not None for _, запись, _ in записи):
        raise ОшибкаОтчёта("профиль исторического Git-снимка неизвестен")


def история_схем_несовместима(записи: Sequence[dict[str, object]]) -> bool:
    первый_профилированный_порядок = min(
        (
            int(запись["порядок"])
            for запись in записи
            if запись.get("схема") == СХЕМА_ПРОФИЛИРОВАННОГО_ЗАПУСКА
        ),
        default=None,
    )
    return bool(
        первый_профилированный_порядок is not None
        and (
            any(
                запись.get("схема") == СХЕМА_ЗАПУСКА_С_НАБЛЮДЕНИЯМИ
                for запись in записи
            )
            or any(
                int(запись["порядок"])
                > первый_профилированный_порядок
                and запись.get("схема") != СХЕМА_ПРОФИЛИРОВАННОГО_ЗАПУСКА
                for запись in записи
            )
        )
    )


def вычислить_хэш_префикса_раундов(
    записи: Sequence[tuple[Path, dict[str, object], bytes]],
) -> str:
    """v4: числовой порядок, имя и сырые байты; длины — беззнаковые 64-битные big-endian."""
    хэш = hashlib.sha256()
    добавить_часть_отпечатка(хэш, "схема", "fum.префикс-приёмочных-раундов.1".encode("utf-8"))
    for путь, _, байты in sorted(записи, key=lambda элемент: int(элемент[1]["порядок"])):
        добавить_часть_отпечатка(хэш, путь.name, байты)
    return f"sha256:{хэш.hexdigest()}"


def проверить_основу_истории_раундов(
    записи: Sequence[tuple[Path, dict[str, object], bytes]],
) -> list[tuple[Path, dict[str, object], bytes]]:
    if not записи:
        raise ОшибкаОтчёта("история раундов пуста")
    if not isinstance(записи[0][1], dict):
        raise ОшибкаОтчёта("история требует словарь записи")
    сессия = проверить_аналитический_ключ(записи[0][1].get("сессия"), "сессия раундов")
    части_сессии = PurePosixPath(сессия).parts
    if len(части_сессии) != 3 or части_сессии[0] != КАТАЛОГ_ЖУРНАЛА or части_сессии[-1] != ИМЯ_ЗАПРОСА:
        raise ОшибкаОтчёта("сессия раундов должна указывать на запрос в Журнале")
    for путь, значение, байты in записи:
        проверить_запись(значение, путь.name, сессия)
        try:
            прочитанное = json.loads(байты.decode("utf-8"))
        except (UnicodeError, json.JSONDecodeError) as ошибка:
            raise ОшибкаОтчёта("не удалось разобрать сохранённые байты раунда") from ошибка
        проверить_запись(прочитанное, путь.name, сессия)
        if прочитанное != значение:
            raise ОшибкаОтчёта("разобранная запись не совпадает с сохранёнными байтами")
    упорядоченные = sorted(записи, key=lambda элемент: int(элемент[1]["порядок"]))
    порядки = [элемент[1]["порядок"] for элемент in упорядоченные]
    идентификаторы = [элемент[1]["идентификатор"] for элемент in упорядоченные]
    if len(set(порядки)) != len(порядки) or len(set(идентификаторы)) != len(идентификаторы):
        raise ОшибкаОтчёта("история раундов содержит повтор порядка или UUID")
    return упорядоченные


def проверить_историю_раундов(
    записи: Sequence[tuple[Path, dict[str, object], bytes]],
) -> list[tuple[Path, dict[str, object], bytes]]:
    """Проверяет сохранённые данные без обращения к текущему Git или контрактным файлам."""
    упорядоченные = проверить_основу_истории_раундов(записи)
    граница = next(
        (номер for номер, (_, запись, _) in enumerate(упорядоченные)
         if запись["схема"] == СХЕМА_ЗАПУСКА_С_РАУНДАМИ),
        None,
    )
    if граница is None:
        raise ОшибкаОтчёта("история не содержит приёмочных раундов v4")
    префикс = упорядоченные[:граница]
    новые = упорядоченные[граница:]
    if any(запись["схема"] != СХЕМА_ЗАПУСКА_С_РАУНДАМИ for _, запись, _ in новые):
        raise ОшибкаОтчёта("старую схему нельзя добавлять после первого раунда v4")
    if any(запись["состояние"] != "завершён" for _, запись, _ in префикс):
        raise ОшибкаОтчёта("миграция запрещена при активном историческом запуске")
    if (
        any(запись["схема"] == СХЕМА_ЗАПУСКА_С_НАБЛЮДЕНИЯМИ for _, запись, _ in префикс)
        or история_схем_несовместима([запись for _, запись, _ in префикс])
    ):
        raise ОшибкаОтчёта("исторический префикс содержит несовместимые схемы")
    первый = новые[0][1]
    переход = первый["переход_схемы"]
    if префикс:
        if переход is None:
            raise ОшибкаОтчёта("первый v4 после старых записей требует переход")
        if (
            переход["последний_порядок"] != префикс[-1][1]["порядок"]
            or переход["число_записей"] != len(префикс)
            or переход["хэш_префикса"] != вычислить_хэш_префикса_раундов(префикс)
        ):
            raise ОшибкаОтчёта("исторический префикс не совпадает с границей перехода")
        начало = int(префикс[-1][1]["порядок"]) + 1
    else:
        if переход is not None:
            raise ОшибкаОтчёта("чистая история v4 не объявляет переход")
        начало = 1
    if [запись["порядок"] for _, запись, _ in новые] != list(range(начало, начало + len(новые))):
        raise ОшибкаОтчёта("новые раунды должны продолжать порядок без пропусков")
    if any(запись["переход_схемы"] is not None for _, запись, _ in новые[1:]):
        raise ОшибкаОтчёта("переход схемы допускается только в первом v4")
    return новые



ПУТИ_КОНТРАКТА_РАУНДОВ = (
    "AGENTS.md",
    "Инструменты/fum-otchyotyi-o-zapuskakh-proverok/SKILL.md",
    "Инструменты/fum-otchyotyi-o-zapuskakh-proverok/scripts/отчёты_о_запусках_проверок.py",
    "Правила/агентов/Git-и-рабочая-сессия.md",
    "Правила/агентов/журнал-и-происхождение.md",
    "Правила/агентов/проверки-коммит-и-публикация.md",
    "Правила/агентов/инвентарь-правил.json",
)


def исполняемая_структура_контракта(данные: bytes) -> str:
    try:
        дерево = ast.parse(данные.decode("utf-8"))
    except (UnicodeError, SyntaxError, ValueError) as ошибка:
        raise ОшибкаОтчёта("контракт Python не разбирается") from ошибка
    for узел in ast.walk(дерево):
        if isinstance(узел, (ast.Module, ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)):
            if узел.body and isinstance(узел.body[0], ast.Expr) and isinstance(узел.body[0].value, ast.Constant) and isinstance(узел.body[0].value.value, str):
                узел.body = узел.body[1:]
    return ast.dump(дерево, include_attributes=False)


def содержание_контракта_без_свежести(данные: bytes) -> bytes:
    начало_маркера = rb"<!--\s*FUM-MD-RECENCY"
    if re.search(начало_маркера, данные) is None:
        return данные
    шаблон = (
        rb"\n<!-- FUM-MD-RECENCY:BEGIN -->\n"
        rb"<!-- last-content-edit: [0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2} MSK -->\n"
        rb"<!-- content-sha256: sha256:[0-9a-f]{64} -->\n"
        rb"<!-- FUM-MD-RECENCY:END -->\n?\Z"
    )
    совпадение = re.search(шаблон, данные)
    if совпадение is None or re.search(начало_маркера, данные[:совпадение.start()]) is not None:
        raise ОшибкаОтчёта("контракт содержит повреждённую границу свежести")
    return данные[:совпадение.start()]


def подготовить_переход_раундов(
    корень: Path, записи: Sequence[tuple[Path, dict[str, object], bytes]], исходный_коммит: str,
) -> dict[str, object]:
    префикс = проверить_основу_истории_раундов(записи)
    if (
        any(запись["схема"] in {СХЕМА_ЗАПУСКА_С_РАУНДАМИ, СХЕМА_ЗАПУСКА_С_НАБЛЮДЕНИЯМИ} or запись["состояние"] != "завершён" for _, запись, _ in префикс)
        or история_схем_несовместима([запись for _, запись, _ in префикс])
    ):
        raise ОшибкаОтчёта("переход требует терминальный старый префикс без v2")
    if not isinstance(исходный_коммит, str) or re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", исходный_коммит) is None:
        raise ОшибкаОтчёта("переход требует полный исходный commit OID")
    корень = корень.absolute()
    if корень.resolve() != корень:
        raise ОшибкаОтчёта("корень перехода должен быть физическим")
    корень_git = Path(выполнить_чтение_репозитория(корень, "rev-parse", "--show-toplevel").decode("utf-8").strip())
    if корень_git.resolve() != корень:
        raise ОшибкаОтчёта("переход требует точный корень рабочего дерева")
    if выполнить_чтение_репозитория(корень, "cat-file", "-t", исходный_коммит).strip() != b"commit":
        raise ОшибкаОтчёта("исходный объект перехода не является commit")
    выполнить_чтение_репозитория(корень, "merge-base", "--is-ancestor", исходный_коммит, "HEAD")
    for путь_записи, запись, байты_записи in префикс:
        if (запись.get("профиль_проверки") or {}).get("класс") != "полная":
            continue
        имя = (PurePosixPath(запись["сессия"]).parent / "материалы" / "запуски-проверок" / путь_записи.name).as_posix()
        опора = выполнить_чтение_репозитория(корень, "ls-tree", "-z", исходный_коммит, "--", имя)
        if not опора or опора.count(b"\0") != 1:
            raise ОшибкаОтчёта("исходный commit не содержит прежнюю полную попытку")
        метаданные, фактическое_имя = опора[:-1].split(b"\t", 1)
        режим, тип, объект = метаданные.decode("ascii").split()
        if режим not in {"100644", "100755"} or тип != "blob" or фактическое_имя.decode("utf-8") != имя:
            raise ОшибкаОтчёта("опора прежней полной попытки имеет неверный тип или путь")
        if выполнить_чтение_репозитория(корень, "cat-file", "blob", объект) != байты_записи:
            raise ОшибкаОтчёта("исходный commit не сохраняет точные байты прежней полной попытки")
    дерево = выполнить_чтение_репозитория(корень, "ls-tree", "-z", исходный_коммит, "--", *ПУТИ_КОНТРАКТА_РАУНДОВ)
    исходные: dict[str, tuple[str, str]] = {}
    for элемент in дерево.split(b"\0"):
        if not элемент:
            continue
        метаданные, имя = элемент.split(b"\t", 1)
        режим, тип, объект = метаданные.decode("ascii").split()
        if режим not in {"100644", "100755"} or тип != "blob":
            raise ОшибкаОтчёта("исходный контракт должен быть обычным файлом")
        исходные[имя.decode("utf-8")] = (режим, объект)
    изменения: list[dict[str, str]] = []
    изменён_исполняемый_контракт = False
    for имя in sorted(ПУТИ_КОНТРАКТА_РАУНДОВ):
        путь = корень / имя
        проверить_компоненты_без_ссылок(корень, путь)
        if имя not in исходные:
            continue
        проверить_обычный_путь(путь, "контракт перехода")
        до = выполнить_чтение_репозитория(корень, "cat-file", "blob", исходные[имя][1])
        после = путь.read_bytes()
        if имя.endswith(".py"):
            изменён_исполняемый_контракт = исполняемая_структура_контракта(до) != исполняемая_структура_контракта(после)
            содержательно_различны = изменён_исполняемый_контракт
        elif имя.endswith(".md"):
            содержательно_различны = содержание_контракта_без_свежести(до) != содержание_контракта_без_свежести(после)
        else:
            try:
                содержательно_различны = json.loads(до) != json.loads(после)
            except (UnicodeError, json.JSONDecodeError) as ошибка:
                raise ОшибкаОтчёта("машинный контракт перехода не разбирается") from ошибка
        if до != после and содержательно_различны:
            изменения.append({"путь": имя, "до_sha256": "sha256:" + хэш_содержимого(до), "после_sha256": "sha256:" + хэш_содержимого(после)})
    if not изменён_исполняемый_контракт:
        raise ОшибкаОтчёта("переход требует изменение исполняемой структуры отчётной обёртки")
    переход = {
        "последний_порядок": префикс[-1][1]["порядок"],
        "число_записей": len(префикс),
        "хэш_префикса": вычислить_хэш_префикса_раундов(префикс),
        "исходный_коммит": исходный_коммит,
        "изменения_контракта": изменения,
    }
    проверить_переход_схемы(переход)
    return переход


def построить_план_раундов(
    записи: Sequence[tuple[Path, dict[str, object], bytes]],
    текущий_отпечаток: str | None = None,
    текущее_содержимое: str | None = None,
) -> dict[str, object]:
    новые = проверить_историю_раундов(записи)
    for значение, поле in ((текущий_отпечаток, "текущий Git-снимок"), (текущее_содержимое, "текущее содержимое")):
        if значение is not None:
            проверить_отпечаток_раундов(значение, поле)
    значения = [запись for _, запись, _ in новые]
    по_идентификатору = {запись["идентификатор"]: запись for запись in значения}
    полные = [запись for запись in значения if запись["профиль_проверки"]["класс"] == "полная"]
    по_содержимому: dict[str, list[dict[str, object]]] = {}
    for запись in полные:
        по_содержимому.setdefault(запись["отпечаток_содержимого"], []).append(запись)
    повторные = sorted(отпечаток for отпечаток, попытки in по_содержимому.items() if len(попытки) > 1)
    финальная = полные[-1] if полные else None
    финальный_профиль = финальная["профиль_проверки"] if финальная is not None else {}
    финальное_содержимое = финальная["отпечаток_содержимого"] if финальная is not None else None
    недействительные_локализации: list[str] = []
    дублирования: list[dict[str, object]] = []
    отдельные_диагностики: list[dict[str, object]] = []
    for запись in значения:
        профиль = запись["профиль_проверки"]
        if профиль["класс"] != "диагностическая" or запись["состояние"] != "завершён":
            continue
        локализация = профиль["основание"] == "локализация_наблюдаемого_отказа"
        отказ = по_идентификатору.get(профиль["идентификатор_отказа"])
        связь = bool(
            локализация
            and отказ is not None
            and отказ["порядок"] < запись["порядок"]
            and отказ["состояние"] == "завершён"
            and отказ["статус"] == "неуспешно"
            and отказ["отпечаток_содержимого"] == запись["отпечаток_содержимого"]
            and отказ["профиль_проверки"]["отпечаток_снимка"] == профиль["отпечаток_снимка"]
        )
        if локализация and not связь:
            недействительные_локализации.append(запись["идентификатор"])
        наборы_полной = {
            ключ.casefold()
            for полная in по_содержимому.get(запись["отпечаток_содержимого"], [])
            for ключ in полная["профиль_проверки"]["полные_наборы"]
        }
        покрытые = [ключ for ключ in профиль["полные_наборы"] if ключ.casefold() in наборы_полной]
        непокрытые = [ключ for ключ in профиль["полные_наборы"] if ключ.casefold() not in наборы_полной]
        if покрытые:
            дублирования.append({
                "идентификатор": запись["идентификатор"],
                "отпечаток_содержимого": запись["отпечаток_содержимого"],
                "наборы": покрытые,
                "разрешено": связь,
            })
        if непокрытые:
            отдельные_диагностики.append({
                "идентификатор": запись["идентификатор"],
                "отпечаток_содержимого": запись["отпечаток_содержимого"],
                "наборы": непокрытые,
                "статус": запись["статус"],
                "актуальная": запись["отпечаток_содержимого"] == финальное_содержимое,
            })
    префикс = [элемент for элемент in записи if элемент[1]["схема"] != СХЕМА_ЗАПУСКА_С_РАУНДАМИ]
    исторический_план = построить_план_успешной_сессии(префикс) if префикс else None
    исторические_нарушения: list[str] = []
    if исторический_план is not None:
        исторические_нарушения = [
            условие for условие in (
                "нет_запрещённых_перекрытий",
                "локализации_связаны_с_предшествующим_отказом",
                "совместимая_история",
            )
            if not исторический_план["доказанные_условия"][условие]
        ]
        if исторический_план["полные_прогоны"] > 1:
            исторические_нарушения.append("более_одного_успешного_полного_прогона_до_перехода")
    условия = {
        "переход_не_заменяет_изменение_содержимого": (
            значения[0]["переход_схемы"] is None
            or (
                значения[0]["профиль_проверки"]["класс"] == "адресная"
                and all(полная["отпечаток_содержимого"] != значения[0]["отпечаток_содержимого"] for полная in полные)
            )
        ),
        "нет_активных": all(запись["состояние"] == "завершён" for запись in значения),
        "финальная_полная_последняя": финальная is not None and финальная["порядок"] == значения[-1]["порядок"],
        "финальная_полная_успешна": финальная is not None and финальная["состояние"] == "завершён" and финальная["статус"] == "успешно",
        "снимок_совпадает": текущий_отпечаток is not None and финальный_профиль.get("отпечаток_снимка") == текущий_отпечаток,
        "содержимое_совпадает": текущее_содержимое is not None and финальное_содержимое == текущее_содержимое,
        "нет_повторных_полных_попыток": not повторные,
        "локализации_связаны_с_предшествующим_отказом": not недействительные_локализации,
        "нет_запрещённых_перекрытий": all(дубль["разрешено"] for дубль in дублирования),
        "непокрытые_диагностики_успешны": all(диагностика["статус"] == "успешно" for диагностика in отдельные_диагностики if диагностика["актуальная"]),
        "исторические_нарушения_отсутствуют": not исторические_нарушения,
    }
    return {
        "состояние": "готов" if all(условия.values()) else "не готов",
        "доказанные_условия": условия,
        "полные_попытки": len(полные),
        "полные_прогоны": sum(запись["состояние"] == "завершён" and запись["статус"] == "успешно" for запись in полные),
        "идентификатор_финального_запуска": финальная["идентификатор"] if финальная is not None else None,
        "отпечаток_финального_снимка": финальный_профиль.get("отпечаток_снимка"),
        "отпечаток_финального_содержимого": финальное_содержимое,
        "повторные_содержательные_отпечатки": повторные,
        "недействительные_локализации": недействительные_локализации,
        "дублирования": дублирования,
        "отдельные_диагностики": отдельные_диагностики,
        "исторический_план": исторический_план,
        "исторические_нарушения": исторические_нарушения,
    }


def запретить_понижение_схемы_раундов(
    записи: Sequence[tuple[Path, dict[str, object], bytes]],
) -> None:
    if any(запись.get("схема") == СХЕМА_ЗАПУСКА_С_РАУНДАМИ for _, запись, _ in записи):
        raise ОшибкаОтчёта("записи v4 требуют отдельный план и новый формат снимка отчёта")


def построить_план_успешной_сессии(
    записи: Sequence[tuple[Path, dict[str, object], bytes]],
    текущий_отпечаток: str | None = None,
) -> dict[str, object]:
    запретить_понижение_схемы_раундов(записи)
    все_записи = sorted(
        (запись for _, запись, _ in записи),
        key=lambda запись: int(запись["порядок"]),
    )
    профилированные = sorted(
        (
            запись
            for _, запись, _ in записи
            if профиль_записи(запись) is not None
        ),
        key=lambda запись: int(запись["порядок"]),
    )
    все_полные = [
        запись
        for запись in профилированные
        if профиль_записи(запись).get("класс") == "полная"
    ]
    завершённые_полные = [
        запись
        for запись in все_полные
        if запись.get("состояние") == "завершён"
    ]
    успешные_полные = [
        запись
        for запись in завершённые_полные
        if запись.get("статус") == "успешно"
    ]
    дублирования: list[dict[str, object]] = []
    отдельные_диагностики: list[dict[str, object]] = []
    недействительные_локализации: list[str] = []
    допустимые_локализации: set[str] = set()
    по_идентификатору = {
        str(запись.get("идентификатор")): запись
        for запись in профилированные
    }
    for запись in профилированные:
        профиль = профиль_записи(запись)
        if (
            запись.get("состояние") != "завершён"
            or профиль.get("класс") != "диагностическая"
            or профиль.get("основание")
            != "локализация_наблюдаемого_отказа"
        ):
            continue
        идентификатор = str(запись.get("идентификатор"))
        отказ = по_идентификатору.get(
            str(профиль.get("идентификатор_отказа"))
        )
        профиль_отказа = профиль_записи(отказ) if отказ is not None else None
        связь_действительна = bool(
            отказ is not None
            and int(отказ.get("порядок", 0)) < int(запись.get("порядок", 0))
            and отказ.get("статус") == "неуспешно"
            and профиль_отказа is not None
            and профиль_отказа.get("отпечаток_снимка")
            == профиль.get("отпечаток_снимка")
        )
        if связь_действительна:
            допустимые_локализации.add(идентификатор)
        else:
            недействительные_локализации.append(идентификатор)
    финальная = все_полные[-1] if все_полные else None
    финальный_профиль = (
        профиль_записи(финальная) if финальная is not None else None
    )
    if финальная is not None:
        финальные_наборы = {
            str(ключ).casefold(): str(ключ)
            for ключ in финальный_профиль.get("полные_наборы", [])
        }
        for запись in профилированные:
            профиль = профиль_записи(запись)
            if запись.get("состояние") != "завершён" or профиль.get(
                "класс"
            ) not in {"диагностическая", "полная"}:
                continue
            пересечение = sorted({
                финальные_наборы[ключ.casefold()]
                for ключ in профиль.get("полные_наборы", [])
                if (
                    профиль.get("отпечаток_снимка")
                    == финальный_профиль.get("отпечаток_снимка")
                    and ключ.casefold() in финальные_наборы
                )
            })
            объявленные_наборы = {
                str(ключ).casefold(): str(ключ)
                for ключ in профиль.get("полные_наборы", [])
            }
            непокрытые = sorted(
                исходный
                for ключ, исходный in объявленные_наборы.items()
                if ключ not in финальные_наборы
            )
            тот_же_снимок = bool(
                профиль.get("отпечаток_снимка")
                == финальный_профиль.get("отпечаток_снимка")
            )
            if профиль.get("класс") == "диагностическая" and непокрытые:
                отдельные_диагностики.append(
                    {
                        "идентификатор": запись.get("идентификатор"),
                        "наборы": непокрытые,
                        "длительность_наносекунды": запись.get(
                            "длительность_наносекунды"
                        ),
                        "статус": запись.get("статус"),
                        "основание": профиль.get("основание"),
                        "ожидаемое_свидетельство": профиль.get(
                            "ожидаемое_свидетельство"
                        ),
                        "тот_же_снимок": тот_же_снимок,
                    }
                )
            if not пересечение:
                continue
            if int(запись.get("порядок", 0)) >= int(
                финальная.get("порядок", 0)
            ):
                continue
            разрешено = False
            if профиль.get("класс") == "диагностическая" and профиль.get(
                "основание"
            ) == "локализация_наблюдаемого_отказа":
                разрешено = str(
                    запись.get("идентификатор")
                ) in допустимые_локализации
            дублирования.append(
                {
                    "идентификатор": запись.get("идентификатор"),
                    "класс": профиль.get("класс"),
                    "наборы": пересечение,
                    "длительность_наносекунды": запись.get("длительность_наносекунды"),
                    "статус": запись.get("статус"),
                    "основание": профиль.get("основание"),
                    "ожидаемое_свидетельство": профиль.get("ожидаемое_свидетельство"),
                    "разрешено": разрешено,
                }
            )
    неразрешённые = [дубль for дубль in дублирования if not дубль["разрешено"]]
    неуспешные_актуальные_диагностики = [
        диагностика
        for диагностика in отдельные_диагностики
        if диагностика["тот_же_снимок"]
        and диагностика["статус"] != "успешно"
    ]
    счётчик_полных_снимков: dict[str, int] = {}
    for запись in завершённые_полные:
        отпечаток = str(профиль_записи(запись).get("отпечаток_снимка"))
        счётчик_полных_снимков[отпечаток] = (
            счётчик_полных_снимков.get(отпечаток, 0) + 1
        )
    повторные_полные_снимки = sorted(
        отпечаток
        for отпечаток, число in счётчик_полных_снимков.items()
        if число > 1
    )
    есть_выполняющиеся = any(
        запись.get("состояние") == "выполняется" for запись in все_записи
    )
    максимальный_порядок = max(
        (int(запись["порядок"]) for запись in все_записи),
        default=0,
    )
    финальный_полный_последний = bool(
        финальная is not None
        and int(финальная["порядок"]) == максимальный_порядок
    )
    финал_успешен = bool(
        финальная is not None
        and финальная.get("состояние") == "завершён"
        and финальная.get("статус") == "успешно"
    )
    несовместимая_история = история_схем_несовместима(все_записи)
    снимок_совпадает = bool(
        текущий_отпечаток is not None
        and финальный_профиль is not None
        and финальный_профиль.get("отпечаток_снимка")
        == текущий_отпечаток
    )
    доказанные_условия = {
        "нет_активных": not есть_выполняющиеся,
        "финальная_полная_последняя": финальный_полный_последний,
        "финальная_полная_успешна": финал_успешен,
        "ровно_один_успешный_полный_прогон": len(успешные_полные) == 1,
        "нет_запрещённых_перекрытий": not неразрешённые
        and not повторные_полные_снимки,
        "локализации_связаны_с_предшествующим_отказом": not недействительные_локализации,
        "непокрытые_диагностики_успешны": not неуспешные_актуальные_диагностики,
        "совместимая_история": not несовместимая_история,
        "снимок_совпадает": снимок_совпадает,
    }
    готов = all(доказанные_условия.values())
    return {
        "состояние": "готов" if готов else "не готов",
        "нормативный_контур": list(
            НОРМАТИВНЫЙ_КОНТУР_УСПЕШНОЙ_СЕССИИ
        ),
        "доказанные_условия": доказанные_условия,
        "полные_попытки": len(завершённые_полные),
        "полные_прогоны": len(успешные_полные),
        "последний_полный_статус": финальная.get("статус") if финальная is not None else None,
        "отпечаток_финального_снимка": финальный_профиль.get("отпечаток_снимка") if финальный_профиль is not None else None,
        "финальный_полный_последний": финальный_полный_последний,
        "есть_выполняющиеся": есть_выполняющиеся,
        "несовместимая_история": несовместимая_история,
        "дублирования": дублирования,
        "отдельные_диагностики": отдельные_диагностики,
        "повторные_полные_снимки": повторные_полные_снимки,
        "недействительные_локализации": недействительные_локализации,
    }


def проверить_порядок_проверок(
    записи: Sequence[tuple[Path, dict[str, object], bytes]],
    текущий_отпечаток: str | None = None,
) -> dict[str, object]:
    _запретить_историю_с_неизвестным_git_профилем(записи)
    план = построить_план_успешной_сессии(записи, текущий_отпечаток)
    if план["есть_выполняющиеся"]:
        raise ОшибкаОтчёта("экономный план содержит выполняющуюся запись")
    if план["несовместимая_история"]:
        raise ОшибкаОтчёта("v1/v2 нельзя добавлять после v3 или смешивать v2 с v3")
    if план["недействительные_локализации"]:
        raise ОшибкаОтчёта("диагностика требует точный UUID предшествующего неуспешного запуска")
    if план["повторные_полные_снимки"]:
        raise ОшибкаОтчёта("полная проверка повторена на неизменённом снимке")
    if any(not дубль["разрешено"] for дубль in план["дублирования"]):
        raise ОшибкаОтчёта("обнаружено неразрешённое дублирование полной проверки")
    if any(
        диагностика["тот_же_снимок"]
        and диагностика["статус"] != "успешно"
        for диагностика in план["отдельные_диагностики"]
    ):
        raise ОшибкаОтчёта("непокрытая диагностика не была успешной")
    if план["полные_прогоны"] != 1:
        raise ОшибкаОтчёта("успешный план требует ровно один полный прогон")
    if план["последний_полный_статус"] != "успешно":
        raise ОшибкаОтчёта("последняя полная проверка не была успешной")
    if not план["финальный_полный_последний"]:
        raise ОшибкаОтчёта("финальная полная проверка должна быть последней записью")
    if текущий_отпечаток is None:
        raise ОшибкаОтчёта("текущий отпечаток снимка не передан")
    if план[
        "отпечаток_финального_снимка"
    ] != текущий_отпечаток:
        raise ОшибкаОтчёта("снимок изменился после финальной полной проверки")
    return план


def сформировать_строки_плана(
    записи: Sequence[tuple[Path, dict[str, object], bytes]],
    текущий_отпечаток: str | None = None,
) -> list[str]:
    if not any(профиль_записи(запись) is not None for _, запись, _ in записи):
        return []
    план = построить_план_успешной_сессии(записи, текущий_отпечаток)
    строки = [f"Экономный порядок проверок: {план['состояние']}." ]
    for дубль in план["дублирования"]:
        секунды = отформатировать_секунды(
            округлить_до_миллисекунд(int(дубль["длительность_наносекунды"]))
        )
        статус = "разрешено" if дубль["разрешено"] else "не разрешено"
        строки.append(
            "Дублирование полного набора: "
            f"{статус}; {секунды} с; "
            f"результат: {дубль['статус']}; "
            f"наборы: {', '.join(дубль['наборы'])}; "
            f"основание: {дубль['основание'] or 'нет'}."
        )
    for диагностика in план["отдельные_диагностики"]:
        секунды = отформатировать_секунды(
            округлить_до_миллисекунд(
                int(диагностика["длительность_наносекунды"])
            )
        )
        строки.append(
            "Отдельная диагностическая проверка: "
            f"{секунды} с; "
            f"результат: {диагностика['статус']}; "
            f"наборы: {', '.join(диагностика['наборы'])}; "
            f"основание: {диагностика['основание']}."
        )
    return строки


def сформировать_таблицу_запусков(
    записи: Sequence[tuple[Path, dict[str, object], bytes]],
) -> tuple[list[str], str]:
    строки: list[tuple[str, str, str]] = []
    сумма_миллисекунд = 0
    for _, запись, _ in записи:
        вызов = экранировать_табличный_текст(
            f"[{запись['исполнитель']}] {запись['вызов']}"
        )
        if запись["состояние"] == "выполняется":
            длительность = "0,000 с"
            результат = "не завершено — нет итоговой записи"
        else:
            наносекунды = int(запись["длительность_наносекунды"])
            миллисекунды = округлить_до_миллисекунд(наносекунды)
            сумма_миллисекунд += миллисекунды
            длительность = f"{отформатировать_секунды(миллисекунды)} с"
            результат = str(запись["статус"])
            пояснение = запись["пояснение"]
            if пояснение:
                результат = f"{результат} — {пояснение}"
            результат = экранировать_табличный_текст(результат)
        строки.append((вызов, длительность, результат))

    заголовки = ("Вызов", "Длительность", "Результат")
    ширины = [
        max([len(заголовки[номер]), *(len(строка[номер]) for строка in строки)])
        for номер in range(len(заголовки))
    ]
    таблица = [
        табличная_строка(заголовки, ширины),
        табличная_строка(tuple("-" * ширина for ширина in ширины), ширины),
        *(табличная_строка(строка, ширины) for строка in строки),
    ]
    итог = отформатировать_секунды(сумма_миллисекунд)
    return таблица, итог


def сформировать_блок(
    записи: Sequence[tuple[Path, dict[str, object], bytes]],
    начальный_маркер: str,
    текущий_отпечаток: str | None = None,
) -> str:
    запретить_понижение_схемы_раундов(записи)
    таблица, итог = сформировать_таблицу_запусков(записи)
    строки_плана = сформировать_строки_плана(записи, текущий_отпечаток)
    дополнение_плана = ["", *строки_плана] if строки_плана else []
    return "\n".join(
        (
            начальный_маркер,
            "",
            *таблица,
            "",
            f"Общее время прямых запусков проверок: {итог} с.",
            *дополнение_плана,
            "",
            КОНЕЧНЫЙ_МАРКЕР,
        )
    )



def есть_раунды(записи: Sequence[tuple[Path, dict[str, object], bytes]]) -> bool:
    return any(запись.get("схема") == СХЕМА_ЗАПУСКА_С_РАУНДАМИ for _, запись, _ in записи)


def прочитать_историю_проверок(каталог: Path, сессия: str) -> list[tuple[Path, dict[str, object], bytes]]:
    записи = прочитать_записи(каталог, сессия, разрешить_раунды=True)
    if есть_раунды(записи):
        проверить_историю_раундов(записи)
    return записи


def текущий_контекст_проверок(
    корень: Path, сессия: str, записи: Sequence[tuple[Path, dict[str, object], bytes]],
) -> tuple[str | None, str | None]:
    раунды = есть_раунды(записи)
    гит = (
        вычислить_отпечаток_снимка(корень, Path(сессия).parent)
        if раунды or any(профиль_записи(запись) is not None for _, запись, _ in записи)
        else None
    )
    содержимое = вычислить_отпечаток_содержимого(корень, Path(сессия).parent) if раунды else None
    return гит, содержимое


def сформировать_блок_раундов(
    записи: Sequence[tuple[Path, dict[str, object], bytes]],
    начальный_маркер: str,
    текущий_отпечаток: str | None = None,
    текущее_содержимое: str | None = None,
) -> str:
    план = построить_план_раундов(записи, текущий_отпечаток, текущее_содержимое)
    записи = sorted(записи, key=lambda элемент: элемент[1]["порядок"])
    по_идентификатору = {запись["идентификатор"]: запись for _, запись, _ in записи}

    def свидетельства_диагностики(идентификатор: str) -> str:
        запись = по_идентификатору[идентификатор]
        профиль = запись["профиль_проверки"]
        секунды = отформатировать_секунды(округлить_до_миллисекунд(запись["длительность_наносекунды"]))
        return (
            f"длительность: {секунды} с; результат: {запись['статус']}; "
            f"основание: {профиль['основание']}; "
            f"локализуемый отказ: {профиль['идентификатор_отказа'] or 'нет'}; "
            f"ожидаемое свидетельство: {профиль['ожидаемое_свидетельство']}"
        )

    таблица, итог = сформировать_таблицу_запусков(записи)
    строки = [
        начальный_маркер, "", *таблица, "",
        f"Общее время прямых запусков проверок: {итог} с.", "",
        f"Приёмочные раунды: {план['состояние']}.",
        f"Контекст Git-снимка: {текущий_отпечаток or 'не задан'}.",
        f"Контекст содержимого: {текущее_содержимое or 'не задан'}.",
        f"Полных попыток: {план['полные_попытки']}; успешных: {план['полные_прогоны']}.",
    ]
    for условие, выполнено in план["доказанные_условия"].items():
        строки.append(f"Условие «{условие.replace('_', ' ')}»: {'выполнено' if выполнено else 'не выполнено'}.")
    for отпечаток in план["повторные_содержательные_отпечатки"]:
        строки.append(f"Повтор полной попытки на содержимом: {отпечаток}.")
    for идентификатор in план["недействительные_локализации"]:
        строки.append(f"Недействительная локализация: {идентификатор}.")
    for дубль in план["дублирования"]:
        строки.append(
            f"Дублирование полного набора: {'разрешено' if дубль['разрешено'] else 'не разрешено'}; "
            f"запуск: {дубль['идентификатор']}; содержимое: {дубль['отпечаток_содержимого']}; "
            f"наборы: {', '.join(дубль['наборы'])}; "
            f"{свидетельства_диагностики(дубль['идентификатор'])}."
        )
    for диагностика in план["отдельные_диагностики"]:
        строки.append(
            f"Отдельная диагностика: {диагностика['идентификатор']}; "
            f"содержимое: {диагностика['отпечаток_содержимого']}; "
            f"наборы: {', '.join(диагностика['наборы'])}; "
            f"{свидетельства_диагностики(диагностика['идентификатор'])}."
        )
    префикс = [элемент for элемент in записи if элемент[1]["схема"] != СХЕМА_ЗАПУСКА_С_РАУНДАМИ]
    if префикс:
        строки.extend(["", "Исторический префикс до перехода (без текущего контекста):", *сформировать_строки_плана(префикс)])
        строки.append("Нарушения исторического порядка: " + (", ".join(план["исторические_нарушения"]) or "нет") + ".")
    return "\n".join([*строки, "", КОНЕЧНЫЙ_МАРКЕР])


def сформировать_блок_истории(
    записи: Sequence[tuple[Path, dict[str, object], bytes]], маркер: str,
    гит: str | None = None, содержимое: str | None = None,
) -> str:
    if есть_раунды(записи):
        return сформировать_блок_раундов(записи, маркер, гит, содержимое)
    if содержимое is not None:
        raise ОшибкаОтчёта("исторический отчёт не принимает содержательный контекст")
    return сформировать_блок(записи, маркер, гит)


def ожидаемый_снимок_раундов(
    записи: Sequence[tuple[Path, dict[str, object], bytes]], сессия: str,
    отпечаток_закрытия: str, отпечаток_содержимого_закрытия: str,
) -> dict[str, object]:
    новые = проверить_историю_раундов(записи)
    if новые[0][1]["сессия"] != сессия:
        raise ОшибкаОтчёта("снимок раундов принадлежит другой сессии")
    if any(запись["состояние"] != "завершён" for _, запись, _ in записи):
        raise ОшибкаОтчёта("снимок раундов запрещён при активной записи")
    проверить_отпечаток_раундов(отпечаток_закрытия, "Git-контекст закрытия")
    проверить_отпечаток_раундов(отпечаток_содержимого_закрытия, "содержательный контекст закрытия")
    return {
        "схема": СХЕМА_СНИМКА_С_РАУНДАМИ,
        "сессия": сессия,
        "отпечаток_закрытия": отпечаток_закрытия,
        "отпечаток_содержимого_закрытия": отпечаток_содержимого_закрытия,
        "файлы": [
            {"имя": путь.name, "sha256": хэш_содержимого(байты)}
            for путь, _, байты in sorted(записи, key=lambda элемент: элемент[1]["порядок"])
        ],
    }


def проверить_снимок_раундов(
    путь_снимка: Path, записи: Sequence[tuple[Path, dict[str, object], bytes]], сессия: str,
) -> tuple[bytes, str, str]:
    значение, байты = прочитать_машинную_запись(путь_снимка)
    if not isinstance(значение, dict) or set(значение) != ПОЛЯ_СНИМКА_С_РАУНДАМИ:
        raise ОшибкаОтчёта("снимок раундов содержит неверный набор полей")
    гит = значение["отпечаток_закрытия"]
    содержимое = значение["отпечаток_содержимого_закрытия"]
    ожидаемое = ожидаемый_снимок_раундов(записи, сессия, гит, содержимое)
    if значение != ожидаемое:
        raise ОшибкаОтчёта("снимок раундов не совпадает с фактическими записями")
    if байты != канонические_машинные_байты(ожидаемое):
        raise ОшибкаОтчёта("снимок раундов имеет неканонические байты")
    return байты, гит, содержимое


def проверить_снимок_истории(
    путь_снимка: Path, записи: Sequence[tuple[Path, dict[str, object], bytes]], сессия: str,
) -> tuple[bytes, str | None, str | None]:
    значение, _ = прочитать_машинную_запись(путь_снимка)
    if isinstance(значение, dict) and значение.get("схема") == СХЕМА_СНИМКА_С_РАУНДАМИ:
        return проверить_снимок_раундов(путь_снимка, записи, сессия)
    байты, гит = проверить_снимок(путь_снимка, записи, сессия)
    return байты, гит, None


def границы_управляемого_блока(текст: str) -> tuple[int, int, str]:
    начала = list(ЛЮБОЙ_НАЧАЛЬНЫЙ_МАРКЕР.finditer(текст))
    концы = list(КОНЕЧНЫЙ_МАРКЕР_СТРОКА.finditer(текст))
    if len(начала) != 1 or len(концы) != 1:
        raise ОшибкаОтчёта(
            "отчёт должен содержать ровно одну пару FUM-CHECK-RUNS marker"
        )
    начало = начала[0]
    конец = концы[0]
    if начало.end() >= конец.start():
        raise ОшибкаОтчёта("marker-пара отчёта переставлена или вложена")
    маркер = начало.group(0)
    if маркер != ОТКРЫТЫЙ_МАРКЕР and ЗАКРЫТЫЙ_МАРКЕР.fullmatch(маркер) is None:
        raise ОшибкаОтчёта("начальный marker отчёта имеет неизвестный формат")
    return начало.start(), конец.end(), маркер


def заменить_управляемый_блок_в_байтах(
    исходные_байты: bytes,
    новый_блок: str,
) -> bytes:
    try:
        текст = исходные_байты.decode("utf-8")
    except UnicodeError as ошибка:
        raise ОшибкаОтчёта(f"не удалось декодировать отчёт: {ошибка}") from ошибка
    начало, конец, _ = границы_управляемого_блока(текст)
    новый_текст = текст[:начало] + новый_блок + текст[конец:]
    return новый_текст.encode("utf-8")


def _снять_отчёт_без_ссылок(путь: Path, *, ожидаемые=None, ожидаемая_метка=None):
    """Читает обычный отчёт через FD; поздняя сверка не является CAS."""
    if (ожидаемые is None) != (ожидаемая_метка is None):
        raise ОшибкаОтчёта('для сверки отчёта нужны байты и метка')
    if ожидаемые is not None and type(ожидаемые) is not bytes:
        raise ОшибкаОтчёта('неверные ожидаемые байты отчёта')
    дескрипторы, первичная = [], None
    def метка(с):
        return (с.st_dev, с.st_ino, с.st_mode, с.st_uid, с.st_gid, с.st_nlink,
                с.st_size, с.st_mtime_ns, с.st_ctime_ns)
    def прочитать(fd, размер):
        while True:
            try:
                return os.read(fd, размер)
            except InterruptedError:
                continue
    try:
        до = путь.lstat()
        if not stat.S_ISREG(до.st_mode) or до.st_nlink != 1 or до.st_size < 0:
            raise ОшибкаОтчёта('отчёт не является обычным файлом с одной ссылкой')
        исходная = метка(до)
        if ожидаемая_метка is not None and исходная != ожидаемая_метка:
            raise ОшибкаОтчёта('отчёт изменился перед публикацией')
        if ожидаемые is not None and до.st_size != len(ожидаемые):
            raise ОшибкаОтчёта('размер отчёта изменился перед публикацией')
        fd = _приобрести_fd(дескрипторы, os.open, путь,
                            os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK | os.O_CLOEXEC)
        if метка(os.fstat(fd)) != исходная:
            raise ОшибкаОтчёта('отчёт заменён до чтения')
        данные = bytearray() if ожидаемые is None else None
        позиция = 0
        while позиция < до.st_size:
            часть = прочитать(fd, min(65536, до.st_size - позиция))
            if not часть:
                raise ОшибкаОтчёта('отчёт оборван при чтении')
            if ожидаемые is None:
                данные.extend(часть)
            elif часть != ожидаемые[позиция:позиция + len(часть)]:
                raise ОшибкаОтчёта('байты отчёта изменились перед публикацией')
            позиция += len(часть)
        if прочитать(fd, 1) != b'' or метка(os.fstat(fd)) != исходная or метка(путь.lstat()) != исходная:
            raise ОшибкаОтчёта('отчёт изменился при чтении')
        return (bytes(данные) if данные is not None else ожидаемые), исходная
    except OSError as ошибка:
        первичная = ОшибкаОтчёта(f'не удалось безопасно прочитать отчёт: {ошибка}')
        raise первичная from ошибка
    except BaseException as ошибка:
        первичная = ошибка
        raise
    finally:
        _закрыть_удержанные_fd(дескрипторы, первичная, 'сверки отчёта', _сохранять_ошибки=True)


def _проверка_отчёта_под_замком(путь, байты, метка, сверить_замок):
    def проверить():
        сверить_замок()
        _снять_отчёт_без_ссылок(путь, ожидаемые=байты, ожидаемая_метка=метка)
        сверить_замок()
    return проверить


@contextlib.contextmanager
def _удержать_файл_перед_удалением(путь, байты, ожидаемая_метка, сверить_замок, *, ожидаемый_каталог):
    """Удерживает файл и родительский каталог; проверка не является unlink-CAS."""
    дескрипторы, первичная = [], None
    активен = False
    отказ_сверки = None
    владелец_pid, владелец_поток = os.getpid(), threading.current_thread()
    def метка(с):
        return (с.st_dev, с.st_ino, с.st_mode, с.st_uid, с.st_gid, с.st_nlink,
                с.st_size, с.st_mtime_ns, с.st_ctime_ns)
    def метка_каталога(с):
        return (с.st_dev, с.st_ino, с.st_mode, с.st_uid, с.st_gid)
    def прочитать(fd, размер):
        while True:
            try:
                return os.read(fd, размер)
            except InterruptedError:
                continue
    try:
        сверить_замок()
        исходный_каталог = путь.parent.lstat()
        if not stat.S_ISDIR(исходный_каталог.st_mode):
            raise ОшибкаОтчёта('каталог удаляемого файла не является каталогом')
        if метка_каталога(исходный_каталог) != ожидаемый_каталог:
            raise ОшибкаОтчёта('каталог изменился между фазами возобновления')
        каталог_fd = _приобрести_fd(
            дескрипторы, os.open, путь.parent,
            os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
        if метка_каталога(os.fstat(каталог_fd)) != метка_каталога(исходный_каталог):
            raise ОшибкаОтчёта('каталог удаляемого файла заменён')
        исходный = os.stat(путь.name, dir_fd=каталог_fd, follow_symlinks=False)
        if (not stat.S_ISREG(исходный.st_mode) or исходный.st_nlink != 1
            or метка(исходный) != ожидаемая_метка or исходный.st_size != len(байты)):
            raise ОшибкаОтчёта('удаляемый файл изменился')
        файл_fd = _приобрести_fd(
            дескрипторы, os.open, путь.name,
            os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK | os.O_CLOEXEC, dir_fd=каталог_fd)
        if метка(os.fstat(файл_fd)) != ожидаемая_метка:
            raise ОшибкаОтчёта('удаляемый файл заменён до чтения')
        активен = True
        def сверить_файл():
            nonlocal отказ_сверки
            if not активен or os.getpid() != владелец_pid or threading.current_thread() is not владелец_поток:
                raise ОшибкаОтчёта('дескриптор удаляемого файла недействителен')
            if отказ_сверки is not None:
                raise ОшибкаОтчёта('сверка удаляемого файла ранее отказала') from отказ_сверки
            try:
                os.lseek(файл_fd, 0, os.SEEK_SET)
                позиция = 0
                while позиция < len(байты):
                    часть = прочитать(файл_fd, min(65536, len(байты) - позиция))
                    if not часть or часть != байты[позиция:позиция + len(часть)]:
                        raise ОшибкаОтчёта('байты удаляемого файла изменились')
                    позиция += len(часть)
                if (прочитать(файл_fd, 1) != b'' or метка(os.fstat(файл_fd)) != ожидаемая_метка
                    or метка(os.stat(путь.name, dir_fd=каталог_fd, follow_symlinks=False)) != ожидаемая_метка
                    or метка_каталога(путь.parent.lstat()) != метка_каталога(исходный_каталог)):
                    raise ОшибкаОтчёта('удаляемый файл или каталог изменился')
                сверить_замок()
            except BaseException as ошибка:
                отказ_сверки = ошибка
                raise
        сверить_файл()
        yield каталог_fd, сверить_файл
        if отказ_сверки is not None:
            raise ОшибкаОтчёта('сверка удаляемого файла ранее отказала') from отказ_сверки
        try:
            if (метка_каталога(os.fstat(каталог_fd)) != ожидаемый_каталог
                or метка_каталога(путь.parent.lstat()) != ожидаемый_каталог):
                raise ОшибкаОтчёта('каталог изменился после удаления; исход неизвестен')
        except OSError as ошибка:
            raise ОшибкаОтчёта('каталог недоступен после удаления; исход неизвестен') from ошибка
    except BaseException as ошибка:
        первичная = ошибка
        raise
    finally:
        активен = False
        _закрыть_удержанные_fd(дескрипторы, первичная, 'удаляемого файла', _сохранять_ошибки=True)



def _атомарно_сохранить_отчёт_с_правами(путь, новые, исходные, исходная_метка, *, перед_публикацией=None):
    """Сохранить отчёт с ограниченным temp; ошибка после replace означает UNKNOWN."""
    if (type(новые) is not bytes or type(исходные) is not bytes
        or type(исходная_метка) is not tuple or len(исходная_метка) != 9
        or not stat.S_ISREG(исходная_метка[2]) or исходная_метка[5] != 1
        or исходная_метка[6] != len(исходные)
        or (перед_публикацией is not None and not callable(перед_публикацией))):
        raise ОшибкаОтчёта('неверные входы сохранения прав отчёта')
    if stat.S_IMODE(исходная_метка[2]) & 0o7000:
        raise ОшибкаОтчёта('обновление отчёта со специальными битами прав пока не допущено')
    if путь.parent.is_symlink():
        raise ОшибкаОтчёта('каталог отчёта не должен быть символической ссылкой')
    временный = путь.parent / f'.{путь.name}.{uuid.uuid4()}.tmp'
    дескрипторы = []
    первичная = None
    замена_начата = False
    def метка(с):
        return (с.st_dev, с.st_ino, с.st_mode, с.st_uid, с.st_gid, с.st_nlink,
                с.st_size, с.st_mtime_ns, с.st_ctime_ns)
    def указать_unknown(ошибка):
        try:
            BaseException.add_note(ошибка, 'Исход публикации отчёта не подтверждён; повтор не разрешён автоматически.')
        except BaseException:
            pass
    try:
        fd = _приобрести_fd(
            дескрипторы, os.open, временный,
            os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | os.O_CLOEXEC, 0o600)
        сведения = os.fstat(fd)
        if (not stat.S_ISREG(сведения.st_mode) or сведения.st_nlink != 1
            or stat.S_IMODE(сведения.st_mode) & ~0o600
            or (сведения.st_dev, сведения.st_uid, сведения.st_gid)
               != (исходная_метка[0], исходная_метка[3], исходная_метка[4])):
            raise ОшибкаОтчёта('временный отчёт имеет другое устройство, владельца или группу')
        позиция = 0
        while позиция < len(новые):
            try:
                записано = os.write(fd, новые[позиция:позиция + 65536])
            except InterruptedError:
                continue
            if type(записано) is not int or not 0 < записано <= min(65536, len(новые) - позиция):
                raise ОшибкаОтчёта('неполная запись временного отчёта')
            позиция += записано
        os.fsync(fd)
        временная_метка = метка(os.fstat(fd))
        if временная_метка[6] != len(новые):
            raise ОшибкаОтчёта('размер временного отчёта изменился')
        if перед_публикацией is not None:
            перед_публикацией()
        _снять_отчёт_без_ссылок(путь, ожидаемые=исходные, ожидаемая_метка=исходная_метка)
        if метка(временный.lstat()) != временная_метка or метка(os.fstat(fd)) != временная_метка:
            raise ОшибкаОтчёта('временный отчёт изменился до замены')
        замена_начата = True
        os.replace(временный, путь)
        def сверить_замену(проверить_режим):
            открытый, по_имени = os.fstat(fd), путь.lstat()
            идентичность = lambda с: (с.st_dev, с.st_ino, с.st_uid, с.st_gid, с.st_nlink)
            if (not stat.S_ISREG(открытый.st_mode) or not stat.S_ISREG(по_имени.st_mode)
                or идентичность(открытый) != идентичность(по_имени)
                or идентичность(открытый) != (временная_метка[0], временная_метка[1],
                                               исходная_метка[3], исходная_метка[4], 1)
                or (проверить_режим and stat.S_IMODE(открытый.st_mode) != исходная_метка[2] & 0o777)):
                raise ОшибкаОтчёта('результат замены отчёта не подтверждён')
        сверить_замену(False)
        os.fchmod(fd, исходная_метка[2] & 0o777)
        os.fsync(fd)
        сверить_замену(True)
        _закрыть_удержанные_fd(дескрипторы, None, 'временного отчёта')
        синхронизировать_каталог(путь.parent)
    except OSError as ошибка:
        первичная = ОшибкаОтчёта(
            'исход публикации отчёта не подтверждён' if замена_начата
            else 'не удалось подготовить временный отчёт')
        raise первичная from ошибка
    except BaseException as ошибка:
        первичная = ошибка
        if замена_начата:
            указать_unknown(ошибка)
            if isinstance(ошибка, ОшибкаОтчёта):
                первичная = ОшибкаОтчёта('исход публикации отчёта не подтверждён')
                raise первичная from ошибка
        raise
    finally:
        if дескрипторы:
            try:
                _закрыть_удержанные_fd(дескрипторы, None, 'временного отчёта')
            except BaseException as ошибка_закрытия:
                if замена_начата:
                    указать_unknown(ошибка_закрытия)
                if первичная is None:
                    if замена_начата and isinstance(ошибка_закрытия, Exception):
                        raise ОшибкаОтчёта('исход публикации отчёта не подтверждён') from ошибка_закрытия
                    raise
                if первичная is ошибка_закрытия:
                    raise
                if not isinstance(первичная, Exception):
                    raise первичная from ошибка_закрытия
                if not isinstance(ошибка_закрытия, Exception):
                    raise ошибка_закрытия from первичная
                причины = ExceptionGroup(
                    'ошибка публикации и закрытия отчёта', [первичная, ошибка_закрытия])
                raise ОшибкаОтчёта(
                    'исход публикации отчёта не подтверждён' if замена_начата
                    else 'неизвестен исход подготовки и закрытия отчёта') from причины


class _ЗакреплённыеКаталогиПредпросмотра:
    """Однопоточное чтение v1/v2 через удержанные каталоги одной сессии.

    Требуется доверенный однописательский namespace. FD защищают чтение от
    перенаправления имени предка; сверка перед replace не является CAS.
    Повторный вход из обработчиков и иных потоков не допускается.
    EMFILE/ENFILE от штатного open считаются отказом до получения FD при
    отсутствии подмены вызова и handler, выбрасывающего такой же OSError.
    При неизвестном open/close сохраняются владелец и только известные FD;
    номер, потерянный до присваивания, восстановить нельзя.
    """

    _удерживаемые = []

    def __init__(сам, путь_отчёта, каталог_записей, сессия):
        if (not isinstance(путь_отчёта, Path) or not путь_отчёта.is_absolute()
            or '..' in путь_отчёта.parts or not isinstance(каталог_записей, Path)
            or каталог_записей != путь_отчёта.parent / 'материалы' / 'запуски-проверок'
            or type(сессия) is not str):
            raise ОшибкаОтчёта('неверные опоры чтения предпросмотра')
        сам.путь = путь_отчёта
        сам.каталог = каталог_записей
        сам.сессия = сессия
        сам.состояние = 'готов'
        сам.ошибка = None
        сам.первичная = None
        сам.попытка = None
        сам._ресурсы = []
        сам._цепочка = []
        сам._родитель = None
        сам._запуски = None
        сам._процесс = os.getpid()
        сам._поток = threading.current_thread()

    @staticmethod
    def _метка(с):
        return (с.st_dev, с.st_ino, с.st_mode, с.st_uid, с.st_gid, с.st_nlink,
                с.st_size, с.st_mtime_ns, с.st_ctime_ns)

    @staticmethod
    def _метка_папки(с):
        return (с.st_dev, с.st_ino, с.st_mode, с.st_uid, с.st_gid)

    def _вызвать(сам, имя, операция, *аргументы, **ключи):
        if сам.состояние not in ('открытие', 'открыта'):
            raise ОшибкаОтчёта('неизвестная или завершённая опора чтения')
        сам.попытка = (имя, 'начата')
        try:
            результат = операция(*аргументы, **ключи)
        except BaseException as ошибка:
            if (isinstance(ошибка, OSError) and ошибка.errno != errno.EBADF
                and операция in (os.stat, os.fstat, os.read, os.listdir)):
                сам.попытка = (имя, 'подтверждён отказ')
                raise ОшибкаОтчёта('не удалось прочитать опору предпросмотра') from ошибка
            сам.состояние = 'неизвестно'
            сам.ошибка = ошибка
            if isinstance(ошибка, OSError):
                raise ОшибкаОтчёта('не удалось подтвердить операцию опоры чтения') from ошибка
            raise
        сам.попытка = (имя, 'подтверждена')
        return результат

    def _открыть(сам, имя, флаги, *, родитель=None):
        if сам.состояние not in ('открытие', 'открыта'):
            raise ОшибкаОтчёта('неизвестная или завершённая опора чтения')
        запись = {'дескриптор': None, 'фаза': 'открытие начато'}
        сам._ресурсы.append(запись)
        ключи = {} if родитель is None else {'dir_fd': родитель}
        сам.попытка = ('открытие опоры чтения', 'начата')
        try:
            дескриптор = os.open(имя, флаги, **ключи)
        except BaseException as ошибка:
            if isinstance(ошибка, OSError) and ошибка.errno in (errno.EMFILE, errno.ENFILE):
                запись['фаза'] = 'отказ'
                сам.попытка = ('открытие опоры чтения', 'подтверждён отказ')
                raise ОшибкаОтчёта('нет свободного дескриптора для опоры чтения') from ошибка
            сам.состояние = 'неизвестно'
            сам.ошибка = ошибка
            if isinstance(ошибка, OSError):
                raise ОшибкаОтчёта('не удалось открыть опору чтения') from ошибка
            raise
        запись['дескриптор'] = дескриптор
        запись['фаза'] = 'открыта'
        сам.попытка = ('открытие опоры чтения', 'подтверждена')
        return запись

    def _закрыть(сам, запись):
        if сам.состояние not in ('открытие', 'открыта'):
            raise ОшибкаОтчёта('неизвестная или завершённая опора чтения')
        if запись['фаза'] != 'открыта':
            raise ОшибкаОтчёта('неподтверждённая опора чтения')
        запись['фаза'] = 'закрытие начато'
        сам._вызвать('закрытие опоры чтения', os.close, запись['дескриптор'])
        запись['дескриптор'] = None
        запись['фаза'] = 'закрыта'

    def _закрыть_все(сам):
        if сам.состояние not in ('открытие', 'открыта'):
            raise ОшибкаОтчёта('неизвестная или завершённая опора чтения')
        for запись in reversed(сам._ресурсы):
            if запись['фаза'] == 'открыта':
                сам._закрыть(запись)
            elif запись['фаза'] not in ('закрыта', 'отказ'):
                raise ОшибкаОтчёта('неизвестна фаза опоры чтения')

    def _проверить_владельца(сам):
        if (сам.состояние != 'открыта' or os.getpid() != сам._процесс
            or threading.current_thread() is not сам._поток):
            raise ОшибкаОтчёта('опора чтения недоступна или принадлежит другому владельцу')

    def __enter__(сам):
        if (сам.состояние != 'готов' or os.getpid() != сам._процесс
            or threading.current_thread() is not сам._поток) or any(
            владелец.путь == сам.путь and владелец.состояние not in ('подтверждено', 'отказ до чтения')
            for владелец in сам._удерживаемые
        ):
            raise ОшибкаОтчёта('предыдущая опора чтения не подтверждена')
        сам._удерживаемые.append(сам)
        сам.состояние = 'открытие'
        try:
            флаги = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC
            предыдущий = None
            части = ('/', *сам.путь.parent.parts[1:], 'материалы', 'запуски-проверок')
            номер_родителя = len(сам.путь.parent.parts) - 1
            for номер, имя in enumerate(части):
                if предыдущий is None:
                    до = сам._вызвать('метка корня', os.stat, '/', follow_symlinks=False)
                else:
                    до = сам._вызвать('метка каталога', os.stat, имя,
                                      dir_fd=предыдущий, follow_symlinks=False)
                if not stat.S_ISDIR(до.st_mode):
                    raise ОшибкаОтчёта('предок опоры чтения не является обычным каталогом')
                запись = сам._открыть(имя, флаги, родитель=предыдущий)
                fd = запись['дескриптор']
                открытый = сам._вызвать('метка открытого каталога', os.fstat, fd)
                if сам._метка_папки(до) != сам._метка_папки(открытый):
                    raise ОшибкаОтчёта('предок опоры изменился при открытии')
                сам._цепочка.append((имя, запись, сам._метка_папки(открытый)))
                предыдущий = fd
                if номер == номер_родителя:
                    сам._родитель = fd
            сам._запуски = предыдущий
            сам.состояние = 'открыта'
            сам.сверить()
            return сам
        except BaseException as ошибка:
            сам.первичная = ошибка
            if сам.состояние != 'неизвестно':
                try:
                    сам._закрыть_все()
                    сам.состояние = 'отказ до чтения'
                    сам._удерживаемые.remove(сам)
                except BaseException as закрытие:
                    if сам.ошибка is None:
                        сам.ошибка = закрытие
                    сам.состояние = 'неизвестно'
                    if not isinstance(ошибка, Exception):
                        raise ошибка
                    if not isinstance(закрытие, Exception):
                        raise закрытие
                    raise ExceptionGroup('ошибка опоры и её закрытия', [ошибка, закрытие]) from None
            raise

    def __exit__(сам, тип, первичная, трассировка):
        сам.первичная = первичная
        if os.getpid() != сам._процесс or threading.current_thread() is not сам._поток:
            сам.состояние = 'неизвестно'
            сам.ошибка = первичная
        if сам.состояние != 'неизвестно' and any(
            владелец.путь == сам.путь
            and владелец.состояние not in ('подтверждено', 'отказ до эффекта', 'отказ после снимка', 'отказ после журнала')
            for владелец in _ВладелецЗаменыПредпросмотра._удерживаемые
        ):
            сам.состояние = 'неизвестно'
            сам.ошибка = первичная
        if сам.состояние == 'неизвестно':
            if первичная is None:
                raise ОшибкаОтчёта('неизвестна опора чтения предпросмотра')
            return False
        try:
            сам._закрыть_все()
        except BaseException as закрытие:
            if сам.ошибка is None:
                сам.ошибка = закрытие
            сам.состояние = 'неизвестно'
            if первичная is None:
                raise
            if not isinstance(первичная, Exception):
                raise первичная
            if not isinstance(закрытие, Exception):
                raise закрытие
            raise ExceptionGroup('ошибка чтения и закрытия опоры', [первичная, закрытие]) from None
        сам.состояние = 'подтверждено' if первичная is None else 'отказ до чтения'
        сам._удерживаемые.remove(сам)
        return False

    def сверить(сам):
        сам._проверить_владельца()
        предыдущий = None
        for имя, запись, метка in сам._цепочка:
            открытый = сам._вызвать('сверка открытого каталога', os.fstat, запись['дескриптор'])
            if предыдущий is None:
                по_имени = сам._вызвать('сверка имени корня', os.stat, '/', follow_symlinks=False)
            else:
                по_имени = сам._вызвать('сверка имени каталога', os.stat, имя,
                                       dir_fd=предыдущий, follow_symlinks=False)
            if сам._метка_папки(открытый) != метка or сам._метка_папки(по_имени) != метка:
                raise ОшибкаОтчёта('закреплённый каталог предпросмотра изменился')
            предыдущий = запись['дескриптор']

    def _читать(сам, родитель, имя, *, одна_ссылка=False):
        сам._проверить_владельца()
        if type(имя) is not str or not имя or имя in ('.', '..') or '/' in имя:
            raise ОшибкаОтчёта('неверное имя файла закреплённой сессии')
        до = сам._вызвать('метка файла сессии', os.stat, имя,
                          dir_fd=родитель, follow_symlinks=False)
        if not stat.S_ISREG(до.st_mode) or до.st_size < 0 or (одна_ссылка and до.st_nlink != 1):
            raise ОшибкаОтчёта('файл закреплённой сессии не является обычным')
        запись = сам._открыть(имя, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK | os.O_CLOEXEC,
                              родитель=родитель)
        fd = запись['дескриптор']
        if сам._метка(сам._вызвать('метка открытого файла', os.fstat, fd)) != сам._метка(до):
            raise ОшибкаОтчёта('файл сессии заменён до чтения')
        данные = bytearray()
        while len(данные) < до.st_size:
            часть = сам._вызвать('чтение файла сессии', os.read, fd, min(65536, до.st_size - len(данные)))
            if not часть:
                raise ОшибкаОтчёта('файл сессии оборван при чтении')
            данные.extend(часть)
        if сам._вызвать('конец файла сессии', os.read, fd, 1) != b'':
            raise ОшибкаОтчёта('файл сессии вырос при чтении')
        после = сам._вызвать('повторная метка файла', os.fstat, fd)
        по_имени = сам._вызвать('повторная метка имени', os.stat, имя,
                                dir_fd=родитель, follow_symlinks=False)
        if сам._метка(после) != сам._метка(до) or сам._метка(по_имени) != сам._метка(до):
            raise ОшибкаОтчёта('файл сессии изменился при чтении')
        сам._закрыть(запись)
        return bytes(данные), сам._метка(до)

    def отчёт(сам):
        сам.сверить()
        результат = сам._читать(сам._родитель, сам.путь.name, одна_ссылка=True)
        сам.сверить()
        return результат

    def _служебный_файл_есть(сам, имя):
        сам._проверить_владельца()
        сам.попытка = ('сверка служебного имени', 'начата')
        try:
            os.stat(имя, dir_fd=сам._запуски, follow_symlinks=False)
        except FileNotFoundError:
            сам.попытка = ('сверка служебного имени', 'подтверждена')
            return False
        except BaseException as ошибка:
            if isinstance(ошибка, OSError) and ошибка.errno != errno.EBADF:
                сам.попытка = ('сверка служебного имени', 'подтверждён отказ')
                raise ОшибкаОтчёта('не удалось проверить служебный файл') from ошибка
            сам.состояние = 'неизвестно'
            сам.ошибка = ошибка
            if isinstance(ошибка, OSError):
                raise ОшибкаОтчёта('не удалось проверить служебный файл') from ошибка
            raise
        сам.попытка = ('сверка служебного имени', 'подтверждена')
        return True

    def проверить_открытую_сессию(сам):
        сам.сверить()
        if сам._служебный_файл_есть(ИМЯ_ЖУРНАЛА_ВОЗОБНОВЛЕНИЯ):
            raise ОшибкаОтчёта('предпросмотр запрещён до завершения журнала возобновления')
        if сам._служебный_файл_есть(ИМЯ_СНИМКА):
            raise ОшибкаОтчёта('закрытый отчёт нельзя обновить предпросмотром')

    def _имена_записей(сам):
        флаги = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC
        запись = сам._открыть('.', флаги, родитель=сам._запуски)
        fd = запись['дескриптор']
        открытый = сам._вызвать('метка каталога перечисления', os.fstat, fd)
        исходный = сам._вызвать('метка каталога записей', os.fstat, сам._запуски)
        if сам._метка_папки(открытый) != сам._метка_папки(исходный):
            raise ОшибкаОтчёта('каталог перечисления заменён')
        имена = сам._вызвать('чтение каталога записей', os.listdir, fd)
        сам._закрыть(запись)
        return sorted(имена)

    def история(сам):
        сам.сверить()
        имена = сам._имена_записей()
        записи = []
        for имя in имена:
            if имя in (ИМЯ_СНИМКА, ИМЯ_ЖУРНАЛА_ВОЗОБНОВЛЕНИЯ):
                raise ОшибкаОтчёта('служебный файл запрещает предпросмотр')
            if ИМЯ_ФАЙЛА_ЗАПУСКА.fullmatch(имя) is None:
                raise ОшибкаОтчёта('неизвестный файл в закреплённом каталоге запусков')
            байты, _ = сам._читать(сам._запуски, имя)
            try:
                значение = _разобрать_машинный_json(байты.decode('utf-8'))
            except (UnicodeError, ValueError, RecursionError) as ошибка:
                raise ОшибкаОтчёта('не удалось прочитать закреплённую запись') from ошибка
            запись = проверить_запись(значение, имя, сам.сессия)
            if запись['схема'] not in (СХЕМА_ЗАПУСКА, СХЕМА_ЗАПУСКА_С_НАБЛЮДЕНИЯМИ):
                raise ОшибкаОтчёта('профиль исторического Git-снимка неизвестен; закреплённый предпросмотр допускает только v1/v2')
            записи.append((сам.каталог / имя, запись, байты))
        if not записи:
            raise ОшибкаОтчёта('машинный журнал не содержит ни одного запуска')
        if (len({запись['порядок'] for _, запись, _ in записи}) != len(записи)
            or len({запись['идентификатор'] for _, запись, _ in записи}) != len(записи)):
            raise ОшибкаОтчёта('машинный журнал содержит повтор порядка или UUID')
        if сам._имена_записей() != имена:
            raise ОшибкаОтчёта('каталог записей изменился во время чтения')
        сам.сверить()
        return sorted(записи, key=lambda элемент: (int(элемент[1]['порядок']),
                                                    str(элемент[1]['идентификатор'])))


class _ОднократнаяЗаписьМашинногоФайла:
    """Новый машинный файл под замком; ошибки не запускают очистку повторно.

    Родитель и временный файл удерживаются по FD. Каталог, его предки и другие
    процессы того же UID находятся в доверенном однописательском namespace.
    Неизвестный владелец удерживается вызывающим владельцем отчёта в процессе.
    """

    def __init__(сам, путь, байты, проверка, *, _журнал=False, _опора_каталога=None):
        if (not isinstance(путь, Path) or not путь.name or type(байты) is not bytes
            or not callable(проверка) or type(_журнал) is not bool
            or (_опора_каталога is not None
                and (not _журнал or type(_опора_каталога) is not int or _опора_каталога < 0))):
            raise ОшибкаОтчёта('неверные входы однократной машинной записи')
        сам.путь, сам.байты, сам.проверка = путь, байты, проверка
        сам.опора_каталога = _опора_каталога
        сам._именительный = 'журнал возобновления' if _журнал else 'снимок'
        сам._родительный = 'журнала возобновления' if _журнал else 'снимка'
        сам.состояние = 'готов'
        сам.ошибка = None
        сам.попытка = None
        сам.каталог_fd = None
        сам.файл_fd = None
        сам.имя = f'.{путь.name}.{uuid.uuid4()}.tmp'
        сам.метка_каталога = None
        сам.метка_файла = None
        сам.права_файла = None
        сам.процесс, сам.поток = os.getpid(), threading.current_thread()

    def _вызвать(сам, имя, операция, *аргументы, **ключи):
        сам.попытка = (имя, 'начата')
        результат = операция(*аргументы, **ключи)
        сам.попытка = (имя, 'подтверждена')
        return результат

    def _открыть(сам, поле, имя, *аргументы, **ключи):
        сам.попытка = (имя, 'начата')
        дескриптор = os.open(*аргументы, **ключи)
        setattr(сам, поле, дескриптор)
        сам.попытка = (имя, 'подтверждена')
        return дескриптор

    @staticmethod
    def _метка_папки(сведения):
        return (сведения.st_dev, сведения.st_ino, сведения.st_mode, сведения.st_uid, сведения.st_gid)

    def _сверить_каталог(сам):
        открытый = os.fstat(сам.каталог_fd)
        по_пути = сам.путь.parent.lstat()
        if (not stat.S_ISDIR(открытый.st_mode) or not stat.S_ISDIR(по_пути.st_mode)
            or сам._метка_папки(открытый) != сам.метка_каталога
            or сам._метка_папки(по_пути) != сам.метка_каталога):
            raise ОшибкаОтчёта(f'каталог {сам._родительный} изменился')
        if сам.опора_каталога is not None:
            опора = os.fstat(сам.опора_каталога)
            if not stat.S_ISDIR(опора.st_mode) or сам._метка_папки(опора) != сам.метка_каталога:
                raise ОшибкаОтчёта(f'каталог {сам._родительный} не совпадает с удерживаемой опорой')

    def _сверить_файл(сам, ссылок):
        сведения = os.fstat(сам.файл_fd)
        if (not stat.S_ISREG(сведения.st_mode) or сведения.st_nlink != ссылок
            or (сведения.st_dev, сведения.st_ino) != сам.метка_файла
            or (stat.S_IMODE(сведения.st_mode), сведения.st_uid, сведения.st_gid, сведения.st_flags)
               != сам.права_файла
            or сведения.st_size != len(сам.байты)):
            raise ОшибкаОтчёта(f'временный {сам._именительный} изменился')
        позиция = 0
        while позиция < len(сам.байты):
            часть = os.pread(сам.файл_fd, min(65536, len(сам.байты) - позиция), позиция)
            if not часть or часть != сам.байты[позиция:позиция + len(часть)]:
                raise ОшибкаОтчёта(f'байты временного {сам._родительный} изменились')
            позиция += len(часть)
        if os.pread(сам.файл_fd, 1, позиция):
            raise ОшибкаОтчёта(f'временный {сам._именительный} вырос')
        после = os.fstat(сам.файл_fd)
        if (после.st_dev, после.st_ino, после.st_mode, после.st_uid, после.st_gid,
            после.st_nlink, после.st_size, после.st_mtime_ns, после.st_ctime_ns) != (
                сведения.st_dev, сведения.st_ino, сведения.st_mode, сведения.st_uid, сведения.st_gid,
                сведения.st_nlink, сведения.st_size, сведения.st_mtime_ns, сведения.st_ctime_ns):
            raise ОшибкаОтчёта(f'временный {сам._именительный} изменился при чтении')

    def выполнить(сам):
        if (сам.состояние != 'готов' or os.getpid() != сам.процесс
            or threading.current_thread() is not сам.поток):
            raise ОшибкаОтчёта(f'повтор или чужой владелец записи {сам._родительный}')
        сам.состояние = 'подготовка'
        try:
            сам._вызвать(f'проверка перед подготовкой {сам._родительный}', сам.проверка)
            до = сам.путь.parent.lstat()
            if not stat.S_ISDIR(до.st_mode):
                raise ОшибкаОтчёта(f'каталог {сам._родительный} не является физическим каталогом')
            сам.метка_каталога = сам._метка_папки(до)
            сам._открыть('каталог_fd', f'открытие каталога {сам._родительный}', сам.путь.parent,
                         os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
            сам._сверить_каталог()
            сам._открыть('файл_fd', f'открытие временного {сам._родительный}', сам.имя,
                         os.O_RDWR | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | os.O_CLOEXEC,
                         0o644, dir_fd=сам.каталог_fd)
            файл = os.fstat(сам.файл_fd)
            if (not stat.S_ISREG(файл.st_mode) or файл.st_nlink != 1
                or файл.st_uid != os.geteuid() or файл.st_mode & 0o133 or файл.st_flags != 0):
                raise ОшибкаОтчёта(f'неверный новый временный {сам._именительный}')
            сам.метка_файла = (файл.st_dev, файл.st_ino)
            сам.права_файла = (stat.S_IMODE(файл.st_mode), файл.st_uid, файл.st_gid, файл.st_flags)
            позиция = 0
            while позиция < len(сам.байты):
                часть = сам.байты[позиция:позиция + 65536]
                число = сам._вызвать(f'запись {сам._родительный}', os.write, сам.файл_fd, часть)
                if type(число) is not int or not 0 < число <= len(часть):
                    raise ОшибкаОтчёта(f'неполная запись {сам._родительный}')
                позиция += число
            сам._вызвать(f'синхронизация {сам._родительный}', os.fsync, сам.файл_fd)
            сам._сверить_каталог()
            сам._сверить_файл(1)
            сам._вызвать(f'проверка перед публикацией {сам._родительный}', сам.проверка)
            сам._сверить_каталог()
            временный = os.stat(сам.имя, dir_fd=сам.каталог_fd, follow_symlinks=False)
            if (not stat.S_ISREG(временный.st_mode) or временный.st_nlink != 1
                or (временный.st_dev, временный.st_ino) != сам.метка_файла):
                raise ОшибкаОтчёта(f'имя временного {сам._родительный} подменено')
            сам._сверить_файл(1)
            сам._вызвать(f'публикация нового {сам._родительный}', os.link, сам.имя, сам.путь.name,
                         src_dir_fd=сам.каталог_fd, dst_dir_fd=сам.каталог_fd, follow_symlinks=False)
            сам._сверить_каталог()
            for имя in (сам.имя, сам.путь.name):
                сведения = os.stat(имя, dir_fd=сам.каталог_fd, follow_symlinks=False)
                if (not stat.S_ISREG(сведения.st_mode) or сведения.st_nlink != 2
                    or (сведения.st_dev, сведения.st_ino) != сам.метка_файла):
                    raise ОшибкаОтчёта(f'публикация {сам._родительный} не подтверждена')
            сам._сверить_файл(2)
            сам._вызвать(f'синхронизация публикации {сам._родительный}', os.fsync, сам.каталог_fd)
            сам._сверить_каталог()
            временный = os.stat(сам.имя, dir_fd=сам.каталог_fd, follow_symlinks=False)
            if (not stat.S_ISREG(временный.st_mode) or временный.st_nlink != 2
                or (временный.st_dev, временный.st_ino) != сам.метка_файла):
                raise ОшибкаОтчёта(f'временное имя {сам._родительный} изменилось до удаления')
            сам._вызвать(f'удаление временного имени {сам._родительный}', os.unlink, сам.имя, dir_fd=сам.каталог_fd)
            сам._сверить_файл(1)
            try:
                os.stat(сам.имя, dir_fd=сам.каталог_fd, follow_symlinks=False)
            except FileNotFoundError:
                pass
            else:
                raise ОшибкаОтчёта(f'временное имя {сам._родительный} осталось после удаления')
            опубликованный = os.stat(сам.путь.name, dir_fd=сам.каталог_fd, follow_symlinks=False)
            if (not stat.S_ISREG(опубликованный.st_mode) or опубликованный.st_nlink != 1
                or (опубликованный.st_dev, опубликованный.st_ino) != сам.метка_файла):
                raise ОшибкаОтчёта(f'новый {сам._именительный} не подтверждён')
            сам._вызвать(f'синхронизация очистки {сам._родительный}', os.fsync, сам.каталог_fd)
            сам._вызвать(f'закрытие {сам._родительный}', os.close, сам.файл_fd)
            сам.файл_fd = None
            сам._вызвать(f'закрытие каталога {сам._родительный}', os.close, сам.каталог_fd)
            сам.каталог_fd = None
            сам.состояние = 'подтверждено'
        except BaseException as ошибка:
            сам.состояние = 'неизвестно'
            сам.ошибка = ошибка
            raise


_ОднократнаяЗаписьСнимкаЗакрытия = _ОднократнаяЗаписьМашинногоФайла


class _ИзвестныйОтказПредпросмотра(ОшибкаОтчёта):
    """Подтверждённый отказ до изменения отчёта и подготовительного каталога."""


class _ПодтверждённыйОтказПослеСнимка(_ИзвестныйОтказПредпросмотра):
    """Только известный отказ до rename после подтверждённого снимка и проверки замка."""


class _ПодтверждённыйОтказПослеЖурнала(_ИзвестныйОтказПредпросмотра):
    """Известный отказ до rename после проверки журнала, снимка и замка."""


class _ВладелецЗаменыПредпросмотра:
    """Одна замена в согласованном доверенном namespace Darwin arm64/APFS.

    Соседний каталог закрыт для иных UID; процессы того же UID и способные
    менять закреплённые опоры входят в доверенную однописательскую границу.
    Повторный вход из обработчиков и иных потоков не допускается.
    Выпуск 27.2.0 — временный первый допуск, не оценка других версий.
    Сохраняются только наблюдаемые ACL и xattr; скрытые атрибуты не доказаны.
    Проверка перед публикацией допускает повторный вызов без побочных эффектов.
    Действие после подготовки выполняется не более одного раза до замены отчёта.
    При ошибке владелец и известные FD удерживаются без повторной очистки.
    """

    _удерживаемые = []

    def __init__(сам, путь, блок, ожидаемые, проверка, каталоги=None, после_подготовки=None,
                 подтвердить_метаданные=False):
        if (not isinstance(путь, Path) or not путь.name or type(блок) is not str
            or (ожидаемые is not None and type(ожидаемые) is not bytes)
            or (проверка is not None and not callable(проверка))
            or (после_подготовки is not None and not callable(после_подготовки))
            or (после_подготовки is not None and проверка is None)
            or type(подтвердить_метаданные) is not bool
            or (подтвердить_метаданные and (проверка is None or ожидаемые is None
                                            or после_подготовки is not None))
            or (каталоги is not None and type(каталоги) is not _ЗакреплённыеКаталогиПредпросмотра)):
            raise ОшибкаОтчёта('неверные параметры безопасного предпросмотра')
        if '..' in путь.parts:
            raise ОшибкаОтчёта('путь предпросмотра содержит переход к предку')
        сам.путь = Path(os.path.abspath(os.fspath(путь)))
        сам.блок = блок
        сам.ожидаемые = ожидаемые
        сам.проверка = проверка
        сам.после_подготовки = после_подготовки
        сам.подтвердить_метаданные = подтвердить_метаданные
        сам._каталоги = каталоги
        сам.состояние = 'готов'
        сам.ошибка = None
        сам.первичная = None
        сам.попытка = None
        сам.замена_начата = False
        сам.действие_подтверждено = False
        сам._родитель = None
        сам._предки = []
        сам._исходный = None
        сам._каталог = None
        сам._временный = None
        сам._системы = []
        сам._метка_родителя = None
        сам._метка_каталога = None
        сам._метка_исходного = None
        сам._метка_временного = None
        сам._имя_каталога = None
        сам._байты = None
        сам._список = None
        сам._атрибуты = None
        сам._процесс = os.getpid()
        сам._поток = threading.current_thread()

    def _вызвать(сам, имя, операция, *аргументы, **ключи):
        сам.попытка = (имя, 'начата')
        результат = операция(*аргументы, **ключи)
        сам.попытка = (имя, 'подтверждена')
        return результат

    def _открыть(сам, поле, имя, *аргументы, **ключи):
        сам.попытка = (имя, 'начата')
        дескриптор = os.open(*аргументы, **ключи)
        setattr(сам, поле, дескриптор)
        сам.попытка = (имя, 'подтверждена')
        return дескриптор

    def _открыть_родителей(сам):
        флаги = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC
        предыдущий = None
        for имя in ('/', *сам.путь.parent.parts[1:]):
            if предыдущий is None:
                до = os.stat('/', follow_symlinks=False)
            else:
                до = os.stat(имя, dir_fd=предыдущий, follow_symlinks=False)
            if not stat.S_ISDIR(до.st_mode):
                raise _ИзвестныйОтказПредпросмотра('предок отчёта не является физическим каталогом')
            запись = {'имя': имя, 'дескриптор': None, 'метка': None}
            сам._предки.append(запись)
            сам.попытка = ('открытие предка отчёта', 'начата')
            if предыдущий is None:
                дескриптор = os.open('/', флаги)
            else:
                дескриптор = os.open(имя, флаги, dir_fd=предыдущий)
            запись['дескриптор'] = дескриптор
            сам.попытка = ('открытие предка отчёта', 'подтверждена')
            открытый = os.fstat(дескриптор)
            if сам._метка_папки(до) != сам._метка_папки(открытый):
                raise ОшибкаОтчёта('предок отчёта изменился при открытии')
            запись['метка'] = сам._метка_папки(открытый)
            предыдущий = дескриптор
        сам._родитель = предыдущий

    def _закрыть_предков(сам):
        for запись in reversed(сам._предки):
            сам._вызвать('закрытие предка отчёта', os.close, запись['дескриптор'])
            запись['дескриптор'] = None
        сам._родитель = None

    @staticmethod
    def _метка(сведения):
        return (сведения.st_dev, сведения.st_ino, сведения.st_mode, сведения.st_uid,
                сведения.st_gid, сведения.st_nlink, сведения.st_size,
                сведения.st_mtime_ns, сведения.st_ctime_ns, сведения.st_flags)

    @staticmethod
    def _метка_папки(сведения):
        return (сведения.st_dev, сведения.st_ino, сведения.st_mode,
                сведения.st_uid, сведения.st_gid)

    def _проверить_файловую_систему(сам, дескриптор):
        if sys.platform != 'darwin':
            raise ОшибкаОтчёта('безопасный предпросмотр требует подтверждённый Darwin arm64')
        версия = os.uname()
        if версия.machine != 'arm64' or версия.release != '27.2.0':
            raise ОшибкаОтчёта('безопасный предпросмотр требует подтверждённый Darwin arm64')
        import ctypes

        class Сведения(ctypes.Structure):
            _fields_ = [
                ('размер_блока', ctypes.c_uint32), ('размер_ввода', ctypes.c_int32),
                ('блоки', ctypes.c_uint64), ('свободно', ctypes.c_uint64),
                ('доступно', ctypes.c_uint64), ('файлы', ctypes.c_uint64),
                ('свободные_файлы', ctypes.c_uint64), ('идентификатор', ctypes.c_int32 * 2),
                ('владелец', ctypes.c_uint32), ('тип', ctypes.c_uint32),
                ('флаги', ctypes.c_uint32), ('подтип', ctypes.c_uint32),
                ('имя', ctypes.c_char * 16), ('каталог', ctypes.c_char * 1024),
                ('источник', ctypes.c_char * 1024), ('расширенные_флаги', ctypes.c_uint32),
                ('резерв', ctypes.c_uint32 * 7),
            ]
        if (ctypes.sizeof(ctypes.c_void_p) != 8 or ctypes.sizeof(ctypes.c_long) != 8
            or sys.byteorder != 'little' or ctypes.sizeof(Сведения) != 2168
            or ctypes.alignment(Сведения) != 8 or Сведения.имя.offset != 72
            or Сведения.флаги.offset != 64 or Сведения.расширенные_флаги.offset != 2136):
            raise ОшибкаОтчёта('неверный ABI файловой системы предпросмотра')
        try:
            библиотека = ctypes.CDLL(None, use_errno=True)
            получить = библиотека.fstatfs
        except (AttributeError, OSError) as ошибка:
            raise ОшибкаОтчёта('нет fstatfs для предпросмотра') from ошибка
        получить.argtypes = [ctypes.c_int, ctypes.POINTER(Сведения)]
        получить.restype = ctypes.c_int
        сведения = Сведения()
        if получить(дескриптор, ctypes.byref(сведения)) != 0:
            raise OSError(ctypes.get_errno() or errno.EIO, 'неизвестна файловая система')
        if (сведения.имя != b'apfs' or not сведения.флаги & 0x1000
            or сведения.флаги & (0x1 | 0x200000) or сведения.расширенные_флаги & 0x2):
            raise ОшибкаОтчёта('файловая система предпросмотра не допущена')
        return tuple(сведения.идентификатор)

    def _список_для_fd(сам, дескриптор):
        система = _ВызовыСписковДоступаДарвина()
        сам._системы.append(система)
        данные, _ = сам._вызвать('чтение списка доступа', система._снять, дескриптор)
        сам._вызвать('освобождение списка доступа', система._освободить_подтверждённые)
        return данные

    def _атрибуты_для_fd(сам, дескриптор):
        система = _ВызовыВидимыхАтрибутовДарвина()
        сам._системы.append(система)
        return сам._вызвать('чтение видимых атрибутов', система.снять, дескриптор)

    def _очистить_список_каталога(сам):
        система = _ВызовыСписковДоступаДарвина()
        сам._системы.append(система)
        типы = система._типы
        try:
            создать = система._библиотека.acl_init
        except AttributeError as ошибка:
            raise ОшибкаОтчёта('нельзя создать пустой список для каталога') from ошибка
        создать.argtypes = [типы.c_int]
        создать.restype = типы.c_void_p
        список = сам._вызвать('получение пустого списка', система._получить_объект,
                              'список', создать, 0)
        сам._вызвать('очистка списка каталога', система._установить, сам._каталог, список)
        данные, _ = сам._вызвать('сверка списка каталога', система._снять, сам._каталог)
        if данные is not None:
            raise ОшибкаОтчёта('список подготовительного каталога не очищен')
        сам._вызвать('освобождение списка каталога', система._освободить_подтверждённые)

    def _прочитать(сам, дескриптор, размер):
        части = bytearray()
        позиция = 0
        while позиция < размер:
            часть = сам._вызвать('чтение файла', os.pread, дескриптор, min(65536, размер - позиция), позиция)
            if not часть:
                raise ОшибкаОтчёта('файл оборван при чтении предпросмотра')
            части.extend(часть)
            позиция += len(часть)
        if сам._вызвать('проверка конца файла', os.pread, дескриптор, 1, позиция) != b'':
            raise ОшибкаОтчёта('файл вырос при чтении предпросмотра')
        return bytes(части)

    def _сверить_родителя(сам):
        предыдущий = None
        for запись in сам._предки:
            открытый = os.fstat(запись['дескриптор'])
            if предыдущий is None:
                по_имени = os.stat('/', follow_symlinks=False)
            else:
                по_имени = os.stat(запись['имя'], dir_fd=предыдущий, follow_symlinks=False)
            if (сам._метка_папки(открытый) != запись['метка']
                or сам._метка_папки(по_имени) != запись['метка']):
                raise ОшибкаОтчёта('цепочка каталогов отчёта изменилась')
            предыдущий = запись['дескриптор']
        открытый = os.fstat(сам._родитель)
        по_пути = os.stat(сам.путь.parent, follow_symlinks=False)
        if (not stat.S_ISDIR(открытый.st_mode)
            or сам._метка_папки(открытый) != сам._метка_родителя
            or сам._метка_папки(по_пути) != сам._метка_родителя):
            raise ОшибкаОтчёта('каталог предпросмотра изменился')

    def _сверить_исходный(сам):
        сам._сверить_родителя()
        открытый = os.fstat(сам._исходный)
        по_имени = os.stat(сам.путь.name, dir_fd=сам._родитель, follow_symlinks=False)
        if (сам._метка(открытый) != сам._метка_исходного
            or сам._метка(по_имени) != сам._метка_исходного):
            raise ОшибкаОтчёта('исходный отчёт изменился')

    def _сверить_каталог(сам):
        каталог = os.fstat(сам._каталог)
        по_имени = os.stat(сам._имя_каталога, dir_fd=сам._родитель, follow_symlinks=False)
        if (сам._метка_папки(каталог) != сам._метка_каталога
            or сам._метка_папки(по_имени) != сам._метка_каталога):
            raise ОшибкаОтчёта('подготовительный каталог изменился')

    def _сверить_временный(сам, режим):
        сам._сверить_исходный()
        сам._сверить_каталог()
        открытый = os.fstat(сам._временный)
        по_имени = os.stat('отчёт', dir_fd=сам._каталог, follow_symlinks=False)
        метка = (открытый.st_dev, открытый.st_ino)
        if (not stat.S_ISREG(открытый.st_mode) or открытый.st_nlink != 1
            or метка != сам._метка_временного
            or (по_имени.st_dev, по_имени.st_ino) != метка
            or (открытый.st_uid, открытый.st_gid) != сам._метка_исходного[3:5]
            or stat.S_IMODE(открытый.st_mode) != режим or открытый.st_flags != 0
            or сам._прочитать(сам._временный, открытый.st_size) != сам._байты):
            raise ОшибкаОтчёта('временный отчёт изменился')

    def _закрыть(сам, поле, имя):
        дескриптор = getattr(сам, поле)
        сам._вызвать(имя, os.close, дескриптор)
        setattr(сам, поле, None)

    def _отменить_подготовку_после_действия(сам):
        """Освобождает подтверждённую подготовку до попытки замены отчёта."""
        сам._сверить_родителя()
        сам._сверить_каталог()
        открытый = os.fstat(сам._временный)
        по_имени = os.stat('отчёт', dir_fd=сам._каталог, follow_symlinks=False)
        if (not stat.S_ISREG(открытый.st_mode) or открытый.st_nlink != 1
            or (открытый.st_dev, открытый.st_ino) != сам._метка_временного
            or (по_имени.st_dev, по_имени.st_ino) != сам._метка_временного
            or not stat.S_ISREG(по_имени.st_mode) or по_имени.st_nlink != 1):
            raise ОшибкаОтчёта('временный отчёт изменился до отмены подготовки')
        сам._вызвать('удаление временного отчёта', os.unlink, 'отчёт', dir_fd=сам._каталог)
        if os.fstat(сам._временный).st_nlink != 0:
            raise ОшибкаОтчёта('удаление временного отчёта не подтверждено')
        try:
            os.stat('отчёт', dir_fd=сам._каталог, follow_symlinks=False)
        except FileNotFoundError:
            pass
        else:
            raise ОшибкаОтчёта('имя временного отчёта осталось после удаления')
        сам._вызвать('синхронизация отмены отчёта', os.fsync, сам._каталог)
        сам._закрыть('_временный', 'закрытие отменённого отчёта')
        сам._закрыть('_исходный', 'закрытие исходного отчёта')
        сам._сверить_каталог()
        сам._закрыть('_каталог', 'закрытие подготовительного каталога')
        сам._вызвать('удаление подготовительного каталога', os.rmdir,
                     сам._имя_каталога, dir_fd=сам._родитель)
        сам._вызвать('синхронизация отмены подготовки', os.fsync, сам._родитель)
        сам._сверить_родителя()
        сам._закрыть_предков()

    def выполнить(сам):
        if (сам.состояние != 'готов' or os.getpid() != сам._процесс
            or threading.current_thread() is not сам._поток):
            raise ОшибкаОтчёта('повтор или чужой владелец предпросмотра')
        if any(владелец.путь == сам.путь and владелец.состояние not in ('подтверждено', 'отказ до эффекта', 'отказ после снимка', 'отказ после журнала')
               for владелец in сам._удерживаемые):
            raise ОшибкаОтчёта('предыдущий исход предпросмотра не подтверждён')
        for владелец in tuple(сам._удерживаемые):
            if владелец.путь == сам.путь and владелец.состояние in ('подтверждено', 'отказ до эффекта', 'отказ после снимка', 'отказ после журнала'):
                сам._удерживаемые.remove(владелец)
        сам._удерживаемые.append(сам)
        сам.состояние = 'подготовка'
        try:
            флаги_папки = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC
            сам._открыть_родителей()
            родитель = os.fstat(сам._родитель)
            сам._метка_родителя = сам._метка_папки(родитель)
            сам._сверить_родителя()
            if сам._каталоги is not None:
                сам._каталоги.сверить()
                закреплённый = os.fstat(сам._каталоги._родитель)
                if (сам._каталоги.путь != сам.путь
                    or сам._метка_папки(закреплённый) != сам._метка_родителя):
                    raise ОшибкаОтчёта('родитель отчёта не совпадает с опорой чтения')
            if any(
                владелец is not сам and владелец.состояние not in ('подтверждено', 'отказ до эффекта', 'отказ после снимка', 'отказ после журнала')
                and владелец._метка_родителя is not None
                and владелец._метка_родителя[:2] == сам._метка_родителя[:2]
                and владелец.путь.name == сам.путь.name
                for владелец in сам._удерживаемые
            ):
                raise ОшибкаОтчёта('предыдущий исход этого отчёта не подтверждён')
            файловая_система = сам._проверить_файловую_систему(сам._родитель)
            до = os.stat(сам.путь.name, dir_fd=сам._родитель, follow_symlinks=False)
            if stat.S_IMODE(до.st_mode) & 0o7000 and not сам.подтвердить_метаданные:
                raise _ИзвестныйОтказПредпросмотра('обновление отчёта со специальными битами прав пока не допущено')
            if (not stat.S_ISREG(до.st_mode) or до.st_nlink != 1 or до.st_size < 0
                or до.st_flags != 0):
                raise _ИзвестныйОтказПредпросмотра('отчёт не допущен для сохранения метаданных')
            сам._метка_исходного = сам._метка(до)
            сам._открыть('_исходный', 'открытие отчёта', сам.путь.name,
                         os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK | os.O_CLOEXEC,
                         dir_fd=сам._родитель)
            сам._сверить_исходный()
            if сам._проверить_файловую_систему(сам._исходный) != файловая_система:
                raise ОшибкаОтчёта('отчёт расположен на другой файловой системе')
            исходные = сам._прочитать(сам._исходный, до.st_size)
            сам._сверить_исходный()
            if сам.ожидаемые is not None and исходные != сам.ожидаемые:
                raise _ИзвестныйОтказПредпросмотра('отчёт изменился до формирования замены')
            try:
                сам._байты = заменить_управляемый_блок_в_байтах(исходные, сам.блок)
            except ОшибкаОтчёта as ошибка:
                raise _ИзвестныйОтказПредпросмотра('не удалось подготовить блок отчёта') from ошибка
            if сам.подтвердить_метаданные and сам._байты != исходные:
                raise _ИзвестныйОтказПредпросмотра('открытый отчёт не совпадает с ожидаемым блоком')
            if сам._байты == исходные:
                if сам.после_подготовки is not None:
                    raise _ИзвестныйОтказПредпросмотра('нет замены для подготовленного действия')
                if сам.проверка is not None:
                    сам._вызвать('проверка предпросмотра', сам.проверка)
                сам._сверить_исходный()
                if сам.подтвердить_метаданные:
                    сам._список = сам._список_для_fd(сам._исходный)
                    сам._атрибуты = сам._атрибуты_для_fd(сам._исходный)
                    сам._сверить_исходный()
                    сам._вызвать('синхронизация открытого отчёта', os.fsync, сам._исходный)
                    сам._вызвать('синхронизация каталога открытого отчёта', os.fsync, сам._родитель)
                    сам._вызвать('повторная проверка открытого отчёта', сам.проверка)
                    if (сам._список_для_fd(сам._исходный) != сам._список
                        or сам._атрибуты_для_fd(сам._исходный) != сам._атрибуты):
                        raise ОшибкаОтчёта('метаданные открытого отчёта изменились')
                    сам._сверить_исходный()
                сам._закрыть('_исходный', 'закрытие исходного отчёта')
                сам._закрыть_предков()
                сам._байты = None
                сам.блок = None
                сам.ожидаемые = None
                сам.проверка = None
                сам.состояние = 'подтверждено'
                return
            сам._список = сам._список_для_fd(сам._исходный)
            сам._атрибуты = сам._атрибуты_для_fd(сам._исходный)
            сам._сверить_исходный()
            сам._имя_каталога = f'.{сам.путь.name}.{uuid.uuid4()}.подготовка'
            сам._вызвать('создание подготовительного каталога', os.mkdir,
                         сам._имя_каталога, 0o700, dir_fd=сам._родитель)
            сам._открыть('_каталог', 'открытие подготовительного каталога', сам._имя_каталога,
                         флаги_папки, dir_fd=сам._родитель)
            сведения = os.fstat(сам._каталог)
            по_имени = os.stat(сам._имя_каталога, dir_fd=сам._родитель, follow_symlinks=False)
            if (not stat.S_ISDIR(сведения.st_mode) or сведения.st_uid != os.geteuid()
                or (сведения.st_dev, сведения.st_ino) != (по_имени.st_dev, по_имени.st_ino)
                or сведения.st_dev != родитель.st_dev):
                raise ОшибкаОтчёта('неверный подготовительный каталог предпросмотра')
            сам._очистить_список_каталога()
            сам._вызвать('права подготовительного каталога', os.fchmod, сам._каталог, 0o700)
            сведения = os.fstat(сам._каталог)
            if stat.S_IMODE(сведения.st_mode) != 0o700 or сам._список_для_fd(сам._каталог) is not None:
                raise ОшибкаОтчёта('подготовительный каталог не закрыт')
            сам._метка_каталога = сам._метка_папки(сведения)
            сам._открыть('_временный', 'открытие временного отчёта', 'отчёт',
                         os.O_RDWR | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | os.O_CLOEXEC,
                         0o600, dir_fd=сам._каталог)
            сведения = os.fstat(сам._временный)
            if (not stat.S_ISREG(сведения.st_mode) or сведения.st_nlink != 1
                or (сведения.st_dev, сведения.st_uid, сведения.st_gid)
                   != (до.st_dev, до.st_uid, до.st_gid) or сведения.st_flags != 0):
                raise ОшибкаОтчёта('неверный временный отчёт')
            сам._метка_временного = (сведения.st_dev, сведения.st_ino)
            сам._вызвать('начальные права отчёта', os.fchmod, сам._временный, 0o600)
            сведения = os.fstat(сам._временный)
            if stat.S_IMODE(сведения.st_mode) != 0o600 or сам._список_для_fd(сам._временный) is not None:
                raise ОшибкаОтчёта('временный отчёт не закрыт')
            позиция = 0
            while позиция < len(сам._байты):
                часть = сам._байты[позиция:позиция + 65536]
                число = сам._вызвать('запись временного отчёта', os.write, сам._временный, часть)
                if type(число) is not int or not 0 < число <= len(часть):
                    raise ОшибкаОтчёта('неполная запись временного отчёта')
                позиция += число
            сам._вызвать('синхронизация содержимого', os.fsync, сам._временный)
            if сам.проверка is not None:
                сам._вызвать('проверка предпросмотра', сам.проверка)
            сам._сверить_временный(0o600)
            система = _ВызовыВидимыхАтрибутовДарвина()
            перенос = _ОпытныйПереносВидимыхАтрибутов(система, сам._исходный, сам._временный)
            сам._системы.append(перенос)
            сам._вызвать('перенос видимых атрибутов', перенос.выполнить)
            система = _ВызовыСписковДоступаДарвина()
            перенос = _ОпытныйПереносСпискаДоступа(система, сам._исходный, сам._временный)
            сам._системы.append(перенос)
            сам._вызвать('перенос списка доступа', перенос.выполнить)
            режим = stat.S_IMODE(до.st_mode)
            сам._вызвать('восстановление прав отчёта', os.fchmod, сам._временный, режим)
            сам._вызвать('синхронизация отчёта', os.fsync, сам._временный)
            сам._сверить_временный(режим)
            if (сам._список_для_fd(сам._исходный) != сам._список
                or сам._список_для_fd(сам._временный) != сам._список
                or сам._атрибуты_для_fd(сам._исходный) != сам._атрибуты
                or сам._атрибуты_для_fd(сам._временный) != сам._атрибуты):
                raise ОшибкаОтчёта('метаданные отчёта не подтверждены до замены')
            сам._сверить_временный(режим)
            сам._вызвать('синхронизация подготовительного каталога', os.fsync, сам._каталог)
            if сам.после_подготовки is not None:
                сам._вызвать('действие после подготовки отчёта', сам.после_подготовки)
                сам.действие_подтверждено = True
            if сам.проверка is not None:
                сам._вызвать('повторная проверка предпросмотра', сам.проверка)
                if (сам._список_для_fd(сам._исходный) != сам._список
                    or сам._список_для_fd(сам._временный) != сам._список
                    or сам._атрибуты_для_fd(сам._исходный) != сам._атрибуты
                    or сам._атрибуты_для_fd(сам._временный) != сам._атрибуты):
                    raise ОшибкаОтчёта('метаданные отчёта изменились после проверки')
            сам._сверить_временный(режим)
            сам.замена_начата = True
            сам._вызвать('замена отчёта', os.replace, 'отчёт', сам.путь.name,
                         src_dir_fd=сам._каталог, dst_dir_fd=сам._родитель)
            сам._сверить_родителя()
            новая = os.fstat(сам._временный)
            по_имени = os.stat(сам.путь.name, dir_fd=сам._родитель, follow_symlinks=False)
            if ((новая.st_dev, новая.st_ino) != сам._метка_временного
                or (по_имени.st_dev, по_имени.st_ino) != сам._метка_временного
                or not stat.S_ISREG(новая.st_mode) or новая.st_nlink != 1
                or (новая.st_uid, новая.st_gid) != сам._метка_исходного[3:5]
                or stat.S_IMODE(новая.st_mode) != режим or новая.st_flags != 0
                or сам._прочитать(сам._временный, новая.st_size) != сам._байты
                or сам._список_для_fd(сам._временный) != сам._список
                or сам._атрибуты_для_fd(сам._временный) != сам._атрибуты):
                raise ОшибкаОтчёта('опубликованный отчёт не подтверждён')
            сам._вызвать('синхронизация каталога отчёта', os.fsync, сам._родитель)
            сам._вызвать('синхронизация подготовительного каталога после замены', os.fsync, сам._каталог)
            сам._сверить_каталог()
            сам._закрыть('_исходный', 'закрытие исходного отчёта')
            сам._закрыть('_временный', 'закрытие нового отчёта')
            сам._закрыть('_каталог', 'закрытие подготовительного каталога')
            сам._вызвать('удаление подготовительного каталога', os.rmdir,
                         сам._имя_каталога, dir_fd=сам._родитель)
            сам._вызвать('синхронизация удаления подготовительного каталога', os.fsync, сам._родитель)
            сам._сверить_родителя()
            сам._закрыть_предков()
            сам._байты = None
            сам._список = None
            сам._атрибуты = None
            сам._системы.clear()
            сам.блок = None
            сам.ожидаемые = None
            сам.проверка = None
            сам.после_подготовки = None
            сам.состояние = 'подтверждено'
        except _ИзвестныйОтказПредпросмотра as ошибка:
            сам.первичная = ошибка
            if сам._имя_каталога is not None:
                if (isinstance(ошибка, (_ПодтверждённыйОтказПослеСнимка, _ПодтверждённыйОтказПослеЖурнала))
                    and сам.действие_подтверждено and not сам.замена_начата):
                    try:
                        сам._отменить_подготовку_после_действия()
                    except BaseException as закрытие:
                        сам.состояние = 'неизвестно'
                        сам.ошибка = закрытие
                        if not isinstance(закрытие, Exception):
                            raise закрытие from ошибка
                        причины = ExceptionGroup('отказ и неизвестная отмена подготовки', [ошибка, закрытие])
                        raise ОшибкаОтчёта('неизвестен исход отмены подготовки') from причины
                    сам.состояние = ('отказ после снимка' if isinstance(ошибка, _ПодтверждённыйОтказПослеСнимка)
                                     else 'отказ после журнала')
                    сам.ошибка = ошибка
                    raise
                сам.состояние = 'неизвестно'
                сам.ошибка = ошибка
                raise
            try:
                if сам._исходный is not None:
                    сам._закрыть('_исходный', 'закрытие исходного отчёта')
                сам._закрыть_предков()
            except BaseException as закрытие:
                сам.состояние = 'неизвестно'
                сам.ошибка = закрытие
                if not isinstance(закрытие, Exception):
                    raise закрытие from ошибка
                причины = ExceptionGroup('отказ и неизвестное закрытие', [ошибка, закрытие])
                raise ОшибкаОтчёта('неизвестен исход закрытия предпросмотра') from причины
            сам.состояние = 'отказ до эффекта'
            сам.ошибка = ошибка
            raise
        except BaseException as ошибка:
            сам.состояние = 'неизвестно'
            сам.ошибка = ошибка
            if сам.замена_начата and isinstance(ошибка, Exception):
                raise ОшибкаОтчёта('исход публикации отчёта не подтверждён') from ошибка
            if isinstance(ошибка, OSError):
                raise ОшибкаОтчёта('не удалось безопасно подготовить отчёт') from ошибка
            if сам.замена_начата:
                try:
                    BaseException.add_note(ошибка, 'Исход публикации отчёта не подтверждён; повтор не разрешён.')
                except BaseException:
                    pass
            raise


class _ВладелецВозобновления:
    """Фазы одной сессии; UNKNOWN удерживается только в этом процессе."""

    _удерживаемые = []

    def __init__(сам, путь):
        if not isinstance(путь, Path) or not путь.is_absolute() or '..' in путь.parts:
            raise ОшибкаОтчёта('неверный путь владельца возобновления')
        сам.путь = Path(os.path.abspath(os.fspath(путь)))
        сам.состояние = 'готов'
        сам.ошибка = None
        сам.первичная = None
        сам.ошибка_тела = None
        сам.тело_начато = False
        сам.известный_отказ = None
        сам.ошибка_удаления_снимка = None
        сам.ошибка_удаления_журнала = None
        сам.восстановление_журнала = None
        сам.операции = []
        сам.эффект_начат = False
        сам._родитель = None
        сам._метка_родителя = None
        сам._процесс, сам._поток = os.getpid(), threading.current_thread()

    def _проверить_поток(сам):
        if os.getpid() != сам._процесс or threading.current_thread() is not сам._поток:
            raise ОшибкаОтчёта('владелец возобновления принадлежит другому потоку или процессу')

    def __enter__(сам):
        сам._проверить_поток()
        if сам.состояние != 'готов':
            raise ОшибкаОтчёта('повтор владельца возобновления')
        сам._удерживаемые.append(сам)
        сам.состояние = 'подготовка'
        try:
            до = сам.путь.parent.lstat()
            if not stat.S_ISDIR(до.st_mode):
                raise ОшибкаОтчёта('родитель отчёта не является каталогом')
            сам.операции.append({'этап': 'открытие родителя', 'состояние': 'начато'})
            дескриптор = os.open(сам.путь.parent,
                os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
            сам._родитель = дескриптор
            сам.операции[-1]['состояние'] = 'подтверждено'
            открытый = os.fstat(дескриптор)
            сам._метка_родителя = (открытый.st_dev, открытый.st_ino, открытый.st_mode,
                                   открытый.st_uid, открытый.st_gid)
            if (до.st_dev, до.st_ino, до.st_mode, до.st_uid, до.st_gid) != сам._метка_родителя:
                raise ОшибкаОтчёта('родитель отчёта изменился при открытии')
            сам.состояние = 'активен'
            return сам
        except BaseException as ошибка:
            сам.состояние = 'неизвестно'
            сам.ошибка = ошибка
            raise

    def сверить(сам):
        сам._проверить_поток()
        if сам.состояние != 'активен' or сам._родитель is None:
            raise ОшибкаОтчёта('владелец возобновления недоступен')
        открытый, по_пути = os.fstat(сам._родитель), сам.путь.parent.lstat()
        for сведения in (открытый, по_пути):
            if (not stat.S_ISDIR(сведения.st_mode)
                or (сведения.st_dev, сведения.st_ino, сведения.st_mode, сведения.st_uid, сведения.st_gid)
                   != сам._метка_родителя):
                raise ОшибкаОтчёта('родитель отчёта изменился во время возобновления')

    def выполнить(сам, этап, операция, *аргументы, **ключи):
        сам.сверить()
        запись = {'этап': этап, 'состояние': 'начато'}
        сам.операции.append(запись)
        сам.эффект_начат = True
        результат = операция(*аргументы, **ключи)
        запись['состояние'] = 'подтверждено'
        return результат

    @contextlib.contextmanager
    def граница_тела(сам):
        сам.тело_начато = True
        try:
            yield
        except BaseException as ошибка:
            сам.ошибка_тела = ошибка
            raise

    def __exit__(сам, тип, первичная, трассировка):
        сам.первичная = первичная
        try:
            сам._проверить_поток()
        except BaseException as ошибка:
            сам.состояние = 'неизвестно'
            сам.ошибка = ошибка
            raise
        истёк_до_тела = (not сам.тело_начато and type(первичная) is ОшибкаОтчёта
                         and getattr(первичная, '_признак_истечения_замка', None)
                             is _ПРИЗНАК_ИСТЕЧЕНИЯ_ЗАМКА
                         and not getattr(первичная, '__notes__', ()))
        известен = (истёк_до_тела or (первичная is not None and первичная is сам.ошибка_тела
                    and (первичная is сам.известный_отказ
                         or (not сам.эффект_начат and type(первичная) is ОшибкаОтчёта
                             and первичная.__cause__ is None))))
        if первичная is not None and not известен:
            сам.состояние = 'неизвестно'
            сам.ошибка = первичная
            return False
        try:
            сам.операции.append({'этап': 'закрытие родителя', 'состояние': 'начато'})
            os.close(сам._родитель)
            сам._родитель = None
            сам.операции[-1]['состояние'] = 'подтверждено'
        except BaseException as закрытие:
            сам.состояние = 'неизвестно'
            сам.ошибка = закрытие
            if первичная is None:
                raise
            if not isinstance(первичная, Exception):
                raise первичная from закрытие
            if not isinstance(закрытие, Exception):
                raise закрытие from первичная
            raise ExceptionGroup('отказ и неизвестное закрытие владельца', [первичная, закрытие]) from None
        сам.состояние = 'отказ известен' if известен else 'подтверждено'
        сам.ошибка = первичная
        сам._удерживаемые.remove(сам)
        return False


def _проверить_подтверждённую_замену_отчёта(путь_отчёта, *, _владелец_возобновления=None):
    """Проверяет реестр текущего процесса; он не заменяет межпроцессный замок."""
    нормальный_путь = Path(os.path.abspath(os.fspath(путь_отчёта)))
    if _владелец_возобновления is not None:
        if type(_владелец_возобновления) is not _ВладелецВозобновления:
            raise ОшибкаОтчёта('неверный владелец возобновления')
        _владелец_возобновления.сверить()
        if _владелец_возобновления.путь != нормальный_путь:
            raise ОшибкаОтчёта('владелец возобновления относится к другому отчёту')
    неизвестные = [владелец for владелец in _ВладелецЗаменыПредпросмотра._удерживаемые
                   if владелец.состояние not in ('подтверждено', 'отказ до эффекта', 'отказ после снимка', 'отказ после журнала')]
    неизвестные.extend(владелец for владелец in _ВладелецВозобновления._удерживаемые
                       if владелец is not _владелец_возобновления
                       and владелец.состояние not in ('подтверждено', 'отказ известен'))
    if any(владелец.путь == нормальный_путь for владелец in неизвестные):
        raise ОшибкаОтчёта('предыдущий исход предпросмотра не подтверждён')
    сопоставимые = [владелец for владелец in неизвестные
                     if владелец.путь.name == нормальный_путь.name and владелец._метка_родителя is not None]
    if сопоставимые:
        try:
            родитель = os.stat(нормальный_путь.parent, follow_symlinks=False)
        except OSError as ошибка:
            raise ОшибкаОтчёта('не удалось сверить родителя с неизвестной заменой') from ошибка
        if (not stat.S_ISDIR(родитель.st_mode)
            or any(владелец._метка_родителя[:2] == (родитель.st_dev, родитель.st_ino)
                   for владелец in сопоставимые)):
            raise ОшибкаОтчёта('предыдущий исход предпросмотра не подтверждён')


def заменить_управляемый_блок(путь_отчёта: Path, новый_блок: str, *, перед_публикацией=None,
                               ожидаемые_байты=None, _сохранить_права=False, _каталоги=None,
                               _после_подготовки=None, _подтвердить_метаданные=False,
                               _владелец_возобновления=None) -> None:
    if перед_публикацией is not None and not callable(перед_публикацией):
        raise ОшибкаОтчёта('неверная проверка перед публикацией отчёта')
    if ожидаемые_байты is not None and type(ожидаемые_байты) is not bytes:
        raise ОшибкаОтчёта('неверные ожидаемые байты отчёта')
    if type(_сохранить_права) is not bool:
        raise ОшибкаОтчёта('неверный признак сохранения прав отчёта')
    if (type(_подтвердить_метаданные) is not bool or
        (_подтвердить_метаданные and (not _сохранить_права or ожидаемые_байты is None
                                      or перед_публикацией is None or _после_подготовки is not None))):
        raise ОшибкаОтчёта('неверное подтверждение метаданных открытого отчёта')
    if (_после_подготовки is not None
        and (not callable(_после_подготовки) or not _сохранить_права or перед_публикацией is None)):
        raise ОшибкаОтчёта('неверное действие после подготовки отчёта')
    if _владелец_возобновления is not None and not _сохранить_права:
        raise ОшибкаОтчёта('владелец возобновления требует сохранения метаданных')
    if _каталоги is not None:
        if not _сохранить_права or type(_каталоги) is not _ЗакреплённыеКаталогиПредпросмотра:
            raise ОшибкаОтчёта('неверные закреплённые каталоги предпросмотра')
        _каталоги._проверить_владельца()
    if _сохранить_права:
        _проверить_подтверждённую_замену_отчёта(
            путь_отчёта, _владелец_возобновления=_владелец_возобновления)
        владелец = _ВладелецЗаменыПредпросмотра(
            путь_отчёта, новый_блок, ожидаемые_байты, перед_публикацией, _каталоги, _после_подготовки,
            _подтвердить_метаданные)
        владелец.выполнить()
        return
    try:
        if _сохранить_права:
            исходные_байты, метка_отчёта = _снять_отчёт_без_ссылок(путь_отчёта)
        else:
            исходные_байты = путь_отчёта.read_bytes()
            метка_отчёта = None
    except OSError as ошибка:
        raise ОшибкаОтчёта(f'не удалось прочитать отчёт: {ошибка}') from ошибка
    if ожидаемые_байты is not None and исходные_байты != ожидаемые_байты:
        raise ОшибкаОтчёта('отчёт изменился до формирования замены')
    новые_байты = заменить_управляемый_блок_в_байтах(исходные_байты, новый_блок)
    if новые_байты != исходные_байты:
        if _сохранить_права:
            _атомарно_сохранить_отчёт_с_правами(
                путь_отчёта, новые_байты, исходные_байты, метка_отчёта,
                перед_публикацией=перед_публикацией)
        elif перед_публикацией is None:
            атомарно_записать_байты(путь_отчёта, новые_байты)
        else:
            raise ОшибкаОтчёта('проверка публикации требует сохранения прав')
    elif перед_публикацией is not None:
        перед_публикацией()



def ожидаемый_снимок(
    записи: Sequence[tuple[Path, dict[str, object], bytes]],
    сессия: str,
    отпечаток_закрытия: str | None = None,
) -> dict[str, object]:
    запретить_понижение_схемы_раундов(записи)
    есть_профилированные = any(
        запись.get("схема") == СХЕМА_ПРОФИЛИРОВАННОГО_ЗАПУСКА
        for _, запись, _ in записи
    )
    if есть_профилированные and (
        not isinstance(отпечаток_закрытия, str)
        or re.fullmatch(r"sha256:[0-9a-f]{64}", отпечаток_закрытия) is None
    ):
        raise ОшибкаОтчёта("v3-снимок требует отпечаток закрытия")
    if not есть_профилированные and отпечаток_закрытия is not None:
        raise ОшибкаОтчёта("исторический снимок не содержит отпечаток закрытия")
    снимок: dict[str, object] = {
        "схема": (
            СХЕМА_СНИМКА_С_ВЕРДИКТОМ
            if есть_профилированные
            else СХЕМА_СНИМКА
        ),
        "сессия": сессия,
        "файлы": [
            {"имя": путь.name, "sha256": хэш_содержимого(байты)}
            for путь, _, байты in записи
        ],
    }
    if есть_профилированные:
        снимок["отпечаток_закрытия"] = отпечаток_закрытия
    return снимок


def проверить_снимок(
    путь_снимка: Path,
    записи: Sequence[tuple[Path, dict[str, object], bytes]],
    сессия: str,
) -> tuple[bytes, str | None]:
    значение, байты = прочитать_машинную_запись(путь_снимка)
    if not isinstance(значение, dict):
        raise ОшибкаОтчёта("снимок содержит неверный набор полей")
    схема = значение.get("схема")
    if схема == СХЕМА_СНИМКА:
        ожидаемые_поля = ПОЛЯ_СНИМКА
        отпечаток_закрытия = None
    elif схема == СХЕМА_СНИМКА_С_ВЕРДИКТОМ:
        ожидаемые_поля = ПОЛЯ_СНИМКА_С_ВЕРДИКТОМ
        отпечаток_закрытия = значение.get("отпечаток_закрытия")
        if not isinstance(отпечаток_закрытия, str) or re.fullmatch(
            r"sha256:[0-9a-f]{64}", отпечаток_закрытия
        ) is None:
            raise ОшибкаОтчёта("снимок содержит неверный отпечаток закрытия")
    else:
        raise ОшибкаОтчёта("снимок имеет неверную схему или сессию")
    if set(значение) != ожидаемые_поля:
        raise ОшибкаОтчёта("снимок содержит неверный набор полей")
    if значение["сессия"] != сессия:
        raise ОшибкаОтчёта("снимок имеет неверную схему или сессию")
    файлы = значение["файлы"]
    if not isinstance(файлы, list) or any(
        not isinstance(описание, dict)
        or set(описание) != ПОЛЯ_ФАЙЛА_СНИМКА
        or not isinstance(описание["имя"], str)
        or not isinstance(описание["sha256"], str)
        or re.fullmatch(r"[0-9a-f]{64}", описание["sha256"]) is None
        for описание in файлы
    ):
        raise ОшибкаОтчёта("снимок содержит неверный список файлов")
    if значение != ожидаемый_снимок(
        записи,
        сессия,
        отпечаток_закрытия,
    ):
        raise ОшибкаОтчёта("снимок не совпадает с фактическими записями")
    if байты != канонические_машинные_байты(значение):
        raise ОшибкаОтчёта("снимок имеет неканонические байты")
    return байты, отпечаток_закрытия


def проверить_закрытое_состояние(
    путь_отчёта: Path,
    путь_снимка: Path,
    записи: Sequence[tuple[Path, dict[str, object], bytes]],
    сессия: str,
    *, _отчёт_без_ссылок: bool = False,
) -> None:
    if any(запись["состояние"] == "выполняется" for _, запись, _ in записи):
        raise ОшибкаОтчёта("закрытый снимок содержит выполняющуюся запись")
    байты_снимка, отпечаток_закрытия, содержимое_закрытия = проверить_снимок_истории(
        путь_снимка,
        записи,
        сессия,
    )
    маркер = сформировать_закрытый_маркер(байты_снимка)
    текст = (_снять_отчёт_без_ссылок(путь_отчёта)[0]
             if _отчёт_без_ссылок else путь_отчёта.read_bytes()).decode("utf-8")
    начало, конец, фактический_маркер = границы_управляемого_блока(текст)
    if фактический_маркер != маркер:
        raise ОшибкаОтчёта("marker отчёта не совпадает с хэшем снимка")
    ожидаемый_блок = сформировать_блок_истории(
        записи,
        маркер,
        отпечаток_закрытия,
        содержимое_закрытия,
    )
    if текст[начало:конец] != ожидаемый_блок:
        raise ОшибкаОтчёта("Markdown-блок не совпадает с машинным снимком")


def сформировать_закрытый_маркер(байты_снимка: bytes) -> str:
    return (
        "<!-- FUM-CHECK-RUNS:BEGIN состояние=закрыт; "
        "снимок=материалы/запуски-проверок/снимок.json; "
        f"sha256=sha256:{хэш_содержимого(байты_снимка)} -->"
    )


def ожидаемый_журнал_возобновления(
    сессия: str,
    байты_снимка: bytes,
    закрытые_байты_отчёта: bytes,
    открытые_байты_отчёта: bytes,
    отпечаток_закрытия: str | None = None,
) -> dict[str, str]:
    значение = {
        "схема": (
            СХЕМА_ЖУРНАЛА_ВОЗОБНОВЛЕНИЯ_С_ВЕРДИКТОМ
            if отпечаток_закрытия is not None
            else СХЕМА_ЖУРНАЛА_ВОЗОБНОВЛЕНИЯ
        ),
        "сессия": сессия,
        "хэш_закрытого_отчёта": хэш_содержимого(закрытые_байты_отчёта),
        "хэш_открытого_отчёта": хэш_содержимого(открытые_байты_отчёта),
        "хэш_снимка": хэш_содержимого(байты_снимка),
    }
    if отпечаток_закрытия is not None:
        значение["отпечаток_закрытия"] = отпечаток_закрытия
    return значение


def проверить_журнал_возобновления(
    путь_журнала: Path,
    путь_отчёта: Path,
    путь_снимка: Path,
    записи: Sequence[tuple[Path, dict[str, object], bytes]],
    сессия: str,
) -> tuple[bytes, bytes, bytes, str, bytes, str | None]:
    if any(запись["состояние"] == "выполняется" for _, запись, _ in записи):
        raise ОшибкаОтчёта(
            "журнал возобновления не допускает выполняющуюся запись"
        )
    значение, байты_журнала = прочитать_машинную_запись(путь_журнала)
    if not isinstance(значение, dict):
        raise ОшибкаОтчёта("журнал возобновления содержит неверный набор полей")
    схема = значение.get("схема")
    if схема == СХЕМА_ЖУРНАЛА_ВОЗОБНОВЛЕНИЯ:
        ожидаемые_поля = ПОЛЯ_ЖУРНАЛА_ВОЗОБНОВЛЕНИЯ
        отпечаток_закрытия = None
    elif схема == СХЕМА_ЖУРНАЛА_ВОЗОБНОВЛЕНИЯ_С_ВЕРДИКТОМ:
        ожидаемые_поля = ПОЛЯ_ЖУРНАЛА_ВОЗОБНОВЛЕНИЯ_С_ВЕРДИКТОМ
        отпечаток_закрытия = значение.get("отпечаток_закрытия")
        if not isinstance(отпечаток_закрытия, str) or re.fullmatch(
            r"sha256:[0-9a-f]{64}", отпечаток_закрытия
        ) is None:
            raise ОшибкаОтчёта(
                "журнал возобновления содержит неверный отпечаток закрытия"
            )
    else:
        raise ОшибкаОтчёта("журнал возобновления имеет неверную схему")
    if set(значение) != ожидаемые_поля:
        raise ОшибкаОтчёта("журнал возобновления содержит неверный набор полей")
    if значение["сессия"] != сессия:
        raise ОшибкаОтчёта("журнал возобновления принадлежит другой сессии")
    поля_хэшей = (
        "хэш_закрытого_отчёта",
        "хэш_открытого_отчёта",
        "хэш_снимка",
    )
    if any(
        not isinstance(значение[поле], str)
        or re.fullmatch(r"[0-9a-f]{64}", значение[поле]) is None
        for поле in поля_хэшей
    ):
        raise ОшибкаОтчёта("журнал возобновления содержит неверный хэш")
    if байты_журнала != канонические_машинные_байты(значение):
        raise ОшибкаОтчёта("журнал возобновления имеет неканонические байты")

    байты_снимка = канонические_машинные_байты(
        ожидаемый_снимок(записи, сессия, отпечаток_закрытия)
    )
    текущие_байты_отчёта = _снять_отчёт_без_ссылок(путь_отчёта)[0]
    закрытые_байты_отчёта = заменить_управляемый_блок_в_байтах(
        текущие_байты_отчёта,
        сформировать_блок(
            записи,
            сформировать_закрытый_маркер(байты_снимка),
            отпечаток_закрытия,
        ),
    )
    открытые_байты_отчёта = заменить_управляемый_блок_в_байтах(
        текущие_байты_отчёта,
        сформировать_блок(
            записи,
            ОТКРЫТЫЙ_МАРКЕР,
            отпечаток_закрытия,
        ),
    )
    ожидаемое_значение = ожидаемый_журнал_возобновления(
        сессия,
        байты_снимка,
        закрытые_байты_отчёта,
        открытые_байты_отчёта,
        отпечаток_закрытия,
    )
    if значение != ожидаемое_значение:
        raise ОшибкаОтчёта(
            "хэши журнала возобновления не совпадают с текущей сессией"
        )
    if текущие_байты_отчёта == закрытые_байты_отчёта:
        состояние_отчёта = "закрыт"
    elif текущие_байты_отчёта == открытые_байты_отчёта:
        состояние_отчёта = "открыт"
    else:
        raise ОшибкаОтчёта(
            "отчёт не совпадает ни с одной фазой журнала возобновления"
        )

    снимок_существует = путь_снимка.exists() or путь_снимка.is_symlink()
    if снимок_существует:
        фактические_байты_снимка, фактический_отпечаток_закрытия = проверить_снимок(
            путь_снимка,
            записи,
            сессия,
        )
        if (
            фактические_байты_снимка != байты_снимка
            or фактический_отпечаток_закрытия != отпечаток_закрытия
        ):
            raise ОшибкаОтчёта(
                "снимок не совпадает с журналом возобновления"
            )
    elif состояние_отчёта != "открыт":
        raise ОшибкаОтчёта(
            "закрытая фаза журнала возобновления потеряла снимок"
        )
    return (
        закрытые_байты_отчёта,
        открытые_байты_отчёта,
        байты_снимка,
        состояние_отчёта,
        байты_журнала,
        отпечаток_закрытия,
    )


def проверить_журнал_сессии(
    корень_репозитория: str | Path,
    запрос: str | Path,
    *, контрольная_точка: bool = False,
    идентификатор_активного_запуска: str | None = None,
) -> list[str]:
    try:
        (
            корень,
            _,
            путь_отчёта,
            каталог,
            сессия,
        ) = разрешить_сессию(корень_репозитория, запрос)
        if контрольная_точка:
            _запретить_историю_с_неизвестным_git_профилем(прочитать_историю_проверок(каталог, сессия))
        with межпроцессная_блокировка(корень, сессия):
            запретить_действие_при_возобновлении(каталог, "проверка")
            записи = прочитать_историю_проверок(каталог, сессия)
            if контрольная_точка:
                _запретить_историю_с_неизвестным_git_профилем(записи)
            путь_снимка = каталог / ИМЯ_СНИМКА
            текст = путь_отчёта.read_bytes().decode("utf-8")
            _, _, маркер = границы_управляемого_блока(текст)
            if контрольная_точка:
                if путь_снимка.exists() or путь_снимка.is_symlink():
                    raise ОшибкаОтчёта("контрольная точка требует открытый журнал без снимка")
                if маркер != ОТКРЫТЫЙ_МАРКЕР:
                    raise ОшибкаОтчёта("контрольная точка требует точный открытый marker")
                активные = [
                    запись
                    for _, запись, _ in записи
                    if запись["состояние"] == "выполняется"
                ]
                if активные and (
                    len(активные) != 1
                    or идентификатор_активного_запуска is None
                    or активные[0]["идентификатор"]
                    != идентификатор_активного_запуска
                ):
                    raise ОшибкаОтчёта(
                        "контрольная точка допускает только одну собственную активную запись"
                    )
                терминальные_записи = [
                    элемент
                    for элемент in записи
                    if элемент[1]["состояние"] != "выполняется"
                ]
                текущий_отпечаток, текущее_содержимое = текущий_контекст_проверок(
                    корень, сессия, терминальные_записи
                )
                начало, конец, _ = границы_управляемого_блока(текст)
                if текст[начало:конец] != сформировать_блок_истории(
                    терминальные_записи,
                    ОТКРЫТЫЙ_МАРКЕР,
                    текущий_отпечаток,
                    текущее_содержимое,
                ):
                    raise ОшибкаОтчёта("контрольная точка требует точный предпросмотр записей")
                return []
            if путь_снимка.exists():
                проверить_закрытое_состояние(
                    путь_отчёта,
                    путь_снимка,
                    записи,
                    сессия,
                )
            else:
                if маркер != ОТКРЫТЫЙ_МАРКЕР:
                    raise ОшибкаОтчёта(
                        "открытый журнал имеет закрытый marker без снимка"
                    )
                if not any(
                    запись["состояние"] == "выполняется"
                    for _, запись, _ in записи
                ):
                    raise ОшибкаОтчёта(
                        "открытый журнал допустим только при выполняющейся записи"
                    )
    except (ОшибкаОтчёта, OSError, UnicodeError) as ошибка:
        return [str(ошибка)]
    return []


def выполнить_предпросмотр(корень_репозитория: Path, запрос: Path) -> int:
    корень, _, путь_отчёта, каталог, сессия = разрешить_сессию(
        корень_репозитория,
        запрос,
    )
    with contextlib.ExitStack() as удержания:
        каталоги = удержания.enter_context(
            _ЗакреплённыеКаталогиПредпросмотра(путь_отчёта, каталог, сессия))
        _запретить_историю_с_неизвестным_git_профилем(каталоги.история())
        try:
            сейчас = time.monotonic()
            if type(сейчас) not in (int, float) or not math.isfinite(сейчас):
                raise ValueError('недостоверные часы')
            срок = сейчас + 5.0
            if not math.isfinite(срок) or срок <= сейчас:
                raise ValueError('непредставимый срок')
        except (OSError, OverflowError, TypeError, ValueError) as причина:
            raise ОшибкаОтчёта('не удалось определить срок замка предпросмотра') from причина
        сверить_замок = удержания.enter_context(
            межпроцессная_блокировка(корень, сессия, срок_монотонный=срок))
        if not callable(сверить_замок):
            raise ОшибкаОтчёта('нет проверки замка предпросмотра')
        каталоги.проверить_открытую_сессию()
        исходные_байты, исходная_метка = каталоги.отчёт()
        текст = исходные_байты.decode('utf-8')
        _, _, маркер = границы_управляемого_блока(текст)
        if маркер != ОТКРЫТЫЙ_МАРКЕР:
            raise ОшибкаОтчёта(
                "предпросмотр запрещён для закрытого marker без снимка"
            )
        # Для формирования отчёта используется история, прочитанная под lock;
        # первое чтение до lock служит только предварительному допуску.
        записи = каталоги.история()
        _запретить_историю_с_неизвестным_git_профилем(записи)
        исходная_история = tuple((путь, байты) for путь, _, байты in записи)
        текущий_отпечаток, текущее_содержимое = None, None
        def проверить_публикацию():
            сверить_замок()
            каталоги.проверить_открытую_сессию()
            история = каталоги.история()
            if tuple((путь, байты) for путь, _, байты in история) != исходная_история:
                raise ОшибкаОтчёта('история проверок изменилась во время предпросмотра')
            if каталоги.отчёт() != (исходные_байты, исходная_метка):
                raise ОшибкаОтчёта('отчёт изменился во время предпросмотра')
            каталоги.проверить_открытую_сессию()
            сверить_замок()
        заменить_управляемый_блок(
            путь_отчёта,
            сформировать_блок_истории(
                записи,
                ОТКРЫТЫЙ_МАРКЕР,
                текущий_отпечаток,
                текущее_содержимое,
            ),
            перед_публикацией=проверить_публикацию,
            ожидаемые_байты=исходные_байты,
            _сохранить_права=True,
            _каталоги=каталоги,
        )
    return 0


def выполнить_проверку_плана(корень_репозитория: Path, запрос: Path) -> int:
    корень, _, путь_отчёта, каталог, сессия = разрешить_сессию(
        корень_репозитория,
        запрос,
    )
    _запретить_историю_с_неизвестным_git_профилем(прочитать_историю_проверок(каталог, сессия))
    with межпроцессная_блокировка(корень, сессия):
        запретить_действие_при_возобновлении(каталог, "проверка плана")
        путь_снимка = каталог / ИМЯ_СНИМКА
        if путь_снимка.exists() or путь_снимка.is_symlink():
            raise ОшибкаОтчёта("проверить план можно только в открытой сессии")
        текст = путь_отчёта.read_bytes().decode("utf-8")
        _, _, маркер = границы_управляемого_блока(текст)
        if маркер != ОТКРЫТЫЙ_МАРКЕР:
            raise ОшибкаОтчёта("проверить план можно только в открытой сессии")
        записи = прочитать_историю_проверок(каталог, сессия)
        _запретить_историю_с_неизвестным_git_профилем(записи)
        текущий_отпечаток, текущее_содержимое = текущий_контекст_проверок(корень, сессия, записи)
        if есть_раунды(записи):
            план = построить_план_раундов(записи, текущий_отпечаток, текущее_содержимое)
            if план["состояние"] != "готов":
                нарушения = ", ".join(имя for имя, выполнено in план["доказанные_условия"].items() if not выполнено)
                raise ОшибкаОтчёта(f"план приёмочных раундов не готов: {нарушения}")
        else:
            if not any(профиль_записи(запись) is not None for _, запись, _ in записи):
                raise ОшибкаОтчёта("машинный журнал не содержит v3-профилей")
            проверить_порядок_проверок(записи, текущий_отпечаток)
    print("экономный план проверок подтверждён")
    return 0


def выполнить_закрытие(корень_репозитория: Path, запрос: Path) -> int:
    корень, _, путь_отчёта, каталог, сессия = разрешить_сессию(
        корень_репозитория,
        запрос,
    )
    _проверить_подтверждённую_замену_отчёта(путь_отчёта)
    _запретить_историю_с_неизвестным_git_профилем(прочитать_историю_проверок(каталог, сессия))
    with межпроцессная_блокировка(корень, сессия) as сверить_замок:
        запретить_действие_при_возобновлении(каталог, "закрытие")
        записи = прочитать_историю_проверок(каталог, сессия)
        _запретить_историю_с_неизвестным_git_профилем(записи)
        путь_снимка = каталог / ИМЯ_СНИМКА
        if путь_снимка.exists():
            if any(
                запись["состояние"] == "выполняется"
                for _, запись, _ in записи
            ):
                raise ОшибкаОтчёта(
                    "подготовленный снимок содержит выполняющуюся запись"
                )
            байты_снимка, отпечаток_закрытия, содержимое_закрытия = проверить_снимок_истории(
                путь_снимка,
                записи,
                сессия,
            )
            закреплённый_снимок, метка_снимка = _снять_отчёт_без_ссылок(путь_снимка)
            if закреплённый_снимок != байты_снимка:
                raise ОшибкаОтчёта('подготовленный снимок изменился до закрытия')
            ожидаемый_маркер = сформировать_закрытый_маркер(байты_снимка)
            исходный_отчёт, метка_отчёта = _снять_отчёт_без_ссылок(путь_отчёта)
            текст = исходный_отчёт.decode("utf-8")
            проверить_отчёт = _проверка_отчёта_под_замком(
                путь_отчёта, исходный_отчёт, метка_отчёта, сверить_замок)
            def проверить_отчёт_и_снимок():
                проверить_отчёт()
                _снять_отчёт_без_ссылок(
                    путь_снимка, ожидаемые=байты_снимка, ожидаемая_метка=метка_снимка)
                сверить_замок()
            _, _, фактический_маркер = границы_управляемого_блока(текст)
            if фактический_маркер == ОТКРЫТЫЙ_МАРКЕР:
                заменить_управляемый_блок(
                    путь_отчёта,
                    сформировать_блок_истории(
                        записи,
                        ожидаемый_маркер,
                        отпечаток_закрытия,
                        содержимое_закрытия,
                    ),
                    перед_публикацией=проверить_отчёт_и_снимок,
                    ожидаемые_байты=исходный_отчёт,
                    _сохранить_права=True,
                )
            elif фактический_маркер != ожидаемый_маркер:
                raise ОшибкаОтчёта(
                    "закрытый marker не совпадает с подготовленным снимком"
                )
            проверить_закрытое_состояние(
                путь_отчёта,
                путь_снимка,
                записи,
                сессия,
                _отчёт_без_ссылок=True,
            )
            сверить_замок()
            return 0
        if any(запись["состояние"] == "выполняется" for _, запись, _ in записи):
            raise ОшибкаОтчёта("нельзя закрыть журнал с выполняющейся записью")
        отпечаток_закрытия, содержимое_закрытия = текущий_контекст_проверок(корень, сессия, записи)
        снимок = (
            ожидаемый_снимок_раундов(записи, сессия, отпечаток_закрытия, содержимое_закрытия)
            if есть_раунды(записи)
            else ожидаемый_снимок(записи, сессия, отпечаток_закрытия)
        )
        байты_снимка = канонические_машинные_байты(снимок)
        маркер = сформировать_закрытый_маркер(байты_снимка)
        блок = сформировать_блок_истории(записи, маркер, отпечаток_закрытия, содержимое_закрытия)
        исходный_отчёт, метка_отчёта = _снять_отчёт_без_ссылок(путь_отчёта)
        проверить_отчёт = _проверка_отчёта_под_замком(
            путь_отчёта, исходный_отчёт, метка_отчёта, сверить_замок)
        заменить_управляемый_блок_в_байтах(исходный_отчёт, блок)
        подтверждённый_снимок = [None]
        def проверить_контекст_закрытия():
            метка = подтверждённый_снимок[0]
            if метка is None:
                проверить_отчёт()
                try:
                    путь_снимка.lstat()
                except FileNotFoundError:
                    pass
                else:
                    raise ОшибкаОтчёта('снимок появился до подготовки закрытия')
            else:
                сверить_замок()
                сведения = путь_отчёта.lstat()
                текущая_метка = (сведения.st_dev, сведения.st_ino, сведения.st_mode,
                                 сведения.st_uid, сведения.st_gid, сведения.st_nlink,
                                 сведения.st_size, сведения.st_mtime_ns, сведения.st_ctime_ns)
                if текущая_метка != метка_отчёта:
                    _снять_отчёт_без_ссылок(
                        путь_снимка, ожидаемые=байты_снимка, ожидаемая_метка=метка)
                    сверить_замок()
                    raise _ПодтверждённыйОтказПослеСнимка('отчёт изменился после подготовки снимка')
                _снять_отчёт_без_ссылок(
                    путь_отчёта, ожидаемые=исходный_отчёт, ожидаемая_метка=метка_отчёта)
                _снять_отчёт_без_ссылок(
                    путь_снимка, ожидаемые=байты_снимка, ожидаемая_метка=метка)
            сверить_замок()
        публикация_снимка = _ОднократнаяЗаписьСнимкаЗакрытия(
            путь_снимка, байты_снимка, проверить_контекст_закрытия)
        def записать_подготовленный_снимок():
            публикация_снимка.выполнить()
            данные, метка = _снять_отчёт_без_ссылок(путь_снимка)
            if данные != байты_снимка:
                raise ОшибкаОтчёта('записанный снимок не подтверждён')
            подтверждённый_снимок[0] = метка
        заменить_управляемый_блок(
            путь_отчёта,
            блок,
            перед_публикацией=проверить_контекст_закрытия,
            ожидаемые_байты=исходный_отчёт,
            _сохранить_права=True,
            _после_подготовки=записать_подготовленный_снимок,
        )
        проверить_закрытое_состояние(
            путь_отчёта,
            путь_снимка,
            записи,
            сессия,
            _отчёт_без_ссылок=True,
        )
        сверить_замок()
    return 0


def выполнить_возобновление(корень_репозитория: Path, запрос: Path) -> int:
    корень, _, путь_отчёта, каталог, сессия = разрешить_сессию(
        корень_репозитория,
        запрос,
    )
    _проверить_подтверждённую_замену_отчёта(путь_отчёта)
    _запретить_историю_с_неизвестным_git_профилем(прочитать_записи(каталог, сессия))
    замок = межпроцессная_блокировка(корень, сессия)
    владелец = _ВладелецВозобновления(путь_отчёта)
    with владелец, замок as сверить_замок, владелец.граница_тела():
        записи = прочитать_записи(каталог, сессия)
        _запретить_историю_с_неизвестным_git_профилем(записи)
        путь_снимка = каталог / ИМЯ_СНИМКА
        путь_журнала = каталог / ИМЯ_ЖУРНАЛА_ВОЗОБНОВЛЕНИЯ
        каталог_мета = каталог.lstat()
        if not stat.S_ISDIR(каталог_мета.st_mode):
            raise ОшибкаОтчёта('каталог возобновления не является каталогом')
        ожидаемый_каталог = (каталог_мета.st_dev, каталог_мета.st_ino, каталог_мета.st_mode,
                             каталог_мета.st_uid, каталог_мета.st_gid)
        def проверить_каталог():
            try:
                текущий = каталог.lstat()
            except OSError as ошибка:
                raise ОшибкаОтчёта('каталог возобновления недоступен') from ошибка
            if (текущий.st_dev, текущий.st_ino, текущий.st_mode,
                текущий.st_uid, текущий.st_gid) != ожидаемый_каталог:
                raise ОшибкаОтчёта('каталог возобновления изменился')
        исходный_отчёт, исходная_метка = _снять_отчёт_без_ссылок(путь_отчёта)
        проверить_исходный_отчёт = _проверка_отчёта_под_замком(
            путь_отчёта, исходный_отчёт, исходная_метка, сверить_замок)
        закреплённый_снимок = (_снять_отчёт_без_ссылок(путь_снимка)
                               if путь_снимка.exists() or путь_снимка.is_symlink() else None)
        журнал_был = журнал_возобновления_существует(каталог)
        if журнал_был:
            (
                закрытые_байты_отчёта,
                открытые_байты_отчёта,
                байты_снимка,
                состояние_отчёта,
                байты_журнала,
                отпечаток_закрытия,
            ) = проверить_журнал_возобновления(
                путь_журнала,
                путь_отчёта,
                путь_снимка,
                записи,
                сессия,
            )
            ожидаемый_исходный = (закрытые_байты_отчёта if состояние_отчёта == 'закрыт'
                                  else открытые_байты_отчёта)
            if исходный_отчёт != ожидаемый_исходный:
                raise ОшибкаОтчёта('отчёт изменился при подготовке возобновления')
        else:
            if not путь_снимка.exists():
                raise ОшибкаОтчёта("возобновить можно только закрытый снимок")
            проверить_закрытое_состояние(
                путь_отчёта,
                путь_снимка,
                записи,
                сессия,
                _отчёт_без_ссылок=True,
            )
            байты_снимка, отпечаток_закрытия = проверить_снимок(
                путь_снимка,
                записи,
                сессия,
            )
            if any(
                запись.get("схема") == СХЕМА_ЗАПУСКА_С_НАБЛЮДЕНИЯМИ
                for _, запись, _ in записи
            ):
                raise ОшибкаОтчёта(
                    "исторический снимок v2 нельзя возобновить в контуре v3"
                )
            if (
                отпечаток_закрытия is not None
                and построить_план_успешной_сессии(
                    записи,
                    отпечаток_закрытия,
                )["состояние"]
                == "готов"
            ):
                raise ОшибкаОтчёта(
                    "готовый профилированный снимок нельзя возобновить"
                )
            закрытые_байты_отчёта = исходный_отчёт
            открытые_байты_отчёта = заменить_управляемый_блок_в_байтах(
                закрытые_байты_отчёта,
                сформировать_блок(
                    записи,
                    ОТКРЫТЫЙ_МАРКЕР,
                    отпечаток_закрытия,
                ),
            )
            значение_журнала = ожидаемый_журнал_возобновления(
                сессия,
                байты_снимка,
                закрытые_байты_отчёта,
                открытые_байты_отчёта,
                отпечаток_закрытия,
            )
            байты_журнала = канонические_машинные_байты(значение_журнала)
            состояние_отчёта = "закрыт"

        if закреплённый_снимок is not None and закреплённый_снимок[0] != байты_снимка:
            raise ОшибкаОтчёта('снимок изменился при подготовке возобновления')
        закреплённый_журнал = [_снять_отчёт_без_ссылок(путь_журнала) if журнал_был else None]
        if закреплённый_журнал[0] is not None and закреплённый_журнал[0][0] != байты_журнала:
            raise ОшибкаОтчёта('журнал изменился при подготовке возобновления')

        def проверить_машинные_опоры():
            проверить_каталог()
            if закреплённый_снимок is None:
                try:
                    путь_снимка.lstat()
                except FileNotFoundError:
                    pass
                else:
                    raise ОшибкаОтчёта('снимок появился при возобновлении')
            else:
                _снять_отчёт_без_ссылок(
                    путь_снимка, ожидаемые=закреплённый_снимок[0],
                    ожидаемая_метка=закреплённый_снимок[1])
            if закреплённый_журнал[0] is None:
                try:
                    путь_журнала.lstat()
                except FileNotFoundError:
                    pass
                else:
                    raise ОшибкаОтчёта('журнал появился до подготовки возобновления')
            else:
                _снять_отчёт_без_ссылок(
                    путь_журнала, ожидаемые=закреплённый_журнал[0][0],
                    ожидаемая_метка=закреплённый_журнал[0][1])
            проверить_каталог()

        def проверить_контекст_возобновления():
            владелец.сверить()
            сверить_замок()
            проверить_машинные_опоры()
            if закреплённый_журнал[0] is not None:
                сведения = путь_отчёта.lstat()
                текущая_метка = (сведения.st_dev, сведения.st_ino, сведения.st_mode,
                                 сведения.st_uid, сведения.st_gid, сведения.st_nlink,
                                 сведения.st_size, сведения.st_mtime_ns, сведения.st_ctime_ns)
                if текущая_метка != исходная_метка:
                    проверить_машинные_опоры()
                    сверить_замок()
                    raise _ПодтверждённыйОтказПослеЖурнала(
                        'отчёт изменился после подготовки журнала возобновления')
            проверить_исходный_отчёт()
            проверить_машинные_опоры()
            сверить_замок()

        публикация_журнала = None
        if not журнал_был:
            публикация_журнала = _ОднократнаяЗаписьМашинногоФайла(
                путь_журнала, байты_журнала, проверить_контекст_возобновления, _журнал=True)

        def подготовить_журнал():
            if публикация_журнала is not None:
                владелец.выполнить('публикация журнала', публикация_журнала.выполнить)
                данные, метка = _снять_отчёт_без_ссылок(путь_журнала)
                if данные != байты_журнала:
                    raise ОшибкаОтчёта('записанный журнал не подтверждён')
                закреплённый_журнал[0] = (данные, метка)

        до_замены = tuple(_ВладелецЗаменыПредпросмотра._удерживаемые)
        try:
            if состояние_отчёта == "закрыт":
                владелец.выполнить('открытие отчёта', заменить_управляемый_блок,
                    путь_отчёта,
                    сформировать_блок(
                        записи,
                        ОТКРЫТЫЙ_МАРКЕР,
                        отпечаток_закрытия,
                    ),
                    перед_публикацией=проверить_контекст_возобновления,
                    ожидаемые_байты=исходный_отчёт,
                    _сохранить_права=True,
                    _после_подготовки=подготовить_журнал,
                    _владелец_возобновления=владелец,
                )
            else:
                владелец.выполнить('подтверждение открытого отчёта', заменить_управляемый_блок,
                    путь_отчёта, сформировать_блок(записи, ОТКРЫТЫЙ_МАРКЕР, отпечаток_закрытия),
                    перед_публикацией=проверить_контекст_возобновления,
                    ожидаемые_байты=исходный_отчёт, _сохранить_права=True,
                    _подтвердить_метаданные=True, _владелец_возобновления=владелец)
        except _ИзвестныйОтказПредпросмотра as ошибка:
            новые = [элемент for элемент in _ВладелецЗаменыПредпросмотра._удерживаемые
                     if all(элемент is not старый for старый in до_замены)]
            if (len(новые) == 1 and новые[0].ошибка is ошибка
                and новые[0].состояние in ('отказ до эффекта', 'отказ после журнала')):
                владелец.известный_отказ = ошибка
            raise

        if закреплённый_журнал[0] is None:
            raise ОшибкаОтчёта('журнал возобновления не подтверждён')
        закреплённый_журнал = закреплённый_журнал[0]

        текущий_отчёт, текущая_метка = _снять_отчёт_без_ссылок(путь_отчёта)
        if текущий_отчёт != открытые_байты_отчёта:
            raise ОшибкаОтчёта(
                "открытый отчёт не совпадает с журналом возобновления"
            )
        проверить_открытый_отчёт = _проверка_отчёта_под_замком(
            путь_отчёта, текущий_отчёт, текущая_метка, сверить_замок)
        if путь_снимка.exists() or путь_снимка.is_symlink():
            if закреплённый_снимок is None:
                raise ОшибкаОтчёта('снимок появился во время возобновления')
            проверить_открытый_отчёт()
            известный_отказ_снимка = None
            try:
                with _удержать_файл_перед_удалением(
                    путь_снимка, *закреплённый_снимок, сверить_замок,
                    ожидаемый_каталог=ожидаемый_каталог,
                ) as (каталог_fd, сверить_снимок):
                    проверить_открытый_отчёт()
                    сверить_снимок()
                    try:
                        владелец.выполнить('удаление снимка', os.unlink, путь_снимка.name, dir_fd=каталог_fd)
                    except OSError as отказ:
                        владелец.ошибка_удаления_снимка = отказ
                        try:
                            сверить_снимок()
                            _снять_отчёт_без_ссылок(
                                путь_журнала, ожидаемые=закреплённый_журнал[0],
                                ожидаемая_метка=закреплённый_журнал[1])
                            проверить_открытый_отчёт()
                            владелец.сверить()
                            сверить_замок()
                        except BaseException as сбой:
                            if not isinstance(сбой, Exception):
                                raise сбой from отказ
                            raise BaseExceptionGroup('отказ удаления и неизвестная сверка снимка',
                                                     [отказ, сбой]) from None
                        владелец.операции[-1]['состояние'] = 'отказ подтверждён'
                        известный_отказ_снимка = отказ
                    else:
                        владелец.выполнить('синхронизация удаления снимка', os.fsync, каталог_fd)
                        try:
                            os.stat(путь_снимка.name, dir_fd=каталог_fd, follow_symlinks=False)
                        except FileNotFoundError:
                            pass
                        else:
                            raise ОшибкаОтчёта('снимок появился после удаления')
            except OSError as ошибка:
                raise ОшибкаОтчёта(
                    "не удалось удалить снимок; состояние журнала возобновления "
                    f"требует проверки: {ошибка}"
                ) from ошибка
            if известный_отказ_снимка is not None:
                отказ = ОшибкаОтчёта('снимок и журнал подтверждены после отказа удаления')
                владелец.известный_отказ = отказ
                raise отказ from известный_отказ_снимка
        elif закреплённый_снимок is not None:
            raise ОшибкаОтчёта('снимок исчез во время возобновления')
        if путь_снимка.exists() or путь_снимка.is_symlink():
            raise ОшибкаОтчёта(
                "снимок остался после подтверждения фазы возобновления"
            )

        проверить_открытый_отчёт()
        известный_отказ_журнала = None
        try:
            with _удержать_файл_перед_удалением(
                путь_журнала, *закреплённый_журнал, сверить_замок,
                ожидаемый_каталог=ожидаемый_каталог,
            ) as (каталог_fd, сверить_журнал):
                def журнал_в_каталоге():
                    try:
                        os.stat(путь_журнала.name, dir_fd=каталог_fd, follow_symlinks=False)
                    except FileNotFoundError:
                        return False
                    return True
                попытка_удаления = False
                удаление_вернуло_успех = False
                попытка_синхронизации = False
                синхронизация_вернула_успех = False
                try:
                    try:
                        os.stat(путь_снимка.name, dir_fd=каталог_fd, follow_symlinks=False)
                    except FileNotFoundError:
                        pass
                    else:
                        raise ОшибкаОтчёта('снимок появился во время возобновления')
                    if закреплённый_снимок is None:
                        владелец.выполнить('синхронизация отсутствующего снимка', os.fsync, каталог_fd)
                    проверить_открытый_отчёт()
                    сверить_журнал()
                    попытка_удаления = True
                    владелец.выполнить('удаление журнала', os.unlink, путь_журнала.name, dir_fd=каталог_fd)
                    удаление_вернуло_успех = True
                    def синхронизировать_удаление():
                        nonlocal попытка_синхронизации, синхронизация_вернула_успех
                        попытка_синхронизации = True
                        результат = os.fsync(каталог_fd)
                        синхронизация_вернула_успех = True
                        return результат
                    владелец.выполнить('синхронизация удаления журнала', синхронизировать_удаление)
                    if журнал_в_каталоге():
                        raise ОшибкаОтчёта('журнал появился после удаления')
                    try:
                        os.stat(путь_снимка.name, dir_fd=каталог_fd, follow_symlinks=False)
                    except FileNotFoundError:
                        pass
                    else:
                        raise ОшибкаОтчёта('снимок появился после удаления журнала; исход неизвестен')
                except OSError as ошибка:
                    владелец.ошибка_удаления_журнала = ошибка
                    if not попытка_удаления:
                        raise ОшибкаОтчёта('сбой до попытки удаления журнала; исход требует проверки') from ошибка
                    if удаление_вернуло_успех and (
                        not попытка_синхронизации or синхронизация_вернула_успех
                    ):
                        raise ОшибкаОтчёта('ошибка вне фазы синхронизации удаления журнала; исход неизвестен') from ошибка
                    try:
                        проверить_каталог()
                        проверить_открытый_отчёт()
                        def проверить_отсутствие_снимка():
                            сверить_замок()
                            проверить_каталог()
                            try:
                                os.stat(путь_снимка.name, dir_fd=каталог_fd, follow_symlinks=False)
                            except FileNotFoundError:
                                pass
                            else:
                                raise ОшибкаОтчёта('снимок появился при проверке журнала')
                            сверить_замок()
                        проверить_отсутствие_снимка()
                        if not удаление_вернуло_успех:
                            сверить_журнал()
                            владелец.операции[-1]['состояние'] = 'отказ подтверждён'
                        else:
                            if журнал_в_каталоге():
                                raise ОшибкаОтчёта('журнал неожиданно появился после удаления')
                            def проверить_перед_восстановлением():
                                проверить_каталог()
                                проверить_открытый_отчёт()
                                проверить_отсутствие_снимка()
                                if журнал_в_каталоге():
                                    raise ОшибкаОтчёта('журнал появился до восстановления')
                                проверить_каталог()
                            восстановление = _ОднократнаяЗаписьМашинногоФайла(
                                путь_журнала, байты_журнала, проверить_перед_восстановлением,
                                _журнал=True, _опора_каталога=каталог_fd)
                            владелец.восстановление_журнала = восстановление
                            владелец.выполнить('восстановление журнала', восстановление.выполнить)
                            опубликованный = os.stat(путь_журнала.name, dir_fd=каталог_fd,
                                                     follow_symlinks=False)
                            данные, метка_журнала = _снять_отчёт_без_ссылок(путь_журнала)
                            if (not stat.S_ISREG(опубликованный.st_mode) or опубликованный.st_nlink != 1
                                or (опубликованный.st_dev, опубликованный.st_ino) != восстановление.метка_файла
                                or метка_журнала[:2] != восстановление.метка_файла or данные != байты_журнала):
                                raise ОшибкаОтчёта('восстановленный журнал не подтверждён')
                        проверить_отсутствие_снимка()
                        проверить_открытый_отчёт()
                        владелец.сверить()
                        сверить_замок()
                        проверить_каталог()
                        if удаление_вернуло_успех:
                            после = os.stat(путь_журнала.name, dir_fd=каталог_fd, follow_symlinks=False)
                            повторная_метка = (после.st_dev, после.st_ino, после.st_mode,
                                после.st_uid, после.st_gid, после.st_nlink, после.st_size,
                                после.st_mtime_ns, после.st_ctime_ns)
                            if повторная_метка != метка_журнала:
                                raise ОшибкаОтчёта('восстановленный журнал изменился после проверки')
                    except BaseException as сбой:
                        if not isinstance(сбой, Exception):
                            raise сбой from ошибка
                        причины = BaseExceptionGroup(
                            'ошибки удаления и проверки или восстановления журнала', [ошибка, сбой])
                        raise ОшибкаОтчёта(
                            'неизвестен исход удаления и восстановления журнала возобновления'
                        ) from причины
                    известный_отказ_журнала = ошибка
        except OSError as ошибка:
            raise ОшибкаОтчёта('не удалось удержать журнал возобновления') from ошибка
        if известный_отказ_журнала is not None:
            отказ = ОшибкаОтчёта('открытый отчёт и журнал подтверждены после отказа удаления')
            владелец.известный_отказ = отказ
            raise отказ from известный_отказ_журнала
        проверить_открытый_отчёт()
    return 0


def группа_процессов_существует(идентификатор_группы: int) -> bool:
    try:
        os.killpg(идентификатор_группы, 0)
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    return True


def дождаться_исчезновения_группы(
    процесс: subprocess.Popen[bytes],
    идентификатор_группы: int,
    предел_секунд: float,
) -> bool:
    предел = time.monotonic() + предел_секунд
    while True:
        процесс.poll()
        if not группа_процессов_существует(идентификатор_группы):
            return True
        остаток = предел - time.monotonic()
        if остаток <= 0:
            return False
        time.sleep(min(ИНТЕРВАЛ_ПРОВЕРКИ_ГРУППЫ, остаток))


def остановить_группу(
    процесс: subprocess.Popen[bytes],
    идентификатор_группы: int,
) -> bool:
    применено_принудительное_завершение = False
    if идентификатор_группы <= 0:
        raise ОшибкаОтчёта("неверный идентификатор дочерней группы процессов")
    try:
        os.killpg(идентификатор_группы, signal.SIGTERM)
    except ProcessLookupError:
        pass
    except PermissionError as ошибка:
        raise ОшибкаОтчёта(
            "не удалось отправить SIGTERM дочерней группе процессов"
        ) from ошибка
    if not дождаться_исчезновения_группы(
        процесс,
        идентификатор_группы,
        ПАУЗА_ПЕРЕД_ПРИНУДИТЕЛЬНОЙ_ОСТАНОВКОЙ,
    ):
        try:
            os.killpg(идентификатор_группы, signal.SIGKILL)
        except ProcessLookupError:
            pass
        except PermissionError as ошибка:
            raise ОшибкаОтчёта(
                "не удалось отправить SIGKILL дочерней группе процессов"
            ) from ошибка
        else:
            применено_принудительное_завершение = True
    try:
        процесс.wait(timeout=ПРЕДЕЛ_ПОДТВЕРЖДЕНИЯ_ОСТАНОВКИ_ГРУППЫ)
    except subprocess.TimeoutExpired as ошибка:
        raise ОшибкаОтчёта(
            "лидер дочерней группы не завершился в отведённый срок"
        ) from ошибка
    if not дождаться_исчезновения_группы(
        процесс,
        идентификатор_группы,
        ПРЕДЕЛ_ПОДТВЕРЖДЕНИЯ_ОСТАНОВКИ_ГРУППЫ,
    ):
        raise ОшибкаОтчёта(
            "дочерняя группа процессов не исчезла в отведённый срок"
        )
    return применено_принудительное_завершение


def имя_сигнала(номер: int) -> str:
    try:
        return signal.Signals(номер).name
    except ValueError:
        return f"сигнал {номер}"


def проверить_ссылку_диагностики_на_отказ(
    профиль: dict[str, object],
    записи: Sequence[tuple[Path, dict[str, object], bytes]],
) -> None:
    if профиль["класс"] != "диагностическая" or профиль[
        "основание"
    ] != "локализация_наблюдаемого_отказа":
        return
    идентификатор = профиль["идентификатор_отказа"]
    совпадения = [
        запись
        for _, запись, _ in записи
        if запись.get("идентификатор") == идентификатор
    ]
    if len(совпадения) != 1:
        raise ОшибкаОтчёта("диагностика ссылается на отсутствующий отказ")
    отказ = совпадения[0]
    профиль_отказа = профиль_записи(отказ)
    if (
        отказ.get("состояние") != "завершён"
        or отказ.get("статус") != "неуспешно"
        or профиль_отказа is None
        or профиль_отказа["отпечаток_снимка"]
        != профиль["отпечаток_снимка"]
    ):
        raise ОшибкаОтчёта("диагностика требует предшествующий отказ на том же снимке")



def проверить_допуск_запуска_раундов(
    профиль: dict[str, object], содержимое: str,
    записи: Sequence[tuple[Path, dict[str, object], bytes]],
) -> None:
    проверить_отпечаток_раундов(содержимое, "содержимое нового запуска")
    новые = [запись for _, запись, _ in записи if запись["схема"] == СХЕМА_ЗАПУСКА_С_РАУНДАМИ]
    if профиль["класс"] == "полная" and any(
        запись["профиль_проверки"]["класс"] == "полная"
        and запись["отпечаток_содержимого"] == содержимое
        for запись in новые
    ):
        raise ОшибкаОтчёта("полная попытка на этом содержимом уже учтена")
    if профиль["класс"] == "полная" and any(
        запись["переход_схемы"] is not None and запись["отпечаток_содержимого"] == содержимое
        for запись in новые
    ):
        raise ОшибкаОтчёта("полная попытка требует изменения содержимого после границы перехода")
    if профиль["основание"] == "локализация_наблюдаемого_отказа":
        отказ = next((запись for запись in новые if запись["идентификатор"] == профиль["идентификатор_отказа"]), None)
        if not (
            отказ is not None
            and отказ["состояние"] == "завершён"
            and отказ["статус"] == "неуспешно"
            and отказ["профиль_проверки"]["отпечаток_снимка"] == профиль["отпечаток_снимка"]
            and отказ["отпечаток_содержимого"] == содержимое
        ):
            raise ОшибкаОтчёта("локализация раунда требует предшествующий отказ на обоих отпечатках")


_ПРИЧИНА_ЗАКРЫТОГО_ЗАПУСКА = "запуск проверок закрыт до восстановления ограниченной среды"


def выполнить_запуск(
    корень_репозитория: Path,
    запрос: Path,
    название: str,
    исполнитель: str,
    идентификатор_запуска: str | None,
    тайм_аут: float | None,
    команда: Sequence[str],
    класс_проверки: str | None = None,
    полные_наборы: Sequence[str] = (),
    основание: str | None = None,
    идентификатор_отказа: str | None = None,
    ожидаемое_свидетельство: str | None = None,
    приёмочные_раунды: bool = False,
    исходный_коммит_раундов: str | None = None,
    *,
    требовать_выбор_первой_схемы: bool = False,
    обычная_схема_профиля: bool = False,
) -> int:
    raise ОшибкаОтчёта(_ПРИЧИНА_ЗАКРЫТОГО_ЗАПУСКА)
    if type(требовать_выбор_первой_схемы) is not bool or type(обычная_схема_профиля) is not bool:
        raise ОшибкаОтчёта("выбор первой схемы требует логические параметры")
    корень, _, путь_отчёта, каталог, сессия = разрешить_сессию(
        корень_репозитория,
        запрос,
    )
    проверить_строку(название, "название")
    проверить_строку(исполнитель, "исполнитель")
    if not команда:
        raise ОшибкаОтчёта("после -- должна быть указана команда")
    if any(not isinstance(аргумент, str) or "\0" in аргумент for аргумент in команда):
        raise ОшибкаОтчёта("команда содержит недопустимый аргумент")
    if тайм_аут is not None and (
        not math.isfinite(тайм_аут) or тайм_аут <= 0
    ):
        raise ОшибкаОтчёта("тайм-аут должен быть положительным числом")
    идентификатор = проверить_идентификатор(
        идентификатор_запуска or str(uuid.uuid4())
    )
    запуск_полной_проверки = является_запуском_полной_проверки(корень, команда)
    if класс_проверки is None:
        raise ОшибкаОтчёта("каждый новый запуск требует --класс-проверки")
    if (класс_проверки == "полная") != запуск_полной_проверки:
        raise ОшибкаОтчёта("класс «полная» допустим только для exact run-smoke-check")
    if класс_проверки == "полная" and ожидаемое_свидетельство is not None:
        raise ОшибкаОтчёта("подтверждение полной проверки нельзя задавать аргументом")
    заготовка_профиля: dict[str, object] = {
        "класс": класс_проверки,
        "отпечаток_снимка": "sha256:" + "0" * 64,
        "полные_наборы": list(полные_наборы),
        "основание": основание,
        "идентификатор_отказа": идентификатор_отказа,
        "ожидаемое_свидетельство": ожидаемое_свидетельство,
    }
    проверить_профиль_проверки(
        заготовка_профиля, None, [], "выполняется"
    )
    временный_каталог_наблюдений: tempfile.TemporaryDirectory[str] | None = None
    путь_наблюдений: Path | None = None
    if запуск_полной_проверки:
        временный_каталог_наблюдений = tempfile.TemporaryDirectory(
            prefix="fum-smoke-observations-"
        )
        путь_наблюдений = (
            Path(временный_каталог_наблюдений.name) / "наблюдения.json"
        )
    управляемые_сигналы = {signal.SIGINT, signal.SIGTERM}
    есть_потоковая_маска = hasattr(signal, "pthread_sigmask")
    прежняя_маска: set[signal.Signals] | None = None
    if есть_потоковая_маска:
        прежняя_маска = signal.pthread_sigmask(
            signal.SIG_BLOCK,
            управляемые_сигналы,
        )
    полученный_сигнал: int | None = None
    учтённые_ожидающие_сигналы: set[signal.Signals] = set()
    идёт_очистка = False

    def принять_сигнал(номер_сигнала: int, _кадр: object) -> None:
        nonlocal полученный_сигнал
        if полученный_сигнал is None:
            полученный_сигнал = номер_сигнала
        if not идёт_очистка:
            raise ПрерываниеОбёртки(номер_сигнала)

    прежние_обработчики: dict[int, object] = {}

    def восстановить_рабочую_маску() -> None:
        if прежняя_маска is not None:
            signal.pthread_sigmask(signal.SIG_SETMASK, прежняя_маска)

    def восстановить_маску_дочернего_процесса() -> None:
        if прежняя_маска is not None:
            signal.pthread_sigmask(signal.SIG_SETMASK, прежняя_маска)

    def заблокировать_управляемые_сигналы() -> None:
        if есть_потоковая_маска:
            signal.pthread_sigmask(signal.SIG_BLOCK, управляемые_сигналы)

    def определить_отложенный_сигнал() -> int | None:
        nonlocal полученный_сигнал
        if есть_потоковая_маска and hasattr(signal, "sigpending"):
            ожидающие = set(signal.sigpending()) & управляемые_сигналы
            учтённые_ожидающие_сигналы.update(ожидающие)
            if ожидающие and полученный_сигнал is None:
                полученный_сигнал = int(min(ожидающие, key=int))
        return полученный_сигнал

    def поглотить_учтённые_сигналы() -> None:
        if not (
            есть_потоковая_маска
            and hasattr(signal, "sigpending")
            and hasattr(signal, "sigwait")
        ):
            return
        ожидающие = (
            set(signal.sigpending())
            & учтённые_ожидающие_сигналы
        )
        for номер_сигнала in sorted(ожидающие, key=int):
            signal.sigwait({номер_сигнала})

    try:
        if путь_наблюдений is not None:
            атомарно_записать_байты(
                путь_наблюдений,
                канонические_машинные_байты(
                    начальный_конверт_наблюдений(идентификатор)
                ),
            )
        for номер_сигнала in управляемые_сигналы:
            прежние_обработчики[номер_сигнала] = signal.getsignal(номер_сигнала)
            signal.signal(номер_сигнала, принять_сигнал)

        with межпроцессная_блокировка(корень, сессия):
            каталог.mkdir(parents=True, exist_ok=True)
            if каталог.is_symlink() or not каталог.is_dir():
                raise ОшибкаОтчёта("каталог запусков имеет неверный тип")
            запретить_действие_при_возобновлении(каталог, "новый запуск")
            if (каталог / ИМЯ_СНИМКА).exists():
                raise ОшибкаОтчёта(
                    "после подготовки или закрытия снимка новые запуски запрещены"
                )
            текст_отчёта = путь_отчёта.read_bytes().decode("utf-8")
            _, _, маркер_отчёта = границы_управляемого_блока(текст_отчёта)
            if маркер_отчёта != ОТКРЫТЫЙ_МАРКЕР:
                raise ОшибкаОтчёта(
                    "новый запуск запрещён для закрытого marker без снимка"
                )
            существующие: list[tuple[Path, dict[str, object], bytes]] = []
            if any(каталог.iterdir()):
                существующие = прочитать_историю_проверок(каталог, сессия)
            if обычная_схема_профиля and (
                приёмочные_раунды or исходный_коммит_раундов is not None or есть_раунды(существующие)
            ):
                raise ОшибкаОтчёта("обычная схема несовместима с приёмочными раундами")
            if not существующие and требовать_выбор_первой_схемы and not (
                обычная_схема_профиля or приёмочные_раунды or исходный_коммит_раундов is not None
            ):
                raise ОшибкаОтчёта(
                    "первый командный запуск требует --приёмочные-раунды или --обычная-схема-профиля"
                )
            использовать_раунды = приёмочные_раунды or исходный_коммит_раундов is not None or есть_раунды(существующие)
            if not использовать_раунды and история_схем_несовместима(
                [запись for _, запись, _ in существующие]
            ):
                raise ОшибкаОтчёта(
                    "новый запуск запрещён после исторической записи в v3-хвосте"
                )
            if any(
                запись.get("схема") == СХЕМА_ЗАПУСКА_С_НАБЛЮДЕНИЯМИ
                for _, запись, _ in существующие
            ):
                raise ОшибкаОтчёта(
                    "историческую v2-сессию нельзя смешивать с новым v3-контуром"
                )
            выполняющиеся = [
                запись
                for _, запись, _ in существующие
                if запись.get("состояние") == "выполняется"
            ]
            if any(
                ((запись.get("профиль_проверки") if использовать_раунды else профиль_записи(запись)) or {}).get("класс") == "полная"
                for запись in выполняющиеся
            ):
                raise ОшибкаОтчёта(
                    "новый запуск запрещён, пока выполняется финальная полная проверка"
                )
            if запуск_полной_проверки and выполняющиеся:
                raise ОшибкаОтчёта(
                    "финальная полная проверка запрещена при выполняющейся записи"
                )
            if идентификатор in {
                str(запись["идентификатор"])
                for _, запись, _ in существующие
            }:
                raise ОшибкаОтчёта("UUID запуска уже существует")
            порядок = max(
                (int(запись["порядок"]) for _, запись, _ in существующие),
                default=0,
            ) + 1
            путь_записи = каталог / f"{порядок}_{идентификатор}.json"
            профиль_проверки = dict(заготовка_профиля)
            профиль_проверки["отпечаток_снимка"] = (
                вычислить_отпечаток_снимка(корень, Path(сессия).parent)
            )
            переход_раундов = None
            отпечаток_содержимого = None
            if использовать_раунды:
                if есть_раунды(существующие):
                    if исходный_коммит_раундов is not None:
                        raise ОшибкаОтчёта("граница перехода уже сохранена")
                elif существующие:
                    if исходный_коммит_раундов is None:
                        raise ОшибкаОтчёта("переход старой истории требует исходный commit")
                    if профиль_проверки["класс"] != "адресная":
                        raise ОшибкаОтчёта("первый переход фиксируется только адресной проверкой")
                    переход_раундов = подготовить_переход_раундов(корень, существующие, исходный_коммит_раундов)
                elif исходный_коммит_раундов is not None:
                    raise ОшибкаОтчёта("пустая история не принимает исходный commit перехода")
                отпечаток_содержимого = вычислить_отпечаток_содержимого(корень, Path(сессия).parent)
                проверить_допуск_запуска_раундов(профиль_проверки, отпечаток_содержимого, существующие)
            else:
                проверить_ссылку_диагностики_на_отказ(профиль_проверки, существующие)
            активная_запись: dict[str, object] = {
                "схема": СХЕМА_ЗАПУСКА_С_РАУНДАМИ if использовать_раунды else СХЕМА_ПРОФИЛИРОВАННОГО_ЗАПУСКА,
                "идентификатор": идентификатор,
                "сессия": сессия,
                "порядок": порядок,
                "исполнитель": исполнитель,
                "вызов": название,
                "состояние": "выполняется",
                "длительность_наносекунды": None,
                "статус": None,
                "код_завершения": None,
                "пояснение": None,
            }
            активная_запись["план"] = None
            активная_запись["наблюдения"] = []
            активная_запись["профиль_проверки"] = профиль_проверки
            if использовать_раунды:
                активная_запись["отпечаток_содержимого"] = отпечаток_содержимого
                активная_запись["переход_схемы"] = переход_раундов
                проверить_историю_раундов([*существующие, (путь_записи, активная_запись, канонические_машинные_байты(активная_запись))])
            проверить_запись(активная_запись, путь_записи.name, сессия)
            атомарно_записать_байты(
                путь_записи,
                канонические_машинные_байты(активная_запись),
            )

        начало = time.monotonic_ns()
        процесс: subprocess.Popen[bytes] | None = None
        идентификатор_группы: int | None = None
        процесс_запущен = False
        статус: str
        код: int
        пояснение: str | None = None
        возвращаемый_код: int
        try:
            try:
                try:
                    окружение = подготовить_ограниченную_среду_проверки(
                        идентификатор, путь_наблюдений,
                        неполная_проекция=является_неполной_проверкой_проекции(корень, команда),
                    )
                    фактическая_команда = list(команда)
                    процесс = subprocess.Popen(
                        фактическая_команда,
                        cwd=корень,
                        env=окружение,
                        stdin=subprocess.DEVNULL,
                        start_new_session=True,
                        preexec_fn=(
                            восстановить_маску_дочернего_процесса
                            if есть_потоковая_маска
                            else None
                        ),
                    )
                    идентификатор_группы = процесс.pid
                    процесс_запущен = True
                finally:
                    восстановить_рабочую_маску()
                код = процесс.wait(timeout=тайм_аут)
                if код == 0:
                    статус = "успешно"
                    возвращаемый_код = 0
                elif код > 0:
                    статус = "неуспешно"
                    возвращаемый_код = код
                else:
                    статус = "прервано"
                    пояснение = имя_сигнала(-код)
                    возвращаемый_код = 128 + (-код)
            except subprocess.TimeoutExpired:
                идёт_очистка = True
                if процесс is not None and идентификатор_группы is not None:
                    применено_принудительное_завершение = остановить_группу(
                        процесс,
                        идентификатор_группы,
                    )
                else:
                    применено_принудительное_завершение = False
                if полученный_сигнал is not None:
                    код = -полученный_сигнал
                    статус = "прервано"
                    пояснение = имя_сигнала(полученный_сигнал)
                    возвращаемый_код = 128 + полученный_сигнал
                else:
                    статус = "не завершено"
                    код = КОД_ТАЙМ_АУТА
                    пояснение = "тайм-аут"
                    if применено_принудительное_завершение:
                        пояснение += "; применён SIGKILL"
                    возвращаемый_код = КОД_ТАЙМ_АУТА
            except FileNotFoundError:
                код = КОД_ОТСУТСТВУЮЩЕЙ_КОМАНДЫ
                статус = "не завершено"
                пояснение = "исполняемый файл не найден"
                возвращаемый_код = КОД_ОТСУТСТВУЮЩЕЙ_КОМАНДЫ
            except PermissionError:
                код = КОД_ОШИБКИ_ДОСТУПА
                статус = "не завершено"
                пояснение = "исполняемый файл недоступен"
                возвращаемый_код = КОД_ОШИБКИ_ДОСТУПА
            except OSError:
                код = КОД_ОШИБКИ_ОБЁРТКИ
                статус = "не завершено"
                пояснение = "системная ошибка запуска"
                возвращаемый_код = КОД_ОШИБКИ_ОБЁРТКИ
            идёт_очистка = True
        except ПрерываниеОбёртки as прерывание:
            идёт_очистка = True
            if процесс is not None and идентификатор_группы is not None:
                остановить_группу(процесс, идентификатор_группы)
            номер_сигнала = полученный_сигнал or прерывание.номер_сигнала
            код = -номер_сигнала
            статус = "прервано"
            пояснение = имя_сигнала(номер_сигнала)
            возвращаемый_код = 128 + номер_сигнала
        finally:
            идёт_очистка = True
            заблокировать_управляемые_сигналы()

        конец = time.monotonic_ns()
        длительность_запуска = max(0, конец - начало)
        план: list[dict[str, str]] | None = None
        наблюдения: list[dict[str, object]] = []
        текущая_проверка: dict[str, object] | None = None
        ошибка_наблюдений: ОшибкаОтчёта | None = None
        if путь_наблюдений is not None:
            try:
                (план, наблюдения, текущая_проверка) = прочитать_конверт_наблюдений(
                    путь_наблюдений,
                    идентификатор,
                )
            except ОшибкаОтчёта as ошибка:
                ошибка_наблюдений = ошибка
        try:
            with межпроцессная_блокировка(корень, сессия):
                if использовать_раунды:
                    текущая_история = прочитать_историю_проверок(каталог, сессия)
                    текущие_байты = {путь.name: байты for путь, _, байты in текущая_история}
                    if any(
                        запись["состояние"] == "завершён" and текущие_байты.get(путь.name) != байты
                        for путь, запись, байты in существующие
                    ):
                        raise ОшибкаОтчёта("прежняя терминальная запись изменилась во время запуска")
                значение, _ = прочитать_машинную_запись(путь_записи)
                if значение != активная_запись:
                    raise ОшибкаОтчёта("активная запись была изменена до завершения")
                if (каталог / ИМЯ_СНИМКА).exists():
                    raise ОшибкаОтчёта("снимок появился до терминальной записи")
                номер_итогового_сигнала = определить_отложенный_сигнал()
                if номер_итогового_сигнала is not None:
                    код = -номер_итогового_сигнала
                    статус = "прервано"
                    пояснение = имя_сигнала(номер_итогового_сигнала)
                    возвращаемый_код = 128 + номер_итогового_сигнала
                if запуск_полной_проверки and ошибка_наблюдений is None:
                    try:
                        if текущая_проверка is not None:
                            начало_текущей = int(
                                текущая_проверка[
                                    "начало_монотонные_наносекунды"
                                ]
                            )
                            if not начало <= начало_текущей <= конец:
                                raise ОшибкаОтчёта(
                                    "начало текущей проверки smoke-check "
                                    "вне интервала внешнего запуска"
                                )
                            if статус == "успешно":
                                raise ОшибкаОтчёта(
                                    "успешный smoke-check оставил текущую проверку"
                                )
                            наблюдения.append(
                                {
                                    "ключ_проверки": текущая_проверка["ключ_проверки"],
                                    "название": текущая_проверка["название"],
                                    "статус": (
                                        "прервано"
                                        if статус == "прервано"
                                        else "не завершено"
                                    ),
                                    "длительность_наносекунды": конец - начало_текущей,
                                }
                            )
                        проверить_согласованность_наблюдений(
                            план,
                            наблюдения,
                            статус,
                            длительность_запуска,
                        )
                    except ОшибкаОтчёта as ошибка:
                        ошибка_наблюдений = ошибка
                if ошибка_наблюдений is not None:
                    план = None
                    наблюдения = []
                    if статус == "прервано":
                        пояснение = (
                            f"{пояснение}; наблюдения отброшены: "
                            f"{ошибка_наблюдений}"
                        )
                    elif процесс_запущен:
                        код = КОД_ОШИБКИ_ОБЁРТКИ
                        статус = "не завершено"
                        пояснение = (
                            "неверные наблюдения smoke-check: "
                            f"{ошибка_наблюдений}"
                        )
                        возвращаемый_код = КОД_ОШИБКИ_ОБЁРТКИ
                завершённая_запись = dict(активная_запись)
                завершённая_запись.update(
                    {
                        "состояние": "завершён",
                        "длительность_наносекунды": длительность_запуска,
                        "статус": статус,
                        "код_завершения": код,
                        "пояснение": пояснение,
                    }
                )
                if запуск_полной_проверки:
                    завершённая_запись["план"] = план
                    завершённая_запись["наблюдения"] = наблюдения
                if профиль_проверки is not None and профиль_проверки["класс"] == "полная":
                    завершённый_профиль = dict(профиль_проверки)
                    завершённый_профиль["полные_наборы"] = (
                        [элемент["ключ_проверки"] for элемент in план]
                        if план is not None
                        else []
                    )
                    завершённая_запись["профиль_проверки"] = завершённый_профиль
                проверить_запись(
                    завершённая_запись,
                    путь_записи.name,
                    сессия,
                )
                атомарно_записать_байты(
                    путь_записи,
                    канонические_машинные_байты(завершённая_запись),
                )
                поглотить_учтённые_сигналы()
        except ОшибкаОтчёта as ошибка:
            print(str(ошибка), file=sys.stderr)
            return КОД_ОШИБКИ_ОБЁРТКИ
        return возвращаемый_код
    finally:
        заблокировать_управляемые_сигналы()
        for номер_сигнала, прежний in прежние_обработчики.items():
            signal.signal(номер_сигнала, прежний)
        восстановить_рабочую_маску()
        if временный_каталог_наблюдений is not None:
            временный_каталог_наблюдений.cleanup()


def положительное_число(значение: str) -> float:
    try:
        число = float(значение)
    except ValueError as ошибка:
        raise argparse.ArgumentTypeError("ожидается число") from ошибка
    if not math.isfinite(число) or число <= 0:
        raise argparse.ArgumentTypeError("ожидается положительное конечное число")
    return число


def добавить_общие_аргументы(разбор: argparse.ArgumentParser) -> None:
    разбор.add_argument("--корень-репозитория", type=Path, required=True)
    разбор.add_argument("--запрос", type=Path, required=True)


def построить_разбор_аргументов() -> argparse.ArgumentParser:
    разбор = argparse.ArgumentParser(description=__doc__, allow_abbrev=False)
    команды = разбор.add_subparsers(dest="подкоманда", required=True)
    for имя in ("предпросмотр", "проверить-план", "закрыть", "возобновить", "проверить"):
        подкоманда = команды.add_parser(имя, allow_abbrev=False)
        добавить_общие_аргументы(подкоманда)
    запуск = команды.add_parser("запустить", allow_abbrev=False)
    добавить_общие_аргументы(запуск)
    запуск.add_argument("--название", required=True)
    запуск.add_argument("--исполнитель", required=True)
    запуск.add_argument("--идентификатор-запуска")
    запуск.add_argument("--тайм-аут-секунды", type=положительное_число)
    запуск.add_argument(
        "--класс-проверки",
        choices=sorted(КЛАССЫ_ПРОВЕРОК),
        required=True,
    )
    запуск.add_argument("--полный-набор", action="append", default=[])
    запуск.add_argument("--основание", choices=sorted(ОСНОВАНИЯ_ДИАГНОСТИКИ))
    запуск.add_argument("--идентификатор-отказа")
    запуск.add_argument("--ожидаемое-свидетельство")
    выбор_схемы = запуск.add_mutually_exclusive_group()
    выбор_схемы.add_argument("--приёмочные-раунды", action="store_true")
    выбор_схемы.add_argument("--обычная-схема-профиля", action="store_true")
    запуск.add_argument("--исходный-коммит-раундов")
    запуск.add_argument("аргументы_команды", nargs=argparse.REMAINDER)
    return разбор


def главная(аргументы: Sequence[str] | None = None) -> int:
    аргументы = sys.argv[1:] if аргументы is None else аргументы
    if next((слово for слово in аргументы if слово != "--"), None) == "запустить":
        print(_ПРИЧИНА_ЗАКРЫТОГО_ЗАПУСКА, file=sys.stderr)
        return 1
    пространство = построить_разбор_аргументов().parse_args(аргументы)
    try:
        if пространство.подкоманда == "запустить":
            команда = list(пространство.аргументы_команды)
            if not команда or команда[0] != "--":
                raise ОшибкаОтчёта("команда должна быть указана после --")
            команда = команда[1:]
            return выполнить_запуск(
                пространство.корень_репозитория,
                пространство.запрос,
                пространство.название,
                пространство.исполнитель,
                пространство.идентификатор_запуска,
                пространство.тайм_аут_секунды,
                команда,
                пространство.класс_проверки,
                пространство.полный_набор,
                пространство.основание,
                пространство.идентификатор_отказа,
                пространство.ожидаемое_свидетельство,
                пространство.приёмочные_раунды,
                пространство.исходный_коммит_раундов,
                требовать_выбор_первой_схемы=True,
                обычная_схема_профиля=пространство.обычная_схема_профиля,
            )
        if пространство.подкоманда == "предпросмотр":
            return выполнить_предпросмотр(
                пространство.корень_репозитория,
                пространство.запрос,
            )
        if пространство.подкоманда == "проверить-план":
            return выполнить_проверку_плана(
                пространство.корень_репозитория,
                пространство.запрос,
            )
        if пространство.подкоманда == "закрыть":
            return выполнить_закрытие(
                пространство.корень_репозитория,
                пространство.запрос,
            )
        if пространство.подкоманда == "возобновить":
            return выполнить_возобновление(
                пространство.корень_репозитория,
                пространство.запрос,
            )
        ошибки = проверить_журнал_сессии(
            пространство.корень_репозитория,
            пространство.запрос,
        )
        if ошибки:
            raise ОшибкаОтчёта("; ".join(ошибки))
        print("проверка отчёта о запусках проверок пройдена")
        return 0
    except ОшибкаОтчёта as ошибка:
        print(str(ошибка), file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(главная())
